INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-001', 'CET4', 'abandon', '/əˈbændən/', 'v.', '放弃；抛弃；遗弃', 'The crew had to abandon the sinking ship in the heavy storm.', '在狂风暴雨中，船员们不得不弃船逃生。', '四级听力·长对话', '1', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-002', 'CET4', 'abolish', '/əˈbɒlɪʃ/', 'v.', '废除；废止（法律、制度等）', 'Many countries have abolished the death penalty.', '许多国家已经废除了死刑。', '六级阅读·法律类', '2', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-003', 'CET4', 'abrupt', '/əˈbrʌpt/', 'adj.', '突然的；意外的；（态度）粗鲁的', 'The meeting came to an abrupt end without any agreement.', '会议突然结束，没有达成任何协议。', '六级完形·新闻类', '3', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-004', 'CET4', 'absolute', '/ˈæbsəluːt/', 'adj.', '绝对的；完全的；专制的', 'There is no absolute answer to this question.', '这个问题没有绝对的答案。', '必背核心·高频词', '4', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-005', 'CET4', 'absorb', '/əbˈsɔːb/', 'v.', '吸收；理解；使全神贯注', 'Plants absorb carbon dioxide from the air and release oxygen.', '植物从空气中吸收二氧化碳并释放氧气。', '四级阅读·科普类', '5', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-006', 'CET4', 'abstract', '/ˈæbstrækt/', 'adj./n./v.', '抽象的；摘要；提取', 'The idea is too abstract for young children.', '这个概念对小孩子来说太抽象了。', '必背核心·高频词', '6', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-007', 'CET4', 'absurd', '/əbˈsɜːd/', 'adj.', '荒谬的；荒唐的', 'It is absurd to blame technology for every social problem.', '把一切社会问题都归咎于技术是荒谬的。', '六级阅读·评论类', '7', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-008', 'CET4', 'abundant', '/əˈbʌndənt/', 'adj.', '丰富的；充裕的', 'The region is abundant in natural resources.', '该地区自然资源丰富。', '六级阅读·经济类', '8', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-009', 'CET4', 'academic', '/ˌækəˈdemɪk/', 'adj.', '学术的；学业的', 'Her academic performance has improved steadily since last term.', '自上学期以来，她的学业成绩稳步提高。', '四级阅读·教育类', '9', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-010', 'CET4', 'accelerate', '/əkˈseləreɪt/', 'v.', '加速；促进', 'Technology has accelerated the pace of social change.', '技术加快了社会变革的步伐。', '六级写作·科技类', '10', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-011', 'CET4', 'access', '/ˈækses/', 'n./v.', '通道；使用权；获取', 'Students now have free access to the university’s online library.', '学生现在可以免费使用学校的在线图书馆。', '四级阅读·校园类', '11', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-012', 'CET4', 'accompany', '/əˈkʌmpəni/', 'v.', '陪伴；伴随；为…伴奏', 'Children under twelve must be accompanied by an adult.', '十二岁以下儿童必须有成人陪同。', '四级阅读·公告类', '12', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-013', 'CET4', 'accomplish', '/əˈkʌmplɪʃ/', 'v.', '完成；实现', 'She accomplished more in one year than most people do in five.', '她一年里取得的成就比多数人五年还多。', '四级阅读·人物类', '13', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-014', 'CET4', 'accumulate', '/əˈkjuːmjəleɪt/', 'v.', '积累；积聚', 'She accumulated a great deal of experience abroad.', '她在国外积累了大量经验。', '必背核心·高频词', '14', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-015', 'CET4', 'accurate', '/ˈækjərət/', 'adj.', '准确的；精确的', 'The report gives an accurate description of the local economy.', '该报告准确描述了当地经济状况。', '四级阅读·经济类', '15', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-016', 'CET4', 'accuse', '/əˈkjuːz/', 'v.', '指控；控告；指责', 'He was accused of stealing the money.', '他被指控偷了那笔钱。', '必背核心·高频词', '16', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-017', 'CET4', 'accustom', '/əˈkʌstəm/', 'v.', '使习惯于', 'It took him months to accustom himself to the climate.', '他花了几个月才适应那里的气候。', '必背核心·高频词', '17', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-018', 'CET4', 'achieve', '/əˈtʃiːv/', 'v.', '实现；达到；取得', 'Only a small number of people achieve their childhood dreams.', '只有少数人实现了儿时的梦想。', '四级阅读·社会类', '18', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-019', 'CET4', 'acknowledge', '/əkˈnɒlɪdʒ/', 'v.', '承认；致谢；告知收到', 'He refused to acknowledge that he had made a mistake.', '他拒不承认自己犯了错。', '六级阅读·社会类', '19', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-020', 'CET4', 'acquire', '/əˈkwaɪə(r)/', 'v.', '获得；习得；养成', 'Children acquire their first language without formal teaching.', '儿童无需正式教学就能习得母语。', '四级阅读·语言类', '20', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-021', 'CET4', 'acute', '/əˈkjuːt/', 'adj.', '严重的；敏锐的；急性的', 'The city is facing an acute shortage of clean water.', '这座城市面临严重的清洁用水短缺。', '六级阅读·环境类', '21', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-022', 'CET4', 'adapt', '/əˈdæpt/', 'v.', '适应；改编', 'It took him months to adapt to the new working environment.', '他花了好几个月才适应新的工作环境。', '四级完形·职场类', '22', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-023', 'CET4', 'adequate', '/ˈædɪkwət/', 'adj.', '足够的；适当的', 'The room is adequate for two people but not for a family.', '这房间住两个人足够，住一家人不够。', '四级阅读·生活类', '23', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-024', 'CET4', 'adhere', '/ədˈhɪə(r)/', 'v.', '坚持；遵守；粘附', 'All members must adhere to the club’s rules.', '所有成员都必须遵守俱乐部的规定。', '六级完形·规则类', '24', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-025', 'CET4', 'adjust', '/əˈdʒʌst/', 'v.', '调整；适应', 'You may adjust the seat to a comfortable position.', '你可以把座椅调整到舒适的位置。', '四级听力·短篇新闻', '25', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-026', 'CET4', 'admire', '/ədˈmaɪə(r)/', 'v.', '钦佩；欣赏', 'I have always admired her courage to start over at fifty.', '我一直很佩服她五十岁重新开始的勇气。', '四级阅读·人物类', '26', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-027', 'CET4', 'adopt', '/əˈdɒpt/', 'v.', '采用；采取；收养', 'The company decided to adopt a more flexible working system.', '公司决定采用更灵活的工作制度。', '四级阅读·职场类', '27', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
