  ('cet4-031', 'CET4', 'aesthetic', '/iːsˈθetɪk/', 'adj./n.', '审美的；美学的；美感', 'The building is praised for its aesthetic value.', '这座建筑因其美学价值而受到称赞。', '六级阅读·艺术类', '31', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-032', 'CET4', 'affect', '/əˈfekt/', 'v.', '影响；感动', 'Lack of sleep can seriously affect your memory.', '睡眠不足会严重影响你的记忆力。', '四级阅读·健康类', '32', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
