  ('cet4-049', 'CET4', 'anonymous', '/əˈnɒnɪməs/', 'adj.', '匿名的；无名的', 'The article was written by an anonymous author.', '这篇文章出自一位匿名作者之手。', '六级阅读·传媒类', '49', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
