  ('cet4-189', 'CET4', 'entail', '/ɪnˈteɪl/', 'v.', '需要；牵涉；使必要', 'The job entails a lot of responsibility.', '这份工作需要承担很多责任。', '六级阅读·职场类', '189', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-190', 'CET4', 'environment', '/ɪnˈvaɪrənmənt/', 'n.', '环境；自然环境', 'We should protect the environment for future generations.', '我们应为子孙后代保护环境。', '四级写作·环保类', '190', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-191', 'CET4', 'envision', '/ɪnˈvɪʒn/', 'v.', '设想；展望', 'Few people envisioned such rapid progress.', '很少有人预见到如此迅速的进展。', '六级写作·科技类', '191', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-192', 'CET4', 'epidemic', '/ˌepɪˈdemɪk/', 'n./adj.', '流行病；蔓延的', 'Obesity has become a global epidemic.', '肥胖已成为一种全球性流行病。', '六级阅读·健康类', '192', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-193', 'CET4', 'erode', '/ɪˈrəʊd/', 'v.', '侵蚀；腐蚀；削弱', 'Constant criticism eroded her confidence.', '不断的批评削弱了她的自信。', '六级阅读·心理类', '193', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-194', 'CET4', 'essential', '/ɪˈsenʃl/', 'adj./n.', '必要的；本质的；要素', 'Sleep is essential to both physical and mental health.', '睡眠对身心健康都必不可少。', '四级阅读·健康类', '194', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-195', 'CET4', 'establish', '/ɪˈstæblɪʃ/', 'v.', '建立；创立；确定', 'The school was established more than a century ago.', '这所学校建立于一个多世纪前。', '四级阅读·教育类', '195', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-196', 'CET4', 'estimate', '/ˈestɪmeɪt/', 'v./n.', '估计；估价', 'Experts estimate that the damage will reach ten million dollars.', '专家估计损失将达到一千万美元。', '四级阅读·新闻类', '196', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-197', 'CET4', 'evaluate', '/ɪˈvæljueɪt/', 'v.', '评价；评估', 'Students are asked to evaluate their own progress each month.', '学生被要求每月评估自己的进步。', '四级阅读·教育类', '197', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-198', 'CET4', 'evidence', '/ˈevɪdəns/', 'n.', '证据；迹象', 'There is growing evidence that exercise improves memory.', '越来越多的证据表明锻炼能改善记忆力。', '四级阅读·健康类', '198', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-199', 'CET4', 'exacerbate', '/ɪɡˈzæsəbeɪt/', 'v.', '使恶化；加剧', 'The drought exacerbated the food shortage.', '干旱加剧了粮食短缺。', '六级阅读·环境类', '199', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-200', 'CET4', 'exaggerate', '/ɪɡˈzædʒəreɪt/', 'v.', '夸大；夸张', 'The report exaggerates the risks involved.', '报告夸大了其中的风险。', '六级阅读·传媒类', '200', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-201', 'CET4', 'exclusive', '/ɪkˈskluːsɪv/', 'adj./n.', '独家的；排外的；专访', 'The magazine obtained an exclusive interview.', '该杂志获得了独家专访。', '六级阅读·传媒类', '201', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-202', 'CET4', 'exert', '/ɪɡˈzɜːt/', 'v.', '施加；运用；努力', 'Parents exert a strong influence on children.', '父母对孩子施加强大的影响。', '六级写作·家庭类', '202', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-203', 'CET4', 'exotic', '/ɪɡˈzɒtɪk/', 'adj.', '异国的；外来的；奇异的', 'The market sells a variety of exotic fruits.', '市场出售各种异国水果。', '六级阅读·文化类', '203', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-204', 'CET4', 'expand', '/ɪkˈspænd/', 'v.', '扩大；膨胀；扩展', 'The company plans to expand its business into Asia.', '公司计划把业务扩展到亚洲。', '四级阅读·商业类', '204', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-205', 'CET4', 'expenditure', '/ɪkˈspendɪtʃə(r)/', 'n.', '支出；消耗；经费', 'Public expenditure on education has risen sharply.', '公共教育支出大幅上升。', '六级阅读·经济类', '205', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-206', 'CET4', 'expertise', '/ˌekspɜːˈtiːz/', 'n.', '专业知识；专长', 'We value his expertise in financial management.', '我们看重他在财务管理方面的专长。', '六级阅读·职场类', '206', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-207', 'CET4', 'explicit', '/ɪkˈsplɪsɪt/', 'adj.', '明确的；清楚的；直言的', 'The contract is explicit about payment terms.', '合同对付款条件有明确规定。', '六级阅读·法律类', '207', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-208', 'CET4', 'exploit', '/ɪkˈsplɔɪt/', 'v./n.', '利用；剥削；功绩', 'Companies should not exploit cheap labour.', '公司不应剥削廉价劳动力。', '六级阅读·社会类', '208', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-209', 'CET4', 'extract', '/ɪkˈstrækt/', 'v./n.', '提取；摘录；摘录片段', 'Scientists extracted DNA from the ancient bone.', '科学家从这块古骨中提取了DNA。', '六级阅读·科研类', '209', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-210', 'CET4', 'fabricate', '/ˈfæbrɪkeɪt/', 'v.', '捏造；伪造；制造', 'The evidence was later shown to be fabricated.', '该证据后来被证明是伪造的。', '六级阅读·法律类', '210', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-211', 'CET4', 'facility', '/fəˈsɪləti/', 'n.', '设施；设备；便利', 'The school has excellent sports facilities.', '这所学校有出色的体育设施。', '四级阅读·校园类', '211', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-212', 'CET4', 'factor', '/ˈfæktə(r)/', 'n.', '因素；要素', 'Cost is the key factor in choosing a supplier.', '成本是选择供应商的关键因素。', '四级阅读·经济类', '212', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-213', 'CET4', 'faculty', '/ˈfæklti/', 'n.', '全体教员；院系；能力', 'The faculty members meet every Monday morning.', '全体教员每周一上午开会。', '四级阅读·教育类', '213', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-214', 'CET4', 'failure', '/ˈfeɪljə(r)/', 'n.', '失败；故障；失败者', 'He regarded the setback as a lesson rather than a failure.', '他把这次挫折看作教训而非失败。', '四级写作·成长类', '214', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-215', 'CET4', 'faint', '/feɪnt/', 'adj./v.', '微弱的；模糊的；昏倒', 'There is still a faint hope of finding survivors.', '找到幸存者仍有一线希望。', '四级阅读·新闻类', '215', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-216', 'CET4', 'faith', '/feɪθ/', 'n.', '信任；信念；信心', 'She has great faith in her students’ abilities.', '她对学生的能力充满信心。', '四级阅读·教育类', '216', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-217', 'CET4', 'fallacy', '/ˈfæləsi/', 'n.', '谬误；谬见', 'The belief that success comes overnight is a fallacy.', '认为成功是一夜之间到来的想法是一种谬见。', '六级写作·励志类', '217', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-218', 'CET4', 'familiar', '/fəˈmɪliə(r)/', 'adj.', '熟悉的；常见的', 'His face looks familiar, but I can’t recall his name.', '他看起来面熟，但我想不起名字。', '四级听力·长对话', '218', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-219', 'CET4', 'fancy', '/ˈfænsi/', 'adj./v./n.', '花哨的；喜欢；幻想', 'We don’t need a fancy car, just a reliable one.', '我们不需要花哨的车，可靠的就行。', '四级阅读·消费类', '219', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-220', 'CET4', 'fare', '/feə(r)/', 'n.', '车费；票价；伙食', 'Bus fares will rise by ten percent next month.', '公交票价下月将上涨百分之十。', '四级阅读·民生类', '220', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-221', 'CET4', 'fascinate', '/ˈfæsɪneɪt/', 'v.', '使着迷；吸引', 'The way children learn language fascinates researchers.', '儿童学习语言的方式令研究者着迷。', '六级阅读·语言类', '221', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-222', 'CET4', 'fashion', '/ˈfæʃn/', 'n.', '时尚；方式；流行', 'Fast fashion has caused serious environmental problems.', '快时尚造成了严重的环境问题。', '四级阅读·环境类', '222', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-223', 'CET4', 'fatal', '/ˈfeɪtl/', 'adj.', '致命的；毁灭性的', 'The accident was fatal to two of the passengers.', '事故对其中两名乘客是致命的。', '四级听力·短篇新闻', '223', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-224', 'CET4', 'fault', '/fɔːlt/', 'n.', '过错；缺点；故障', 'It was nobody’s fault that the flight was delayed.', '航班延误不是任何人的过错。', '四级阅读·生活类', '224', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-225', 'CET4', 'feasible', '/ˈfiːzəbl/', 'adj.', '可行的；行得通的', 'Building a new library here is feasible within two years.', '两年内在这里建一座新图书馆是可行的。', '四级阅读·校园类', '225', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-226', 'CET4', 'feature', '/ˈfiːtʃə(r)/', 'n./v.', '特征；特色；以…为特色', 'The phone features a much longer battery life.', '这款手机的特点是续航更久。', '四级阅读·科技类', '226', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-227', 'CET4', 'federal', '/ˈfedərəl/', 'adj.', '联邦的；联邦政府的', 'The federal government announced new education funding.', '联邦政府宣布了新的教育拨款。', '四级阅读·政治类', '227', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-228', 'CET4', 'fee', '/fiː/', 'n.', '费用；酬金', 'The university has raised tuition fees again.', '这所大学再次提高了学费。', '四级阅读·教育类', '228', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-229', 'CET4', 'feedback', '/ˈfiːdbæk/', 'n.', '反馈；意见', 'Teachers gave detailed feedback on each student’s essay.', '老师对每位学生的作文给出了详细反馈。', '四级阅读·教育类', '229', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-230', 'CET4', 'fellow', '/ˈfeləʊ/', 'adj./n.', '同伴的；同事；家伙', 'Her fellow students voted her class president.', '她的同学选她当班长。', '四级阅读·校园类', '230', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-231', 'CET4', 'fertile', '/ˈfɜːtaɪl/', 'adj.', '肥沃的；富饶的；多产的', 'The river valley has very fertile soil.', '这条河谷土壤非常肥沃。', '四级阅读·地理类', '231', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-232', 'CET4', 'fiction', '/ˈfɪkʃn/', 'n.', '小说；虚构', 'Science fiction often predicts future technology.', '科幻小说常常预言未来技术。', '四级阅读·文化类', '232', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-233', 'CET4', 'fierce', '/fɪəs/', 'adj.', '激烈的；凶猛的；强烈的', 'Competition among tech companies is fierce.', '科技公司之间的竞争很激烈。', '四级阅读·经济类', '233', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-234', 'CET4', 'figure', '/ˈfɪɡə(r)/', 'n./v.', '数字；人物；身材；认为', 'Recent figures show a drop in unemployment.', '最新数据显示失业率下降。', '四级阅读·经济类', '234', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-235', 'CET4', 'filter', '/ˈfɪltə(r)/', 'v./n.', '过滤；筛选；过滤器', 'The app can filter out unwanted messages.', '这个应用能过滤掉不需要的信息。', '四级阅读·科技类', '235', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-236', 'CET4', 'finance', '/ˈfaɪnæns/', 'n./v.', '财政；金融；资助', 'He studied finance and now works in a bank.', '他学金融，现在在银行工作。', '四级阅读·职场类', '236', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-237', 'CET4', 'flame', '/fleɪm/', 'n.', '火焰；热情', 'The dry wood caught flame in seconds.', '干木几秒钟就烧了起来。', '四级阅读·新闻类', '237', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-238', 'CET4', 'flash', '/flæʃ/', 'v./n.', '闪光；闪现；一瞬间', 'A bright light flashed across the sky.', '一道亮光划过天空。', '四级阅读·科普类', '238', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-239', 'CET4', 'flee', '/fliː/', 'v.', '逃离；逃避', 'Thousands of people fled the flooded area.', '成千上万人逃离了洪水地区。', '四级听力·短篇新闻', '239', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-240', 'CET4', 'flexible', '/ˈfleksəbl/', 'adj.', '灵活的；可弯曲的', 'Flexible working hours help employees balance family and work.', '弹性工作时间帮助员工平衡家庭与工作。', '四级写作·职场类', '240', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-241', 'CET4', 'fluctuate', '/ˈflʌktʃueɪt/', 'v.', '波动；起伏；动摇', 'Prices fluctuated wildly last year.', '去年物价剧烈波动。', '六级阅读·经济类', '241', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-242', 'CET4', 'fluent', '/ˈfluːənt/', 'adj.', '流利的；流畅的', 'She is fluent in three foreign languages.', '她能流利地说三门外语。', '四级写作·教育类', '242', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-243', 'CET4', 'focus', '/ˈfəʊkəs/', 'v./n.', '集中；焦点；关注', 'You need to focus on the most important tasks.', '你需要把注意力集中在最重要的任务上。', '四级写作·学习类', '243', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-244', 'CET4', 'forbid', '/fəˈbɪd/', 'v.', '禁止；不许', 'The rules forbid students from using phones in class.', '规定禁止学生在课堂上使用手机。', '四级阅读·校园类', '244', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-245', 'CET4', 'forecast', '/ˈfɔːkɑːst/', 'n./v.', '预报；预测', 'The weather forecast says it will rain tomorrow.', '天气预报说明天会下雨。', '四级听力·短篇新闻', '245', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-246', 'CET4', 'foreign', '/ˈfɒrən/', 'adj.', '外国的；外来的；陌生的', 'Learning a foreign language takes time and patience.', '学一门外语需要时间和耐心。', '四级写作·教育类', '246', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-247', 'CET4', 'foresee', '/fɔːˈsiː/', 'v.', '预见；预知', 'Nobody could foresee the consequences of the decision.', '没有人能预见这个决定的后果。', '六级阅读·历史类', '247', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-248', 'CET4', 'forgive', '/fəˈɡɪv/', 'v.', '原谅；宽恕', 'It is easier to forgive others than to forgive oneself.', '原谅别人比原谅自己容易。', '四级阅读·心理类', '248', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-249', 'CET4', 'formal', '/ˈfɔːml/', 'adj.', '正式的；正规的', 'The invitation requires formal dress.', '这个邀请要求穿正装。', '四级阅读·文化类', '249', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-250', 'CET4', 'former', '/ˈfɔːmə(r)/', 'adj.', '以前的前者的', 'The former manager now runs her own company.', '前任经理现在经营自己的公司。', '四级阅读·职场类', '250', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-251', 'CET4', 'formulate', '/ˈfɔːmjuleɪt/', 'v.', '制定；规划；系统地阐述', 'The team formulated a detailed plan within a week.', '团队在一周内制定了详细计划。', '六级阅读·管理类', '251', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-252', 'CET4', 'fortune', '/ˈfɔːtʃuːn/', 'n.', '财富；运气；命运', 'He made a fortune by investing in technology.', '他靠投资科技发了财。', '四级阅读·人物类', '252', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-253', 'CET4', 'found', '/faʊnd/', 'v.', '建立；创立；创办', 'The school was founded more than a century ago.', '这所学校建立于一个多世纪前。', '四级阅读·教育类', '253', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-254', 'CET4', 'fragile', '/ˈfrædʒaɪl/', 'adj.', '脆弱的；易碎的', 'The region’s economy remains fragile.', '该地区的经济依然脆弱。', '六级阅读·经济类', '254', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-255', 'CET4', 'frame', '/freɪm/', 'n./v.', '框架；结构；给…镶框', 'The window frame was damaged in the storm.', '窗框在暴风雨中受损。', '四级阅读·生活类', '255', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-256', 'CET4', 'freedom', '/ˈfriːdəm/', 'n.', '自由；自主', 'Many people value freedom over high salary.', '许多人看重自由胜过高薪。', '四级写作·职场类', '256', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-257', 'CET4', 'freeze', '/friːz/', 'v.', '冻结；结冰；愣住', 'Water freezes at zero degrees Celsius.', '水在零摄氏度结冰。', '四级阅读·科普类', '257', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
