  ('cet4-266', 'CET4', 'gain', '/ɡeɪn/', 'v./n.', '获得；增加；收益', 'She gained valuable experience during the internship.', '她在实习期间获得了宝贵经验。', '必背核心·高频词', '266', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-267', 'CET4', 'gallery', '/ˈɡæləri/', 'n.', '画廊；美术馆；走廊', 'The gallery displays works by young local artists.', '这家画廊展出本地年轻艺术家的作品。', '必背核心·高频词', '267', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-268', 'CET4', 'gamble', '/ˈɡæmbl/', 'v./n.', '赌博；冒险', 'He gambled all his savings on a risky business venture.', '他把全部积蓄押在了一场冒险的生意上。', '必背核心·高频词', '268', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-269', 'CET4', 'gang', '/ɡæŋ/', 'n.', '一伙；帮派；一群', 'A gang of teenagers was hanging around the entrance.', '一群青少年在入口处闲逛。', '必背核心·高频词', '269', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-270', 'CET4', 'gap', '/ɡæp/', 'n.', '差距；缺口；间隔', 'There is still a wide gap between rich and poor regions.', '富裕地区与贫困地区之间仍有巨大差距。', '必背核心·高频词', '270', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-271', 'CET4', 'garbage', '/ˈɡɑːbɪdʒ/', 'n.', '垃圾；废物', 'The city collects garbage twice a week.', '这座城市每周清运两次垃圾。', '必背核心·高频词', '271', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-272', 'CET4', 'gather', '/ˈɡæðə(r)/', 'v.', '聚集；收集；推测', 'Volunteers gathered at the square before dawn.', '志愿者们在天亮前聚集在广场上。', '必背核心·高频词', '272', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-273', 'CET4', 'gaze', '/ɡeɪz/', 'v./n.', '凝视；注视', 'She gazed out of the window, lost in thought.', '她凝视窗外，陷入沉思。', '必背核心·高频词', '273', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-274', 'CET4', 'gear', '/ɡɪə(r)/', 'n./v.', '齿轮；装备；使适应', 'The company is gearing up for its biggest launch yet.', '公司正在为迄今最大的一场发布做准备。', '必背核心·高频词', '274', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-275', 'CET4', 'generalize', '/ˈdʒenrəlaɪz/', 'v.', '概括；归纳；推广', 'We should not generalize from a single case.', '我们不应从单一案例中进行概括。', '六级阅读·科研类', '275', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-276', 'CET4', 'generate', '/ˈdʒenəreɪt/', 'v.', '产生；生成；发（电）', 'Wind can be used to generate electricity cheaply.', '风能可用来廉价发电。', '四级阅读·环保类', '276', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-277', 'CET4', 'generous', '/ˈdʒenərəs/', 'adj.', '慷慨的；宽宏大量的', 'He was generous with both his time and his money.', '他在时间和金钱上都很慷慨。', '必背核心·高频词', '277', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-278', 'CET4', 'genetic', '/dʒəˈnetɪk/', 'adj.', '遗传的；基因的', 'Genetic factors partly explain why people differ in height.', '遗传因素部分解释了人们身高的差异。', '必背核心·高频词', '278', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-279', 'CET4', 'genius', '/ˈdʒiːniəs/', 'n.', '天才；天赋', 'Many people called him a genius, but he credited hard work.', '许多人称他为天才，但他归功于努力。', '必背核心·高频词', '279', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-280', 'CET4', 'gentle', '/ˈdʒentl/', 'adj.', '温和的；轻柔的', 'A gentle breeze moved the curtains.', '一阵微风拂动了窗帘。', '必背核心·高频词', '280', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-281', 'CET4', 'genuine', '/ˈdʒenjuɪn/', 'adj.', '真正的；真诚的', 'She showed genuine concern for the people in need.', '她对需要帮助的人表现出真诚的关切。', '四级完形·人物类', '281', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-282', 'CET4', 'gesture', '/ˈdʒestʃə(r)/', 'n./v.', '手势；姿态；做手势', 'His offer was a gesture of goodwill.', '他的提议是一种善意的姿态。', '必背核心·高频词', '282', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
