  ('cet4-284', 'CET4', 'glare', '/ɡleə(r)/', 'v./n.', '怒视；刺眼的强光', 'The screen glare made it hard to read.', '屏幕反光让人难以阅读。', '必背核心·高频词', '284', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-285', 'CET4', 'glimpse', '/ɡlɪmps/', 'n./v.', '一瞥；瞥见', 'We only caught a glimpse of the famous actor.', '我们只瞥见了那位著名演员一眼。', '必背核心·高频词', '285', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-286', 'CET4', 'global', '/ˈɡləʊbəl/', 'adj.', '全球的；全世界的', 'Climate change is a global challenge, not a local one.', '气候变化是全球性挑战，而非局部问题。', '必背核心·高频词', '286', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-287', 'CET4', 'gloomy', '/ˈɡluːmi/', 'adj.', '阴沉的；忧郁的；前景黯淡的', 'The forecast for the industry remains gloomy.', '该行业的前景依然黯淡。', '必背核心·高频词', '287', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-288', 'CET4', 'glory', '/ˈɡlɔːri/', 'n.', '光荣；荣耀；壮丽', 'The team is determined to regain its former glory.', '这支队伍决心重拾昔日的荣耀。', '必背核心·高频词', '288', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-289', 'CET4', 'glow', '/ɡləʊ/', 'v./n.', '发光；发热；光辉', 'The street lamps glowed softly in the fog.', '路灯在雾中发出柔和的光。', '必背核心·高频词', '289', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-290', 'CET4', 'govern', '/ˈɡʌvn/', 'v.', '统治；管理；支配', 'The country is governed by an elected parliament.', '这个国家由选举产生的议会治理。', '必背核心·高频词', '290', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-291', 'CET4', 'grab', '/ɡræb/', 'v.', '抓住；夺取；抓紧', 'He grabbed his coat and rushed out of the door.', '他抓起外套冲出门去。', '必背核心·高频词', '291', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-292', 'CET4', 'gradual', '/ˈɡrædʒuəl/', 'adj.', '逐渐的；渐进的', 'There has been a gradual improvement in air quality.', '空气质量已逐步改善。', '必背核心·高频词', '292', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-293', 'CET4', 'graduate', '/ˈɡrædʒueɪt/', 'v./n.', '毕业；毕业生', 'She graduated with honours in economics.', '她以优异成绩从经济学专业毕业。', '必背核心·高频词', '293', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-294', 'CET4', 'grain', '/ɡreɪn/', 'n.', '谷物；颗粒；纹理', 'The region produces most of the country’s grain.', '该地区生产全国大部分谷物。', '必背核心·高频词', '294', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-295', 'CET4', 'grand', '/ɡrænd/', 'adj.', '宏伟的；盛大的；重大的', 'The museum’s grand hall was packed with visitors.', '博物馆宏大的大厅里挤满了参观者。', '必背核心·高频词', '295', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-296', 'CET4', 'grant', '/ɡrɑːnt/', 'v./n.', '授予；同意；补助金', 'The university granted him a full scholarship.', '大学给了他全额奖学金。', '必背核心·高频词', '296', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-297', 'CET4', 'graph', '/ɡrɑːf/', 'n.', '图表；曲线图', 'The graph shows a sharp rise in online sales.', '这张图表显示网上销售急剧上升。', '必背核心·高频词', '297', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-298', 'CET4', 'grasp', '/ɡrɑːsp/', 'v./n.', '抓住；理解；掌握', 'It took me a while to grasp the main idea.', '我花了一段时间才理解主旨。', '必背核心·高频词', '298', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-299', 'CET4', 'grateful', '/ˈɡreɪtfl/', 'adj.', '感激的；感谢的', 'I am extremely grateful for all your help.', '我非常感谢你的所有帮助。', '必背核心·高频词', '299', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-300', 'CET4', 'grave', '/ɡreɪv/', 'n./adj.', '坟墓；严重的；严肃的', 'The situation poses a grave threat to public health.', '这一局势对公众健康构成严重威胁。', '必背核心·高频词', '300', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-301', 'CET4', 'greedy', '/ˈɡriːdi/', 'adj.', '贪婪的；贪吃的', 'Greedy investors ignored the obvious risks.', '贪婪的投资者忽视了明显的风险。', '必背核心·高频词', '301', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-302', 'CET4', 'greet', '/ɡriːt/', 'v.', '问候；迎接；受到…对待', 'The proposal was greeted with loud applause.', '这项提议赢得了热烈掌声。', '必背核心·高频词', '302', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-303', 'CET4', 'grief', '/ɡriːf/', 'n.', '悲伤；悲痛', 'She never fully recovered from the grief of losing him.', '她始终没能从失去他的悲痛中走出来。', '必背核心·高频词', '303', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-304', 'CET4', 'grim', '/ɡrɪm/', 'adj.', '严峻的；冷酷的；阴森的', 'The report paints a grim picture of the job market.', '这份报告描绘了一幅严峻的就业市场图景。', '必背核心·高频词', '304', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-305', 'CET4', 'grip', '/ɡrɪp/', 'v./n.', '紧握；控制；理解', 'The recession has a firm grip on the housing market.', '经济衰退紧紧笼罩着房地产市场。', '必背核心·高频词', '305', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-306', 'CET4', 'gross', '/ɡrəʊs/', 'adj./v.', '总的；明显的；恶劣的', 'The company’s gross profit rose by twelve percent.', '公司的毛利润增长了百分之十二。', '必背核心·高频词', '306', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-307', 'CET4', 'guarantee', '/ˌɡærənˈtiː/', 'v./n.', '保证；担保', 'A good education does not guarantee a well-paid job.', '良好的教育并不保证高薪工作。', '四级写作·教育类', '307', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-308', 'CET4', 'guard', '/ɡɑːd/', 'v./n.', '守卫；保卫；警卫', 'Guards patrol the building around the clock.', '警卫昼夜在大楼里巡逻。', '必背核心·高频词', '308', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-309', 'CET4', 'guidance', '/ˈɡaɪdns/', 'n.', '指导；引导', 'The project was completed under expert guidance.', '该项目在专家指导下完成。', '必背核心·高频词', '309', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-310', 'CET4', 'guilty', '/ˈɡɪlti/', 'adj.', '有罪的；内疚的', 'He felt guilty about missing his daughter’s birthday.', '他因错过女儿的生日而感到内疚。', '必背核心·高频词', '310', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-311', 'CET4', 'habit', '/ˈhæbɪt/', 'n.', '习惯；习性', 'Reading before bed is a habit worth developing.', '睡前阅读是值得养成的习惯。', '必背核心·高频词', '311', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-312', 'CET4', 'hail', '/heɪl/', 'v./n.', '赞扬；冰雹；招呼', 'The new policy was hailed as a major breakthrough.', '这项新政策被誉为重大突破。', '必背核心·高频词', '312', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
