  ('cet4-379', 'CET4', 'immerse', '/ɪˈmɜːs/', 'v.', '使沉浸；使浸入', 'She immersed herself in the study of history.', '她潜心研究历史。', '六级阅读·学习类', '379', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-380', 'CET4', 'immune', '/ɪˈmjuːn/', 'adj.', '免疫的；免除的；不受影响的', 'No one is immune to the effects of stress.', '没有人能免受压力的影响。', '六级阅读·健康类', '380', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-381', 'CET4', 'impair', '/ɪmˈpeə(r)/', 'v.', '损害；削弱', 'Lack of sleep impairs your ability to concentrate.', '睡眠不足会削弱你的专注能力。', '六级阅读·健康类', '381', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-382', 'CET4', 'imperative', '/ɪmˈperətɪv/', 'adj./n.', '必要的；紧急的；祈使语气', 'Immediate action is imperative.', '立即采取行动是当务之急。', '六级写作·环保类', '382', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-383', 'CET4', 'impetus', '/ˈɪmpɪtəs/', 'n.', '推动力；促进；刺激', 'The reform gave new impetus to the economy.', '改革给经济带来了新的推动力。', '六级阅读·经济类', '383', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-384', 'CET4', 'implement', '/ˈɪmplɪment/', 'v./n.', '实施；执行；工具', 'The new rules will be implemented next semester.', '新规定将于下学期实施。', '四级阅读·校园类', '384', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-385', 'CET4', 'implicit', '/ɪmˈplɪsɪt/', 'adj.', '含蓄的；隐含的；绝对的', 'His silence carried an implicit criticism.', '他的沉默含有含蓄的批评。', '六级阅读·语言类', '385', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-386', 'CET4', 'imply', '/ɪmˈplaɪ/', 'v.', '暗示；意味着', 'His silence implied that he disagreed.', '他的沉默暗示他不同意。', '必背核心·高频词', '386', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-387', 'CET4', 'impose', '/ɪmˈpəʊz/', 'v.', '强加；征收；推行', 'The city imposed a tax on plastic bags.', '该市对塑料袋征税。', '必背核心·高频词', '387', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-388', 'CET4', 'impress', '/ɪmˈpres/', 'v.', '使印象深刻；使铭记', 'She impressed the interviewers with her confidence.', '她的自信给面试官留下深刻印象。', '必背核心·高频词', '388', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-389', 'CET4', 'improve', '/ɪmˈpruːv/', 'v.', '改善；提高；改进', 'Regular exercise improves both health and mood.', '规律运动能改善健康和情绪。', '必背核心·高频词', '389', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-390', 'CET4', 'incentive', '/ɪnˈsentɪv/', 'n.', '激励；刺激；动机', 'Tax breaks provide an incentive to invest.', '税收减免提供了投资激励。', '六级阅读·经济类', '390', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-391', 'CET4', 'incidence', '/ˈɪnsɪdəns/', 'n.', '发生率；影响范围', 'The incidence of the disease has fallen sharply.', '这种疾病的发病率大幅下降。', '六级阅读·医疗类', '391', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-392', 'CET4', 'incident', '/ˈɪnsɪdənt/', 'n.', '事件；事故', 'The incident was reported to the police at once.', '该事件立即被报告给了警方。', '必背核心·高频词', '392', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-393', 'CET4', 'income', '/ˈɪnkʌm/', 'n.', '收入；所得', 'Families on a low income struggle to pay rent.', '低收入家庭难以支付房租。', '必背核心·高频词', '393', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-394', 'CET4', 'incorporate', '/ɪnˈkɔːpəreɪt/', 'v.', '包含；纳入；合并', 'The new design incorporates many traditional elements.', '新设计融入了许多传统元素。', '六级阅读·文化类', '394', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-395', 'CET4', 'incredible', '/ɪnˈkredəbl/', 'adj.', '难以置信的；极好的', 'The team made an incredible comeback in the second half.', '该队下半场上演了不可思议的逆转。', '必背核心·高频词', '395', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-396', 'CET4', 'incur', '/ɪnˈkɜː(r)/', 'v.', '招致；遭受；蒙受', 'Late payment will incur a small charge.', '逾期付款会产生少量费用。', '六级阅读·商业类', '396', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-397', 'CET4', 'independence', '/ˌɪndɪˈpendəns/', 'n.', '独立；自主', 'The country gained independence in 1960.', '该国于1960年获得独立。', '必背核心·高频词', '397', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-398', 'CET4', 'index', '/ˈɪndeks/', 'n./v.', '索引；指数；为…编索引', 'The cost-of-living index rose again last month.', '生活成本指数上个月再次上涨。', '必背核心·高频词', '398', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-399', 'CET4', 'indicate', '/ˈɪndɪkeɪt/', 'v.', '表明；指出；示意', 'Recent studies indicate a sharp rise in online shopping.', '近期研究显示网上购物急剧增长。', '四级阅读·商业类', '399', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-400', 'CET4', 'indigenous', '/ɪnˈdɪdʒənəs/', 'adj.', '本土的；土生土长的', 'The plant is indigenous to South America.', '这种植物原产于南美洲。', '六级阅读·环境类', '400', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-401', 'CET4', 'individual', '/ˌɪndɪˈvɪdʒuəl/', 'n./adj.', '个人；个别的；独特的', 'Each individual learns at a different pace.', '每个人的学习速度都不同。', '四级阅读·教育类', '401', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-402', 'CET4', 'indoor', '/ˈɪndɔː(r)/', 'adj.', '室内的；户内的', 'The museum has a large indoor playground.', '这家博物馆有一个很大的室内游乐场。', '必背核心·高频词', '402', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-403', 'CET4', 'induce', '/ɪnˈdjuːs/', 'v.', '引起；诱导；促使', 'The drug may induce drowsiness in some patients.', '这种药可能使部分患者嗜睡。', '必背核心·高频词', '403', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-404', 'CET4', 'industrial', '/ɪnˈdʌstriəl/', 'adj.', '工业的；产业的', 'The town was once a busy industrial centre.', '这座小镇曾是繁忙的工业中心。', '必背核心·高频词', '404', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-405', 'CET4', 'inevitable', '/ɪnˈevɪtəbl/', 'adj.', '不可避免的；必然的', 'Some mistakes are inevitable when you learn something new.', '学新东西时有些错误是不可避免的。', '四级写作·教育类', '405', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-406', 'CET4', 'infant', '/ˈɪnfənt/', 'n./adj.', '婴儿；幼儿的；初期的', 'Infant mortality has fallen sharply since 2000.', '2000年以来婴儿死亡率大幅下降。', '必背核心·高频词', '406', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-407', 'CET4', 'infect', '/ɪnˈfekt/', 'v.', '感染；传染；影响', 'The virus can infect both animals and humans.', '这种病毒能感染动物和人。', '必背核心·高频词', '407', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-408', 'CET4', 'infer', '/ɪnˈfɜː(r)/', 'v.', '推断；推论', 'We can infer from the data that demand is falling.', '我们可以从数据推断需求正在下降。', '必背核心·高频词', '408', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-409', 'CET4', 'inflation', '/ɪnˈfleɪʃn/', 'n.', '通货膨胀；膨胀', 'Inflation has eroded people’s purchasing power.', '通货膨胀侵蚀了人们的购买力。', '必背核心·高频词', '409', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-410', 'CET4', 'influence', '/ˈɪnfluəns/', 'n./v.', '影响；影响力', 'Parents have a great influence on their children’s habits.', '父母对孩子的习惯有很大影响。', '四级写作·家庭类', '410', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-411', 'CET4', 'inform', '/ɪnˈfɔːm/', 'v.', '通知；告知；影响', 'Please inform us of any change in your address.', '地址如有变更请通知我们。', '必背核心·高频词', '411', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-412', 'CET4', 'inhabit', '/ɪnˈhæbɪt/', 'v.', '居住于；栖息于', 'Only a few families still inhabit the old village.', '只有少数几户人家仍住在那个老村里。', '必背核心·高频词', '412', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-413', 'CET4', 'inherent', '/ɪnˈhɪərənt/', 'adj.', '内在的；固有的；天生的', 'There are inherent risks in every investment.', '每项投资都存在固有的风险。', '六级阅读·经济类', '413', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-414', 'CET4', 'inherit', '/ɪnˈherɪt/', 'v.', '继承；遗传', 'She inherited her mother’s love of music.', '她继承了母亲对音乐的热爱。', '必背核心·高频词', '414', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-415', 'CET4', 'inhibit', '/ɪnˈhɪbɪt/', 'v.', '抑制；阻碍；约束', 'Fear of failure inhibits creativity.', '对失败的恐惧抑制了创造力。', '六级写作·教育类', '415', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-416', 'CET4', 'initial', '/ɪˈnɪʃl/', 'adj./n.', '最初的；首字母', 'The initial results of the survey were encouraging.', '调查的初步结果令人鼓舞。', '必背核心·高频词', '416', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-417', 'CET4', 'initiate', '/ɪˈnɪʃieɪt/', 'v.', '发起；开始；使入门', 'The school initiated a reading programme last year.', '学校去年发起了一项阅读计划。', '六级阅读·教育类', '417', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-418', 'CET4', 'injure', '/ˈɪndʒə(r)/', 'v.', '伤害；损害', 'Three people were injured in the accident.', '事故中有三人受伤。', '必背核心·高频词', '418', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-419', 'CET4', 'innocent', '/ˈɪnsnt/', 'adj.', '无辜的；天真的', 'The court found him innocent of all charges.', '法庭判定他所有指控均不成立。', '必背核心·高频词', '419', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-420', 'CET4', 'innovation', '/ˌɪnəˈveɪʃn/', 'n.', '创新；革新', 'Technological innovation drives economic growth.', '技术创新推动经济增长。', '必背核心·高频词', '420', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-421', 'CET4', 'input', '/ˈɪnpʊt/', 'n./v.', '输入；投入；投入物', 'We welcome input from all team members.', '我们欢迎所有团队成员的意见。', '必背核心·高频词', '421', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-422', 'CET4', 'inquire', '/ɪnˈkwaɪə(r)/', 'v.', '询问；打听；调查', 'She inquired about the price of the course.', '她询问了这门课程的价格。', '必背核心·高频词', '422', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-423', 'CET4', 'insert', '/ɪnˈsɜːt/', 'v.', '插入；嵌入', 'Insert the card into the slot facing up.', '将卡片正面朝上插入插槽。', '必背核心·高频词', '423', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-424', 'CET4', 'insight', '/ˈɪnsaɪt/', 'n.', '洞察力；见解；领悟', 'The book offers new insights into human behaviour.', '这本书为人类行为提供了新见解。', '六级阅读·学术类', '424', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-425', 'CET4', 'insist', '/ɪnˈsɪst/', 'v.', '坚持；坚决主张', 'She insisted on paying for the meal herself.', '她坚持自己付饭钱。', '四级完形·生活类', '425', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-426', 'CET4', 'inspect', '/ɪnˈspekt/', 'v.', '检查；视察', 'Officials inspect the factory twice a year.', '官员每年视察这家工厂两次。', '必背核心·高频词', '426', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-427', 'CET4', 'inspire', '/ɪnˈspaɪə(r)/', 'v.', '激励；启发；唤起', 'Her story inspired thousands of young readers.', '她的故事激励了成千上万的年轻读者。', '四级阅读·人物类', '427', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-428', 'CET4', 'install', '/ɪnˈstɔːl/', 'v.', '安装；设置；任命', 'It took an hour to install the software.', '安装这个软件花了一个小时。', '必背核心·高频词', '428', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-429', 'CET4', 'instance', '/ˈɪnstəns/', 'n.', '例子；实例；情况', 'For instance, many students work part-time.', '例如，许多学生做兼职。', '必背核心·高频词', '429', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-430', 'CET4', 'instant', '/ˈɪnstənt/', 'adj./n.', '立即的；速食的；瞬间', 'The new policy took effect almost instantly.', '新政策几乎立即生效。', '必背核心·高频词', '430', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-431', 'CET4', 'instinct', '/ˈɪnstɪŋkt/', 'n.', '本能；直觉', 'Her first instinct was to call the police.', '她的第一本能是报警。', '必背核心·高频词', '431', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-432', 'CET4', 'institute', '/ˈɪnstɪtjuːt/', 'n./v.', '研究所；学院；建立', 'He works at a research institute in Beijing.', '他在北京一家研究所工作。', '必背核心·高频词', '432', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-433', 'CET4', 'instruct', '/ɪnˈstrʌkt/', 'v.', '指示；命令；教授', 'The guide instructed us to stay on the path.', '导游指示我们留在小路上。', '必背核心·高频词', '433', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-434', 'CET4', 'instrument', '/ˈɪnstrəmənt/', 'n.', '仪器；乐器；工具', 'The lab bought a new measuring instrument.', '实验室购买了一台新测量仪器。', '必背核心·高频词', '434', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-435', 'CET4', 'insult', '/ɪnˈsʌlt/', 'v./n.', '侮辱；辱骂', 'He felt insulted by the unfair remark.', '他被那句不公平的话激怒了。', '必背核心·高频词', '435', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-436', 'CET4', 'intact', '/ɪnˈtækt/', 'adj.', '完整无缺的；未受损的', 'The old painting survived the fire intact.', '那幅古画在大火中完好无损地保存下来。', '必背核心·高频词', '436', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-437', 'CET4', 'integral', '/ˈɪntɪɡrəl/', 'adj.', '不可或缺的；完整的', 'Practice is an integral part of language learning.', '练习是语言学习不可或缺的一部分。', '六级写作·教育类', '437', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-438', 'CET4', 'integrity', '/ɪnˈteɡrəti/', 'n.', '诚实正直；完整', 'He is a man of absolute integrity.', '他是一个极其正直的人。', '六级阅读·人物类', '438', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-439', 'CET4', 'intend', '/ɪnˈtend/', 'v.', '打算；计划；意指', 'I intend to apply for the scholarship next term.', '我打算下学期申请这项奖学金。', '必背核心·高频词', '439', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-440', 'CET4', 'intense', '/ɪnˈtens/', 'adj.', '强烈的；激烈的；紧张的', 'The competition for good jobs is becoming more intense.', '好工作的竞争越来越激烈。', '四级阅读·就业类', '440', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-441', 'CET4', 'interact', '/ˌɪntərˈækt/', 'v.', '互动；交流；相互作用', 'Teachers should interact more with their students.', '教师应当多与学生互动。', '必背核心·高频词', '441', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
