  ('cet4-485', 'CET4', 'keen', '/kiːn/', 'adj.', '热切的；热衷的；敏锐的', 'She is keen on learning foreign languages.', '她热衷于学习外语。', '必背核心·高频词', '485', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
