  ('cet4-496', 'CET4', 'knee', '/niː/', 'n.', '膝盖', 'He fell and scraped his knee badly.', '他摔倒时把膝盖擦伤了。', '必背核心·高频词', '496', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-497', 'CET4', 'kneel', '/niːl/', 'v.', '跪下；跪着', 'She knelt down to comfort the crying child.', '她跪下来安慰哭泣的孩子。', '必背核心·高频词', '497', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-498', 'CET4', 'knife', '/naɪf/', 'n./v.', '刀；用刀切', 'He cut the rope with a small knife.', '他用一把小刀割断了绳子。', '必背核心·高频词', '498', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-499', 'CET4', 'knight', '/naɪt/', 'n.', '骑士；爵士', 'The knight rescued the villagers from danger.', '骑士把村民从危险中救了出来。', '必背核心·高频词', '499', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
