  ('cet4-501', 'CET4', 'knob', '/nɒb/', 'n.', '球形把手；旋钮', 'Turn the knob to the right to open the door.', '向右转动把手即可开门。', '必背核心·高频词', '501', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-502', 'CET4', 'knock', '/nɒk/', 'v./n.', '敲；碰；撞击', 'Someone is knocking at the door.', '有人在敲门。', '必背核心·高频词', '502', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-503', 'CET4', 'knot', '/nɒt/', 'n./v.', '结；打结；疙瘩', 'He tied the rope in a tight knot.', '他把绳子打了个紧结。', '必背核心·高频词', '503', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
