  ('cet4-572', 'CET4', 'majority', '/məˈdʒɒrəti/', 'n.', '大多数；多数票', 'The majority of voters supported the reform.', '多数选民支持这项改革。', '必背核心·高频词', '572', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-573', 'CET4', 'manage', '/ˈmænɪdʒ/', 'v.', '管理；设法做到；经营', 'She manages a team of fifteen people.', '她管理着一个十五人的团队。', '必背核心·高频词', '573', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
