  ('cet4-580', 'CET4', 'marginal', '/ˈmɑːdʒɪnl/', 'adj.', '边缘的；微小的；不重要的', 'The change had only a marginal effect.', '这一变化只产生了微小的影响。', '六级阅读·经济类', '580', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-581', 'CET4', 'mark', '/mɑːk/', 'n./v.', '标记；分数；标明', 'The exam marks will be published on Friday.', '考试成绩将于星期五公布。', '必背核心·高频词', '581', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-582', 'CET4', 'market', '/ˈmɑːkɪt/', 'n./v.', '市场；行情；推销', 'The company is trying to expand into new markets.', '公司正努力开拓新市场。', '必背核心·高频词', '582', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-583', 'CET4', 'massive', '/ˈmæsɪv/', 'adj.', '巨大的；大量的', 'The storm caused massive damage to the crops.', '暴风雨给庄稼造成了巨大损失。', '必背核心·高频词', '583', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-584', 'CET4', 'master', '/ˈmɑːstə(r)/', 'n./v.', '主人；硕士；掌握', 'It takes years to master a musical instrument.', '掌握一门乐器需要多年时间。', '必背核心·高频词', '584', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-585', 'CET4', 'match', '/mætʃ/', 'n./v.', '比赛；对手；匹配', 'The two teams meet in the final match tonight.', '两队今晚在决赛中相遇。', '必背核心·高频词', '585', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-586', 'CET4', 'material', '/məˈtɪəriəl/', 'n./adj.', '材料；素材；物质的', 'The building is made of recycled material.', '这栋建筑是用回收材料建造的。', '必背核心·高频词', '586', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-587', 'CET4', 'mature', '/məˈtʃʊə(r)/', 'adj./v.', '成熟的；使成熟', 'He is very mature for a boy of his age.', '以他这个年纪来说，他很成熟。', '四级完形·人物类', '587', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-588', 'CET4', 'maximum', '/ˈmæksɪməm/', 'n./adj.', '最大量；最大值；最高的', 'The hall holds a maximum of five hundred people.', '大厅最多可容纳五百人。', '必背核心·高频词', '588', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-589', 'CET4', 'mayor', '/meə(r)/', 'n.', '市长', 'The mayor promised to improve public transport.', '市长承诺改善公共交通。', '必背核心·高频词', '589', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-590', 'CET4', 'meaning', '/ˈmiːnɪŋ/', 'n.', '意义；意思；目的', 'The word has several different meanings.', '这个词有几种不同的意思。', '必背核心·高频词', '590', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-591', 'CET4', 'measure', '/ˈmeʒə(r)/', 'n./v.', '措施；测量；衡量', 'The government took emergency measures.', '政府采取了紧急措施。', '必背核心·高频词', '591', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-592', 'CET4', 'mechanic', '/məˈkænɪk/', 'n.', '技工；机械师', 'The mechanic fixed the car in under an hour.', '修理工不到一小时就把车修好了。', '必背核心·高频词', '592', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-593', 'CET4', 'mechanism', '/ˈmekənɪzəm/', 'n.', '机制；机构；机械装置', 'The body has its own repair mechanism.', '人体有自身的修复机制。', '六级阅读·科普类', '593', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-594', 'CET4', 'medal', '/ˈmedl/', 'n.', '奖牌；勋章', 'She won a gold medal at the age of nineteen.', '她十九岁时赢得一枚金牌。', '必背核心·高频词', '594', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-595', 'CET4', 'media', '/ˈmiːdiə/', 'n.', '媒体；新闻媒介', 'Social media has changed how we get news.', '社交媒体改变了我们获取新闻的方式。', '必背核心·高频词', '595', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-596', 'CET4', 'mediate', '/ˈmiːdieɪt/', 'v.', '调解；斡旋；居中', 'The UN mediated between the two sides.', '联合国在双方之间进行了调解。', '六级阅读·政治类', '596', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-597', 'CET4', 'medical', '/ˈmedɪkl/', 'adj.', '医学的；医疗的', 'Medical research needs long-term investment.', '医学研究需要长期投入。', '必背核心·高频词', '597', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-598', 'CET4', 'medicine', '/ˈmedsn/', 'n.', '药；医学', 'Take the medicine twice a day after meals.', '这种药每天饭后服两次。', '必背核心·高频词', '598', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-599', 'CET4', 'mediocre', '/ˌmiːdiˈəʊkə(r)/', 'adj.', '平庸的；普通的', 'The film was pleasant but mediocre.', '这部电影还算好看，但很平庸。', '六级阅读·艺术类', '599', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-600', 'CET4', 'medium', '/ˈmiːdiəm/', 'n./adj.', '媒介；手段；中等的', 'Television remains a powerful advertising medium.', '电视仍是强大的广告媒介。', '必背核心·高频词', '600', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-601', 'CET4', 'memory', '/ˈmeməri/', 'n.', '记忆；回忆；存储器', 'He has a remarkable memory for names.', '他对名字的记忆力惊人。', '必背核心·高频词', '601', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-602', 'CET4', 'mental', '/ˈmentl/', 'adj.', '精神的；心理的；智力的', 'Regular exercise improves both physical and mental health.', '规律锻炼能改善身心健康。', '四级阅读·健康类', '602', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-603', 'CET4', 'mention', '/ˈmenʃn/', 'v./n.', '提到；提及', 'She mentioned the problem at the meeting.', '她在会上提到了这个问题。', '必背核心·高频词', '603', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-604', 'CET4', 'mercy', '/ˈmɜːsi/', 'n.', '仁慈；宽恕；幸运', 'The survivors were at the mercy of the sea.', '幸存者听凭大海摆布。', '必背核心·高频词', '604', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-605', 'CET4', 'mere', '/mɪə(r)/', 'adj.', '仅仅的；只不过的', 'The journey took a mere twenty minutes.', '这趟旅程只花了二十分钟。', '必背核心·高频词', '605', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-606', 'CET4', 'merge', '/mɜːdʒ/', 'v.', '合并；融合；融入', 'The two colleges merged in 2015.', '这两所学院于2015年合并。', '六级阅读·教育类', '606', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-607', 'CET4', 'merit', '/ˈmerɪt/', 'n./v.', '优点；功绩；值得', 'The plan has real merit despite its low cost.', '这个方案虽然成本低，但确有可取之处。', '必背核心·高频词', '607', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-608', 'CET4', 'mess', '/mes/', 'n./v.', '混乱；脏乱；弄乱', 'The room was in a terrible mess after the party.', '聚会后房间乱得一塌糊涂。', '必背核心·高频词', '608', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-609', 'CET4', 'method', '/ˈmeθəd/', 'n.', '方法；办法；条理', 'They developed a new method of teaching reading.', '他们开发了一种新的阅读教学方法。', '必背核心·高频词', '609', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-610', 'CET4', 'meticulous', '/məˈtɪkjələs/', 'adj.', '一丝不苟的；细致的', 'She kept meticulous records of every experiment.', '她对每次实验都做了细致的记录。', '六级阅读·科研类', '610', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-611', 'CET4', 'midnight', '/ˈmɪdnaɪt/', 'n.', '午夜；子夜', 'He worked until midnight to finish the report.', '他工作到午夜才完成报告。', '必背核心·高频词', '611', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-612', 'CET4', 'mild', '/maɪld/', 'adj.', '温和的；轻微的；不浓的', 'The winter here is unusually mild.', '这里的冬天异常温和。', '必背核心·高频词', '612', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-613', 'CET4', 'military', '/ˈmɪlətri/', 'adj./n.', '军事的；军队', 'He served in the military for six years.', '他在军队服役六年。', '必背核心·高频词', '613', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-614', 'CET4', 'mineral', '/ˈmɪnərəl/', 'n./adj.', '矿物；矿物质', 'The water is rich in natural minerals.', '这种水富含天然矿物质。', '必背核心·高频词', '614', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-615', 'CET4', 'minimum', '/ˈmɪnɪməm/', 'n./adj.', '最小值；最低限度的', 'Applicants need a minimum of two years’ experience.', '申请者至少需要两年经验。', '四级阅读·招聘类', '615', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-616', 'CET4', 'minister', '/ˈmɪnɪstə(r)/', 'n.', '部长；大臣；牧师', 'The foreign minister met his counterpart yesterday.', '外交部长昨天会见了对方外长。', '必背核心·高频词', '616', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-617', 'CET4', 'minor', '/ˈmaɪnə(r)/', 'adj./n.', '较小的；次要的；未成年人', 'There are only a few minor problems left.', '只剩下几个小问题。', '必背核心·高频词', '617', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-618', 'CET4', 'minority', '/maɪˈnɒrəti/', 'n.', '少数；少数民族', 'Only a small minority disagreed with the decision.', '只有极少数人不同意这一决定。', '必背核心·高频词', '618', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-619', 'CET4', 'miracle', '/ˈmɪrəkl/', 'n.', '奇迹；奇事', 'It was a miracle that no one was hurt.', '无人受伤真是奇迹。', '必背核心·高频词', '619', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-620', 'CET4', 'mirror', '/ˈmɪrə(r)/', 'n./v.', '镜子；反映；反射', 'The lake mirrored the snow-covered mountains.', '湖面映出白雪覆盖的群山。', '必背核心·高频词', '620', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-621', 'CET4', 'mission', '/ˈmɪʃn/', 'n.', '使命；任务；代表团', 'The rescue mission lasted three days.', '救援任务持续了三天。', '必背核心·高频词', '621', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-622', 'CET4', 'mistake', '/mɪˈsteɪk/', 'n./v.', '错误；误会；弄错', 'Don’t be afraid of making mistakes.', '不要害怕犯错。', '必背核心·高频词', '622', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-623', 'CET4', 'mixture', '/ˈmɪkstʃə(r)/', 'n.', '混合；混合物', 'Air is a mixture of several gases.', '空气是几种气体的混合物。', '必背核心·高频词', '623', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-624', 'CET4', 'mobile', '/ˈməʊbaɪl/', 'adj./n.', '移动的；流动的；手机', 'Mobile payment is now common everywhere.', '移动支付现在随处可见。', '必背核心·高频词', '624', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-625', 'CET4', 'mobilize', '/ˈməʊbəlaɪz/', 'v.', '动员；调动；组织起来', 'The government mobilized all available resources.', '政府调动了一切可用资源。', '六级阅读·新闻类', '625', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-626', 'CET4', 'model', '/ˈmɒdl/', 'n./v.', '模型；模范；模仿', 'The car maker unveiled its latest model.', '这家汽车制造商发布了最新型号。', '必背核心·高频词', '626', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-627', 'CET4', 'moderate', '/ˈmɒdərət/', 'adj.', '适度的；温和的', 'A moderate amount of coffee does no harm to health.', '适量的咖啡对健康无害。', '四级阅读·健康类', '627', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-628', 'CET4', 'modern', '/ˈmɒdn/', 'adj.', '现代的；近代的', 'Modern life moves at a very fast pace.', '现代生活节奏很快。', '必背核心·高频词', '628', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-629', 'CET4', 'modest', '/ˈmɒdɪst/', 'adj.', '谦虚的；适度的；朴素的', 'He lives in a modest house in the suburbs.', '他住在郊区一栋简朴的房子里。', '必背核心·高频词', '629', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-630', 'CET4', 'modify', '/ˈmɒdɪfaɪ/', 'v.', '修改；调整；缓和', 'The rules were modified after complaints.', '投诉之后规则被修改了。', '必背核心·高频词', '630', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-631', 'CET4', 'moment', '/ˈməʊmənt/', 'n.', '片刻；瞬间；时机', 'Please wait a moment, I will check for you.', '请稍等，我帮您查一下。', '必背核心·高频词', '631', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-632', 'CET4', 'monitor', '/ˈmɒnɪtə(r)/', 'v./n.', '监测；监控；显示器', 'Scientists monitor the volcano around the clock.', '科学家们昼夜监测这座火山。', '必背核心·高频词', '632', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-633', 'CET4', 'monopoly', '/məˈnɒpəli/', 'n.', '垄断；专卖；独占', 'No single firm should hold a monopoly.', '不应由单家企业垄断。', '六级阅读·经济类', '633', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-634', 'CET4', 'mood', '/muːd/', 'n.', '心情；情绪；氛围', 'Rainy weather always puts me in a bad mood.', '雨天总是让我心情不好。', '必背核心·高频词', '634', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
