  ('cet4-776', 'CET4', 'park', '/pɑːk/', 'n./v.', '公园；停车场；停放', 'You cannot park here between nine and five.', '九点到五点之间此处不得停车。', '必背核心·高频词', '776', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-777', 'CET4', 'parliament', '/ˈpɑːləmənt/', 'n.', '议会；国会', 'Parliament passed the bill last week.', '议会上周通过了这项议案。', '必背核心·高频词', '777', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-778', 'CET4', 'partial', '/ˈpɑːʃl/', 'adj.', '部分的；偏袒的', 'The results are only partial so far.', '目前结果只是初步的。', '必背核心·高频词', '778', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
