  ('cet4-780', 'CET4', 'particle', '/ˈpɑːtɪkl/', 'n.', '粒子；微粒；小品词', 'Dust particles float in the air.', '尘埃微粒漂浮在空气中。', '必背核心·高频词', '780', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-781', 'CET4', 'particular', '/pəˈtɪkjələ(r)/', 'adj.', '特定的；特别的；讲究的', 'Is there any particular reason for your choice?', '你的选择有什么特别的原因吗？', '四级听力·长对话', '781', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-782', 'CET4', 'partner', '/ˈpɑːtnə(r)/', 'n./v.', '伙伴；合伙人；搭档', 'She is a partner in a law firm.', '她是一家律师事务所的合伙人。', '必背核心·高频词', '782', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-783', 'CET4', 'passion', '/ˈpæʃn/', 'n.', '激情；热爱；酷爱', 'He has a passion for classical music.', '他酷爱古典音乐。', '必背核心·高频词', '783', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-784', 'CET4', 'passive', '/ˈpæsɪv/', 'adj.', '被动的；消极的', 'Students should not be passive listeners.', '学生不应做被动的听众。', '必背核心·高频词', '784', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-785', 'CET4', 'passport', '/ˈpɑːspɔːt/', 'n.', '护照', 'Make sure your passport is still valid.', '确保你的护照仍然有效。', '必背核心·高频词', '785', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
