  ('cet4-787', 'CET4', 'pastry', '/ˈpeɪstri/', 'n.', '糕点；油酥面团', 'The bakery sells fresh pastry every morning.', '这家面包店每天早上卖新鲜糕点。', '必背核心·高频词', '787', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-788', 'CET4', 'patch', '/pætʃ/', 'n./v.', '补丁；小块地；修补', 'There is a wet patch on the ceiling.', '天花板上有一块水渍。', '必背核心·高频词', '788', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
