  ('cet4-790', 'CET4', 'path', '/pɑːθ/', 'n.', '小路；路径；途径', 'A narrow path leads up to the temple.', '一条小径通向那座寺庙。', '必背核心·高频词', '790', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-791', 'CET4', 'patience', '/ˈpeɪʃns/', 'n.', '耐心；忍耐', 'Teaching young children requires patience.', '教小孩子需要耐心。', '必背核心·高频词', '791', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-792', 'CET4', 'patient', '/ˈpeɪʃnt/', 'n./adj.', '病人；有耐心的', 'The doctor sees about thirty patients a day.', '这位医生一天大约接诊三十位病人。', '必背核心·高频词', '792', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-793', 'CET4', 'pattern', '/ˈpætn/', 'n./v.', '模式；图案；仿造', 'Sleeping patterns change with age.', '睡眠模式随年龄变化。', '必背核心·高频词', '793', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-794', 'CET4', 'pause', '/pɔːz/', 'v./n.', '暂停；中止', 'She paused for a moment before answering.', '她停顿了一下才回答。', '必背核心·高频词', '794', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-795', 'CET4', 'pave', '/peɪv/', 'v.', '铺路；铺设', 'The road is paved with flat stones.', '这条路用石板铺成。', '必背核心·高频词', '795', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
