  ('cet4-797', 'CET4', 'payment', '/ˈpeɪmənt/', 'n.', '付款；支付；款项', 'Payment must be made within thirty days.', '必须在三十天内付款。', '必背核心·高频词', '797', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-798', 'CET4', 'peace', '/piːs/', 'n.', '和平；平静；安宁', 'The two sides finally signed a peace deal.', '双方最终签署了和平协议。', '必背核心·高频词', '798', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-799', 'CET4', 'peak', '/piːk/', 'n./adj./v.', '顶峰；高峰的；达到顶点', 'Sales peak in December every year.', '销售额每年十二月达到高峰。', '必背核心·高频词', '799', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-800', 'CET4', 'pearl', '/pɜːl/', 'n.', '珍珠；珍品', 'The necklace is made of real pearls.', '这条项链由真珍珠制成。', '必背核心·高频词', '800', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
