  ('cet4-801', 'CET4', 'peculiar', '/pɪˈkjuːliə(r)/', 'adj.', '奇怪的；特有的；独特的', 'This custom is peculiar to the region.', '这个习俗是该地区特有的。', '六级阅读·文化类', '801', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-802', 'CET4', 'pedestrian', '/pəˈdestriən/', 'n./adj.', '行人；平淡的', 'Pedestrians should use the crossing.', '行人应走人行横道。', '必背核心·高频词', '802', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-803', 'CET4', 'penalty', '/ˈpenəlti/', 'n.', '处罚；罚款；罚球', 'There is a penalty for late payment.', '逾期付款会被罚款。', '必背核心·高频词', '803', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-804', 'CET4', 'pencil', '/ˈpensl/', 'n.', '铅笔', 'Write in pencil so you can erase.', '用铅笔写，方便擦掉。', '必背核心·高频词', '804', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-805', 'CET4', 'penetrate', '/ˈpenɪtreɪt/', 'v.', '穿透；渗透；洞察', 'Sunlight barely penetrated the thick fog.', '阳光几乎透不过浓雾。', '必背核心·高频词', '805', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-806', 'CET4', 'pension', '/ˈpenʃn/', 'n.', '养老金；退休金', 'He lives on a small pension.', '他靠微薄的养老金生活。', '必背核心·高频词', '806', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-807', 'CET4', 'pepper', '/ˈpepə(r)/', 'n./v.', '胡椒；辣椒；撒', 'Add a little pepper to the soup.', '往汤里加点胡椒。', '必背核心·高频词', '807', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-808', 'CET4', 'perceive', '/pəˈsiːv/', 'v.', '察觉；理解；认为', 'People now perceive online learning differently.', '人们现在对在线学习的看法不同了。', '四级阅读·教育类', '808', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-809', 'CET4', 'percent', '/pəˈsent/', 'n.', '百分之…', 'About seventy percent agreed with the idea.', '约百分之七十的人赞同这个想法。', '必背核心·高频词', '809', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-810', 'CET4', 'perception', '/pəˈsepʃn/', 'n.', '感知；看法；洞察力', 'Public perception of the issue has changed.', '公众对该问题的看法已经改变。', '必背核心·高频词', '810', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-811', 'CET4', 'perfect', '/ˈpɜːfɪkt/', 'adj./v.', '完美的；使完善', 'Practice makes perfect.', '熟能生巧。', '必背核心·高频词', '811', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-812', 'CET4', 'perform', '/pəˈfɔːm/', 'v.', '表演；执行；表现', 'The team performed well under pressure.', '这支队伍在压力下表现出色。', '必背核心·高频词', '812', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-813', 'CET4', 'perhaps', '/pəˈhæps/', 'adv.', '也许；可能', 'Perhaps we should try a different approach.', '也许我们该换个方法。', '必背核心·高频词', '813', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-814', 'CET4', 'period', '/ˈpɪəriəd/', 'n.', '时期；周期；句号', 'The museum was closed for a period of two years.', '博物馆曾关闭了两年。', '必背核心·高频词', '814', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-815', 'CET4', 'permanent', '/ˈpɜːmənənt/', 'adj.', '永久的；长期的', 'He finally found a permanent job after two years.', '两年后他终于找到了一份长期工作。', '四级阅读·就业类', '815', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-816', 'CET4', 'permeate', '/ˈpɜːmieɪt/', 'v.', '渗透；弥漫；充满', 'The smell of coffee permeated the room.', '咖啡的气味弥漫了整个房间。', '六级完形·生活类', '816', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-817', 'CET4', 'permit', '/pəˈmɪt/', 'v./n.', '允许；许可；执照', 'Smoking is not permitted in the building.', '楼内禁止吸烟。', '必背核心·高频词', '817', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-818', 'CET4', 'perpetual', '/pəˈpetʃuəl/', 'adj.', '永久的；持续的；无休止的', 'He lived in perpetual fear of being discovered.', '他一直生活在被发现的恐惧中。', '六级阅读·文学类', '818', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-819', 'CET4', 'persist', '/pəˈsɪst/', 'v.', '坚持；持续存在', 'If the pain persists, see a doctor.', '如果疼痛持续，请去看医生。', '必背核心·高频词', '819', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-820', 'CET4', 'personal', '/ˈpɜːsənl/', 'adj.', '个人的；私人的；亲自的', 'Please keep this information personal.', '请对这条信息保密。', '必背核心·高频词', '820', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-821', 'CET4', 'personality', '/ˌpɜːsəˈnæləti/', 'n.', '个性；人格；名人', 'She has a warm and friendly personality.', '她性格热情友善。', '必背核心·高频词', '821', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-822', 'CET4', 'personnel', '/ˌpɜːsəˈnel/', 'n.', '人员；员工；人事部门', 'All personnel must wear a badge.', '所有员工都必须佩戴胸卡。', '必背核心·高频词', '822', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-823', 'CET4', 'perspective', '/pəˈspektɪv/', 'n.', '视角；观点；透视法', 'Travel gives you a new perspective on life.', '旅行让你对生活有新的看法。', '必背核心·高频词', '823', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-824', 'CET4', 'persuade', '/pəˈsweɪd/', 'v.', '说服；劝说', 'I persuaded my father to give up smoking.', '我说服父亲戒了烟。', '四级完形·家庭类', '824', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-825', 'CET4', 'pertinent', '/ˈpɜːtɪnənt/', 'adj.', '相关的；中肯的；切题的', 'She raised a pertinent question about cost.', '她提出了一个有关成本的中肯问题。', '六级阅读·学术类', '825', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-826', 'CET4', 'pervasive', '/pəˈveɪsɪv/', 'adj.', '普遍的；到处渗透的', 'The influence of advertising is pervasive.', '广告的影响无处不在。', '六级写作·传媒类', '826', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-827', 'CET4', 'phase', '/feɪz/', 'n./v.', '阶段；时期；分阶段进行', 'The project is entering its final phase.', '项目正进入最后阶段。', '必背核心·高频词', '827', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-828', 'CET4', 'phenomenon', '/fəˈnɒmɪnən/', 'n.', '现象；非凡的人或事', 'Global warming is a worldwide phenomenon.', '全球变暖是一个世界性的现象。', '六级阅读·环境类', '828', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-829', 'CET4', 'philosophy', '/fəˈlɒsəfi/', 'n.', '哲学；哲理；理念', 'Her teaching philosophy is simple and clear.', '她的教学理念简单而清晰。', '必背核心·高频词', '829', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-830', 'CET4', 'phone', '/fəʊn/', 'n./v.', '电话；打电话', 'I will phone you as soon as I arrive.', '我一到就给你打电话。', '必背核心·高频词', '830', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
