  ('cet4-1201', 'CET4', 'scope', '/skəʊp/', 'n.', '范围；机会；视野', 'The subject is beyond the scope of this essay.', '这个话题超出了本文的范围。', '必背核心·高频词', '1201', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
