  ('cet4-1203', 'CET4', 'scratch', '/skrætʃ/', 'v./n.', '抓；挠；划痕', 'The cat scratched the sofa badly.', '猫把沙发挠得厉害。', '必背核心·高频词', '1203', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1204', 'CET4', 'scream', '/skriːm/', 'v./n.', '尖叫；呼啸', 'She screamed when she saw the snake.', '她看到蛇时尖叫起来。', '必背核心·高频词', '1204', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1205', 'CET4', 'screen', '/skriːn/', 'n./v.', '屏幕；屏风；放映', 'Staring at a screen all day hurts your eyes.', '整天盯着屏幕会伤眼睛。', '必背核心·高频词', '1205', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
