  ('cet4-1209', 'CET4', 'season', '/ˈsiːzn/', 'n./v.', '季节；赛季；调味', 'The rainy season lasts from June to August.', '雨季从六月持续到八月。', '必背核心·高频词', '1209', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1210', 'CET4', 'secretary', '/ˈsekrətri/', 'n.', '秘书；书记；大臣', 'The secretary took notes during the meeting.', '秘书在会上做记录。', '必背核心·高频词', '1210', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1211', 'CET4', 'section', '/ˈsekʃn/', 'n.', '部分；章节；区域', 'The last section of the book is the hardest.', '这本书的最后一节最难。', '必背核心·高频词', '1211', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
