  ('cet4-1213', 'CET4', 'secure', '/sɪˈkjʊə(r)/', 'adj./v.', '安全的；获得；保护', 'He finally secured a place at a famous university.', '他最终在一所名校拿到了录取名额。', '四级阅读·教育类', '1213', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
