  ('cet4-1215', 'CET4', 'seize', '/siːz/', 'v.', '抓住；夺取；没收', 'He seized the chance to study in London.', '他抓住了去伦敦学习的机会。', '必背核心·高频词', '1215', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
