  ('cet4-1218', 'CET4', 'senior', '/ˈsiːniə(r)/', 'adj./n.', '级别高的；年长的；大四学生', 'He is senior to me by three years.', '他比我资历深三年。', '必背核心·高频词', '1218', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1219', 'CET4', 'sense', '/sens/', 'n./v.', '感觉；意义；意识到', 'The word has several senses in English.', '这个词在英语中有几个义项。', '必背核心·高频词', '1219', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1220', 'CET4', 'sensitive', '/ˈsensətɪv/', 'adj.', '敏感的；灵敏的；体贴的', 'Some people are sensitive to certain kinds of food.', '有些人对某些食物过敏。', '四级阅读·健康类', '1220', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1221', 'CET4', 'sentence', '/ˈsentəns/', 'n./v.', '句子；判决；宣判', 'Read the sentence aloud once more.', '把这个句子再大声读一遍。', '必背核心·高频词', '1221', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1222', 'CET4', 'separate', '/ˈseprət/', 'adj./v.', '分开的；分离；隔开', 'Keep the raw meat separate from the vegetables.', '把生肉和蔬菜分开放。', '四级阅读·生活类', '1222', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
