  ('cet4-1289', 'CET4', 'substitute', '/ˈsʌbstɪtjuːt/', 'n./v.', '代替者；用…代替', 'You can substitute honey for sugar in this recipe.', '这个食谱里你可以用蜂蜜代替糖。', '四级阅读·生活类', '1289', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1290', 'CET4', 'subtle', '/ˈsʌtl/', 'adj.', '微妙的；细微的；敏锐的', 'There is a subtle difference between the two words.', '这两个词之间有细微差别。', '六级翻译·技巧类', '1290', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1291', 'CET4', 'succinct', '/səkˈsɪŋkt/', 'adj.', '简洁的；简明的', 'Please keep your answer succinct.', '请保持回答简洁。', '六级写作·学术类', '1291', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1292', 'CET4', 'suffice', '/səˈfaɪs/', 'v.', '足够；满足…的需要', 'A simple example will suffice.', '一个简单的例子就足够了。', '六级阅读·学术类', '1292', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1293', 'CET4', 'sufficient', '/səˈfɪʃnt/', 'adj.', '足够的；充分的', 'We do not have sufficient evidence to support the claim.', '我们没有足够证据支持这一说法。', '四级阅读·科研类', '1293', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1294', 'CET4', 'suitable', '/ˈsuːtəbl/', 'adj.', '合适的；适宜的', 'This film is not suitable for young children.', '这部电影不适合幼儿观看。', '四级听力·生活类', '1294', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1295', 'CET4', 'superfluous', '/suːˈpɜːfluəs/', 'adj.', '多余的；过剩的', 'Delete all superfluous words from your essay.', '把文章里所有多余的词语删掉。', '六级写作·学术类', '1295', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1296', 'CET4', 'superior', '/suːˈpɪəriə(r)/', 'adj./n.', '更好的；上级的；上司', 'This model is superior to the old one in many ways.', '这款型号在很多方面优于旧款。', '四级阅读·科技类', '1296', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1297', 'CET4', 'supply', '/səˈplaɪ/', 'n./v.', '供应；供给；补给', 'The factory supplies parts to car makers worldwide.', '这家工厂向全球汽车制造商供应零件。', '四级阅读·商业类', '1297', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1298', 'CET4', 'suppress', '/səˈpres/', 'v.', '压制；抑制；镇压', 'She could not suppress a smile.', '她忍不住笑了。', '六级完形·文学类', '1298', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1299', 'CET4', 'surpass', '/səˈpɑːs/', 'v.', '超过；胜过；超越', 'The result surpassed all our expectations.', '结果超出了我们所有的预期。', '六级阅读·科研类', '1299', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1300', 'CET4', 'surplus', '/ˈsɜːpləs/', 'n./adj.', '盈余；过剩的；多余的', 'The country has a large trade surplus.', '该国拥有巨额贸易顺差。', '六级阅读·经济类', '1300', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-1301', 'CET4', 'surveillance', '/sɜːˈveɪləns/', 'n.', '监视；监督；监控', 'The city is under constant video surveillance.', '这座城市处于全天候视频监控之下。', '六级阅读·社会类', '1301', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1302', 'CET4', 'survive', '/səˈvaɪv/', 'v.', '幸存；生存；存活', 'Few plants can survive in such dry conditions.', '很少有植物能在如此干旱的条件下存活。', '四级阅读·环境类', '1302', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1303', 'CET4', 'susceptible', '/səˈseptəbl/', 'adj.', '易受影响的；易感染的', 'Older people are more susceptible to the virus.', '老年人更容易感染这种病毒。', '六级阅读·医疗类', '1303', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1304', 'CET4', 'sustain', '/səˈsteɪn/', 'v.', '维持；支撑；遭受', 'The economy cannot sustain such rapid growth.', '经济无法维持如此快速的增长。', '四级阅读·经济类', '1304', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1305', 'CET4', 'synergy', '/ˈsɪnədʒi/', 'n.', '协同作用；协同增效', 'The merger created real synergy between the teams.', '合并使两个团队产生了真正的协同效应。', '六级阅读·商业类', '1305', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1306', 'CET4', 'synthesis', '/ˈsɪnθəsɪs/', 'n.', '综合；合成；综合体', 'His theory is a synthesis of two earlier ideas.', '他的理论是对两种早期思想的综合。', '六级阅读·学术类', '1306', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1307', 'CET4', 'tablet', '/ˈtæblət/', 'n.', '药片；平板电脑；碑', 'Take one tablet after each meal.', '每餐后服一片。', '必背核心·高频词', '1307', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1308', 'CET4', 'tacit', '/ˈtæsɪt/', 'adj.', '默许的；心照不宣的', 'There was tacit agreement among the members.', '成员们达成了默契。', '六级阅读·社会类', '1308', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1309', 'CET4', 'tackle', '/ˈtækl/', 'v.', '处理；应对；解决', 'The government must tackle the problem of air pollution.', '政府必须解决空气污染问题。', '四级写作·环保类', '1309', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1310', 'CET4', 'tailor', '/ˈteɪlə(r)/', 'n./v.', '裁缝；定制；使适应', 'The suit was tailored in Shanghai.', '这套西装是在上海定做的。', '必背核心·高频词', '1310', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1311', 'CET4', 'talent', '/ˈtælənt/', 'n.', '天赋；才能；人才', 'She has a real talent for languages.', '她在语言方面真有天赋。', '必背核心·高频词', '1311', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1312', 'CET4', 'tame', '/teɪm/', 'adj./v.', '驯服的；温顺的；驯服', 'The birds were so tame they ate from his hand.', '这些鸟很温顺，从他手里吃食。', '必背核心·高频词', '1312', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1313', 'CET4', 'tangible', '/ˈtændʒəbl/', 'adj.', '有形的；实实在在的', 'The project has brought tangible benefits.', '该项目带来了实实在在的益处。', '六级写作·经济类', '1313', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1314', 'CET4', 'tank', '/tæŋk/', 'n.', '坦克；水箱；槽', 'The fish tank needs cleaning every week.', '鱼缸需要每周清洗。', '必背核心·高频词', '1314', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1315', 'CET4', 'tap', '/tæp/', 'n./v.', '水龙头；轻拍；开发', 'He turned on the tap and washed his hands.', '他打开水龙头洗了手。', '必背核心·高频词', '1315', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1316', 'CET4', 'tape', '/teɪp/', 'n./v.', '磁带；胶带；录音', 'She taped a note to the door.', '她把便条贴在门上。', '必背核心·高频词', '1316', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1317', 'CET4', 'target', '/ˈtɑːɡɪt/', 'n./v.', '目标；指标；把…作为目标', 'The campaign targets young consumers.', '这场营销活动针对年轻消费者。', '必背核心·高频词', '1317', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1318', 'CET4', 'task', '/tɑːsk/', 'n./v.', '任务；工作；派给任务', 'Finishing the report was a difficult task.', '完成这份报告是项艰巨的任务。', '必背核心·高频词', '1318', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1319', 'CET4', 'taste', '/teɪst/', 'n./v.', '味道；品味；品尝', 'The soup has a strange taste.', '这汤有股怪味。', '必背核心·高频词', '1319', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1320', 'CET4', 'tax', '/tæks/', 'n./v.', '税；征税；使负重担', 'The new tax takes effect next April.', '新税将于明年四月生效。', '必背核心·高频词', '1320', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
