  ('cet4-1322', 'CET4', 'technician', '/tekˈnɪʃn/', 'n.', '技术员；技师', 'A technician came to fix the printer.', '一位技术员来修打印机。', '必背核心·高频词', '1322', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1323', 'CET4', 'technique', '/tekˈniːk/', 'n.', '技巧；技术；手法', 'He has developed his own technique for remembering words.', '他摸索出了自己的记单词技巧。', '四级阅读·学习类', '1323', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1324', 'CET4', 'technology', '/tekˈnɒlədʒi/', 'n.', '技术；科技；工艺', 'New technology has changed our daily life.', '新技术改变了我们的日常生活。', '必背核心·高频词', '1324', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
