  ('cet4-1326', 'CET4', 'temper', '/ˈtempə(r)/', 'n./v.', '脾气；情绪；调和', 'He lost his temper over a small matter.', '他为一件小事发了脾气。', '必背核心·高频词', '1326', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1327', 'CET4', 'temperature', '/ˈtemprətʃə(r)/', 'n.', '温度；体温；气温', 'The temperature dropped below zero last night.', '昨夜气温降到了零度以下。', '必背核心·高频词', '1327', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1328', 'CET4', 'temple', '/ˈtempl/', 'n.', '寺庙；庙宇；太阳穴', 'The temple was built more than a thousand years ago.', '这座寺庙建于一千多年前。', '必背核心·高频词', '1328', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1329', 'CET4', 'temporary', '/ˈtemprəri/', 'adj.', '临时的；暂时的', 'This is only a temporary solution to the problem.', '这只是问题的权宜之计。', '四级完形·职场类', '1329', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
