  ('cet4-1336', 'CET4', 'territory', '/ˈterətri/', 'n.', '领土；领域；地区', 'The island is a dependent territory.', '该岛是一块附属领地。', '必背核心·高频词', '1336', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1337', 'CET4', 'terror', '/ˈterə(r)/', 'n.', '恐怖；惊恐；可怕的人或事', 'She screamed in terror at the sight.', '看到那一幕她惊恐地尖叫。', '必背核心·高频词', '1337', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1338', 'CET4', 'testify', '/ˈtestɪfaɪ/', 'v.', '作证；证明；表明', 'He testified that he had seen the accident.', '他作证说自己目睹了事故。', '六级阅读·法律类', '1338', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
