  ('cet4-1341', 'CET4', 'thick', '/θɪk/', 'adj.', '厚的；浓的；密集的', 'The book is too thick to finish quickly.', '这本书太厚，读不完。', '必背核心·高频词', '1341', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
