  ('cet4-1343', 'CET4', 'thorough', '/ˈθʌrə/', 'adj.', '彻底的；详尽的；认真的', 'The police carried out a thorough search.', '警方进行了彻底搜查。', '必背核心·高频词', '1343', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1344', 'CET4', 'thread', '/θred/', 'n./v.', '线；线索；穿过', 'She threaded the needle with care.', '她小心地穿针。', '必背核心·高频词', '1344', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
