  ('cet4-1346', 'CET4', 'threaten', '/ˈθretn/', 'v.', '威胁；危及', 'Pollution threatens the survival of many species.', '污染威胁着许多物种的生存。', '四级阅读·环保类', '1346', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
