  ('cet4-1348', 'CET4', 'thrive', '/θraɪv/', 'v.', '兴旺；茁壮成长', 'Small businesses thrive in this area.', '小企业在这个地区蓬勃发展。', '必背核心·高频词', '1348', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
