  ('cet4-1350', 'CET4', 'thumb', '/θʌm/', 'n./v.', '拇指；翻阅', 'He thumbed through the pages quickly.', '他快速翻着书页。', '必背核心·高频词', '1350', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
