  ('cet4-1399', 'CET4', 'unprecedented', '/ʌnˈpresɪdentɪd/', 'adj.', '前所未有的；空前的', 'The city has seen unprecedented growth.', '这座城市经历了前所未有的增长。', '六级阅读·经济类', '1399', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
