  ('cet4-1401', 'CET4', 'update', '/ˌʌpˈdeɪt/', 'v./n.', '更新；升级；最新消息', 'Please update the software regularly.', '请定期更新软件。', '必背核心·高频词', '1401', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
