  ('cet4-1403', 'CET4', 'upheaval', '/ʌpˈhiːvl/', 'n.', '剧变；动荡；隆起', 'The industry went through a period of upheaval.', '这个行业经历了一段动荡期。', '六级阅读·商业类', '1403', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
