  ('cet4-1405', 'CET4', 'upset', '/ʌpˈset/', 'adj./v./n.', '心烦的；打乱；不适', 'She was upset about the exam results.', '她为考试成绩而心烦。', '必背核心·高频词', '1405', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
