  ('cet4-1407', 'CET4', 'urgent', '/ˈɜːdʒənt/', 'adj.', '紧急的；急迫的', 'There is an urgent need for clean water.', '亟需洁净的水。', '必背核心·高频词', '1407', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1408', 'CET4', 'utility', '/juːˈtɪləti/', 'n.', '效用；公共设施；实用', 'The utility of this tool is limited.', '这个工具的用途有限。', '必背核心·高频词', '1408', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1409', 'CET4', 'utilize', '/ˈjuːtəlaɪz/', 'v.', '利用；使用', 'We should utilize solar energy more effectively.', '我们应更有效地利用太阳能。', '四级写作·环保类', '1409', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1410', 'CET4', 'vacant', '/ˈveɪkənt/', 'adj.', '空缺的；空着的；茫然的', 'No vacant rooms are left in the hotel.', '酒店已无空房。', '必背核心·高频词', '1410', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1411', 'CET4', 'vacation', '/vəˈkeɪʃn/', 'n.', '假期；休假', 'We are going to Hainan during the vacation.', '假期我们要去海南。', '必背核心·高频词', '1411', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
