  ('cet4-1483', 'CET4', 'width', '/wɪdθ/', 'n.', '宽度；广度', 'The room is six metres in width.', '这个房间宽六米。', '必背核心·高频词', '1483', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1484', 'CET4', 'wild', '/waɪld/', 'adj./n.', '野生的；狂野的；荒野', 'Wild animals should not be kept as pets.', '野生动物不应被当作宠物饲养。', '必背核心·高频词', '1484', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1485', 'CET4', 'willing', '/ˈwɪlɪŋ/', 'adj.', '愿意的；乐意的', 'He is always willing to help others.', '他总是乐于助人。', '四级完形·人物类', '1485', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1486', 'CET4', 'wind', '/wɪnd/', 'n./v.', '风；缠绕；上发条', 'A cold wind blew from the north.', '寒风从北方吹来。', '必背核心·高频词', '1486', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1487', 'CET4', 'withdraw', '/wɪðˈdrɔː/', 'v.', '撤回；退出；取款', 'You may withdraw money from any of our branches.', '你可以在我们的任何网点取款。', '四级听力·银行类', '1487', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1488', 'CET4', 'witness', '/ˈwɪtnəs/', 'n./v.', '目击者；见证；目睹', 'The past decade has witnessed great changes in China.', '过去十年见证了中国发生的巨大变化。', '四级写作·社会类', '1488', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1489', 'CET4', 'worth', '/wɜːθ/', 'adj./n.', '值得的；价值', 'The museum is well worth a second visit.', '这家博物馆很值得再去一次。', '四级阅读·旅行类', '1489', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1490', 'CET4', 'yard', '/jɑːd/', 'n.', '院子；码', 'The children were playing in the yard.', '孩子们在院子里玩耍。', '必背核心·高频词', '1490', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1491', 'CET4', 'yawn', '/jɔːn/', 'v./n.', '打哈欠；乏味的事', 'He yawned and looked at his watch.', '他打了个哈欠，看了看表。', '必背核心·高频词', '1491', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1492', 'CET4', 'year', '/jɪə(r)/', 'n.', '年；年份；年纪', 'She has worked here for ten years.', '她在这里工作十年了。', '必背核心·高频词', '1492', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1493', 'CET4', 'yearn', '/jɜːn/', 'v.', '渴望；向往；思念', 'Many city dwellers yearn for a quieter life.', '许多城市居民向往更宁静的生活。', '六级写作·社会类', '1493', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1494', 'CET4', 'yell', '/jel/', 'v./n.', '叫喊；大喊', 'Do not yell at the children.', '别对孩子们大喊大叫。', '必背核心·高频词', '1494', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1495', 'CET4', 'yellow', '/ˈjeləʊ/', 'adj./n./v.', '黄色的；黄色；变黄', 'The leaves turned yellow in October.', '树叶在十月变黄。', '必背核心·高频词', '1495', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1496', 'CET4', 'yesterday', '/ˈjestədeɪ/', 'adv./n.', '昨天；往昔', 'I saw him yesterday afternoon.', '我昨天下午见过他。', '必背核心·高频词', '1496', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1497', 'CET4', 'yet', '/jet/', 'adv./conj.', '还；仍然；然而', 'The work is not finished yet.', '这项工作还没有完成。', '必背核心·高频词', '1497', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1498', 'CET4', 'yield', '/jiːld/', 'v./n.', '产生；屈服；产量', 'This method yields much better results than the old one.', '这种方法比旧方法产生好得多的结果。', '四级阅读·科研类', '1498', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1499', 'CET4', 'yoga', '/ˈjəʊɡə/', 'n.', '瑜伽', 'She does yoga for half an hour every morning.', '她每天早上练半小时瑜伽。', '必背核心·高频词', '1499', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1500', 'CET4', 'yolk', '/jəʊk/', 'n.', '蛋黄', 'Separate the yolk from the white.', '把蛋黄和蛋白分开。', '必背核心·高频词', '1500', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet4-1501', 'CET4', 'young', '/jʌŋ/', 'adj./n.', '年轻的；幼小的；年轻人', 'The young need more opportunities.', '年轻人需要更多机会。', '必背核心·高频词', '1501', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1502', 'CET4', 'youth', '/juːθ/', 'n.', '青春；青年时期；年轻人', 'He spent his youth in the countryside.', '他在乡村度过了青年时代。', '必背核心·高频词', '1502', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1503', 'CET4', 'zeal', '/ziːl/', 'n.', '热情；热忱；干劲', 'She worked with remarkable zeal.', '她以非凡的热情投入工作。', '六级阅读·人物类', '1503', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1504', 'CET4', 'zebra', '/ˈzebrə/', 'n.', '斑马', 'We saw zebras at the safari park.', '我们在野生动物园看到了斑马。', '必背核心·高频词', '1504', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1505', 'CET4', 'zenith', '/ˈzenɪθ/', 'n.', '巅峰；最高点；天顶', 'His career reached its zenith in the 1990s.', '他的事业在二十世纪九十年代达到巅峰。', '六级阅读·人物类', '1505', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1506', 'CET4', 'zero', '/ˈzɪərəʊ/', 'n./num.', '零；零点；零度', 'The temperature fell to zero overnight.', '气温一夜之间降到零度。', '必背核心·高频词', '1506', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1507', 'CET4', 'zip', '/zɪp/', 'n./v.', '拉链；拉上拉链；快速移动', 'Your zip is undone.', '你的拉链开了。', '必背核心·高频词', '1507', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1508', 'CET4', 'zone', '/zəʊn/', 'n./v.', '地区；区域；划分', 'This area is a no-parking zone.', '这个区域禁止停车。', '必背核心·高频词', '1508', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1509', 'CET4', 'zoo', '/zuː/', 'n.', '动物园', 'The zoo is closed on Mondays.', '动物园每周一闭园。', '必背核心·高频词', '1509', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet4-1510', 'CET4', 'zoom', '/zuːm/', 'v./n.', '快速移动；变焦；嗡嗡声', 'House prices have zoomed up recently.', '最近房价飞涨。', '必背核心·高频词', '1510', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-001', 'CET6', 'abandon', '/əˈbændən/', 'v.', '放弃；抛弃；遗弃', 'The crew had to abandon the sinking ship in the heavy storm.', '在狂风暴雨中，船员们不得不弃船逃生。', '四级听力·长对话', '1', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-002', 'CET6', 'abolish', '/əˈbɒlɪʃ/', 'v.', '废除；废止（法律、制度等）', 'Many countries have abolished the death penalty.', '许多国家已经废除了死刑。', '六级阅读·法律类', '2', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-003', 'CET6', 'abrupt', '/əˈbrʌpt/', 'adj.', '突然的；意外的；（态度）粗鲁的', 'The meeting came to an abrupt end without any agreement.', '会议突然结束，没有达成任何协议。', '六级完形·新闻类', '3', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-004', 'CET6', 'absolute', '/ˈæbsəluːt/', 'adj.', '绝对的；完全的；专制的', 'There is no absolute answer to this question.', '这个问题没有绝对的答案。', '必背核心·高频词', '4', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-005', 'CET6', 'absorb', '/əbˈsɔːb/', 'v.', '吸收；理解；使全神贯注', 'Plants absorb carbon dioxide from the air and release oxygen.', '植物从空气中吸收二氧化碳并释放氧气。', '四级阅读·科普类', '5', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-006', 'CET6', 'abstract', '/ˈæbstrækt/', 'adj./n./v.', '抽象的；摘要；提取', 'The idea is too abstract for young children.', '这个概念对小孩子来说太抽象了。', '必背核心·高频词', '6', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-007', 'CET6', 'absurd', '/əbˈsɜːd/', 'adj.', '荒谬的；荒唐的', 'It is absurd to blame technology for every social problem.', '把一切社会问题都归咎于技术是荒谬的。', '六级阅读·评论类', '7', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-008', 'CET6', 'abundant', '/əˈbʌndənt/', 'adj.', '丰富的；充裕的', 'The region is abundant in natural resources.', '该地区自然资源丰富。', '六级阅读·经济类', '8', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-009', 'CET6', 'academic', '/ˌækəˈdemɪk/', 'adj.', '学术的；学业的', 'Her academic performance has improved steadily since last term.', '自上学期以来，她的学业成绩稳步提高。', '四级阅读·教育类', '9', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-010', 'CET6', 'accelerate', '/əkˈseləreɪt/', 'v.', '加速；促进', 'Technology has accelerated the pace of social change.', '技术加快了社会变革的步伐。', '六级写作·科技类', '10', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-011', 'CET6', 'access', '/ˈækses/', 'n./v.', '通道；使用权；获取', 'Students now have free access to the university’s online library.', '学生现在可以免费使用学校的在线图书馆。', '四级阅读·校园类', '11', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-012', 'CET6', 'accompany', '/əˈkʌmpəni/', 'v.', '陪伴；伴随；为…伴奏', 'Children under twelve must be accompanied by an adult.', '十二岁以下儿童必须有成人陪同。', '四级阅读·公告类', '12', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-013', 'CET6', 'accomplish', '/əˈkʌmplɪʃ/', 'v.', '完成；实现', 'She accomplished more in one year than most people do in five.', '她一年里取得的成就比多数人五年还多。', '四级阅读·人物类', '13', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-014', 'CET6', 'accumulate', '/əˈkjuːmjəleɪt/', 'v.', '积累；积聚', 'She accumulated a great deal of experience abroad.', '她在国外积累了大量经验。', '必背核心·高频词', '14', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-015', 'CET6', 'accurate', '/ˈækjərət/', 'adj.', '准确的；精确的', 'The report gives an accurate description of the local economy.', '该报告准确描述了当地经济状况。', '四级阅读·经济类', '15', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-016', 'CET6', 'accuse', '/əˈkjuːz/', 'v.', '指控；控告；指责', 'He was accused of stealing the money.', '他被指控偷了那笔钱。', '必背核心·高频词', '16', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-017', 'CET6', 'accustom', '/əˈkʌstəm/', 'v.', '使习惯于', 'It took him months to accustom himself to the climate.', '他花了几个月才适应那里的气候。', '必背核心·高频词', '17', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-018', 'CET6', 'achieve', '/əˈtʃiːv/', 'v.', '实现；达到；取得', 'Only a small number of people achieve their childhood dreams.', '只有少数人实现了儿时的梦想。', '四级阅读·社会类', '18', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-019', 'CET6', 'acknowledge', '/əkˈnɒlɪdʒ/', 'v.', '承认；致谢；告知收到', 'He refused to acknowledge that he had made a mistake.', '他拒不承认自己犯了错。', '六级阅读·社会类', '19', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-020', 'CET6', 'acquire', '/əˈkwaɪə(r)/', 'v.', '获得；习得；养成', 'Children acquire their first language without formal teaching.', '儿童无需正式教学就能习得母语。', '四级阅读·语言类', '20', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-021', 'CET6', 'acute', '/əˈkjuːt/', 'adj.', '严重的；敏锐的；急性的', 'The city is facing an acute shortage of clean water.', '这座城市面临严重的清洁用水短缺。', '六级阅读·环境类', '21', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-022', 'CET6', 'adapt', '/əˈdæpt/', 'v.', '适应；改编', 'It took him months to adapt to the new working environment.', '他花了好几个月才适应新的工作环境。', '四级完形·职场类', '22', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-023', 'CET6', 'adequate', '/ˈædɪkwət/', 'adj.', '足够的；适当的', 'The room is adequate for two people but not for a family.', '这房间住两个人足够，住一家人不够。', '四级阅读·生活类', '23', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-024', 'CET6', 'adhere', '/ədˈhɪə(r)/', 'v.', '坚持；遵守；粘附', 'All members must adhere to the club’s rules.', '所有成员都必须遵守俱乐部的规定。', '六级完形·规则类', '24', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-025', 'CET6', 'adjust', '/əˈdʒʌst/', 'v.', '调整；适应', 'You may adjust the seat to a comfortable position.', '你可以把座椅调整到舒适的位置。', '四级听力·短篇新闻', '25', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-026', 'CET6', 'admire', '/ədˈmaɪə(r)/', 'v.', '钦佩；欣赏', 'I have always admired her courage to start over at fifty.', '我一直很佩服她五十岁重新开始的勇气。', '四级阅读·人物类', '26', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-027', 'CET6', 'adopt', '/əˈdɒpt/', 'v.', '采用；采取；收养', 'The company decided to adopt a more flexible working system.', '公司决定采用更灵活的工作制度。', '四级阅读·职场类', '27', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-028', 'CET6', 'advantage', '/ədˈvɑːntɪdʒ/', 'n.', '优势；有利条件', 'Being bilingual is a great advantage in the job market.', '掌握双语在就业市场上是很大的优势。', '四级写作·教育类', '28', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-029', 'CET6', 'adverse', '/ˈædvɜːs/', 'adj.', '不利的；相反的；有害的', 'The drug may have adverse effects on children.', '这种药可能对儿童有不良影响。', '六级阅读·医疗类', '29', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-030', 'CET6', 'advocate', '/ˈædvəkeɪt/', 'v./n.', '提倡；拥护者；律师', 'Many experts advocate a balanced approach to development.', '许多专家提倡平衡的发展方式。', '六级写作·发展类', '30', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-031', 'CET6', 'aesthetic', '/iːsˈθetɪk/', 'adj./n.', '审美的；美学的；美感', 'The building is praised for its aesthetic value.', '这座建筑因其美学价值而受到称赞。', '六级阅读·艺术类', '31', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-032', 'CET6', 'affect', '/əˈfekt/', 'v.', '影响；感动', 'Lack of sleep can seriously affect your memory.', '睡眠不足会严重影响你的记忆力。', '四级阅读·健康类', '32', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-033', 'CET6', 'afford', '/əˈfɔːd/', 'v.', '负担得起；提供', 'Many young couples cannot afford to buy a house in big cities.', '许多年轻夫妇在大城市买不起房。', '四级写作·社会类', '33', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-034', 'CET6', 'agenda', '/əˈdʒendə/', 'n.', '议程；日程；议题', 'The first item on the agenda is the budget.', '议程上的第一项是预算。', '必背核心·高频词', '34', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-035', 'CET6', 'aggravate', '/ˈæɡrəveɪt/', 'v.', '加重；使恶化；激怒', 'Air pollution is aggravated by heavy traffic.', '繁忙的交通加剧了空气污染。', '六级阅读·环境类', '35', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-036', 'CET6', 'agony', '/ˈæɡəni/', 'n.', '极度痛苦；煎熬', 'She was in agony after the operation.', '手术后她痛苦不堪。', '必背核心·高频词', '36', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-037', 'CET6', 'alarm', '/əˈlɑːm/', 'n./v.', '警报；惊恐；使惊恐', 'The fire alarm went off at midnight.', '火警警报在午夜响起。', '必背核心·高频词', '37', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-038', 'CET6', 'alert', '/əˈlɜːt/', 'adj./v./n.', '警觉的；提醒；警报', 'Stay alert when driving at night.', '夜间驾车要保持警觉。', '必背核心·高频词', '38', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-039', 'CET6', 'alleviate', '/əˈliːvieɪt/', 'v.', '减轻；缓解', 'The new medicine can alleviate the symptoms of the disease.', '这种新药可以缓解该病的症状。', '六级阅读·医疗类', '39', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-040', 'CET6', 'alliance', '/əˈlaɪəns/', 'n.', '联盟；结盟；联姻', 'The two firms formed a strategic alliance.', '两家公司结成了战略联盟。', '必背核心·高频词', '40', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-041', 'CET6', 'allocate', '/ˈæləkeɪt/', 'v.', '分配；拨给', 'The government allocated more funds to rural schools.', '政府向农村学校拨了更多资金。', '六级阅读·教育类', '41', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-042', 'CET6', 'alternative', '/ɔːlˈtɜːnətɪv/', 'n./adj.', '替代方案；可供选择的', 'We had no alternative but to cancel the trip.', '我们别无选择，只能取消行程。', '四级完形·生活类', '42', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-043', 'CET6', 'ambiguous', '/æmˈbɪɡjuəs/', 'adj.', '模棱两可的；含糊的', 'His answer was deliberately ambiguous.', '他的回答故意含糊其辞。', '六级阅读·语言类', '43', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-044', 'CET6', 'ambitious', '/æmˈbɪʃəs/', 'adj.', '有雄心的；野心勃勃的', 'He is ambitious and works extremely hard.', '他很有抱负，工作极为努力。', '必背核心·高频词', '44', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-045', 'CET6', 'amplify', '/ˈæmplɪfaɪ/', 'v.', '放大；增强；详述', 'Social media can amplify both praise and criticism.', '社交媒体会放大赞美，也会放大批评。', '六级阅读·传媒类', '45', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-046', 'CET6', 'analogy', '/əˈnælədʒi/', 'n.', '类比；比拟；相似', 'The teacher drew an analogy between the brain and a computer.', '老师把大脑比作计算机。', '六级阅读·教育类', '46', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-047', 'CET6', 'analyze', '/ˈænəlaɪz/', 'v.', '分析；分解', 'Researchers analyzed the data collected from 2,000 families.', '研究者分析了从两千个家庭收集来的数据。', '四级阅读·科研类', '47', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-048', 'CET6', 'announce', '/əˈnaʊns/', 'v.', '宣布；宣告；通告', 'The company announced record profits this week.', '该公司本周宣布利润创纪录。', '必背核心·高频词', '48', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-049', 'CET6', 'anonymous', '/əˈnɒnɪməs/', 'adj.', '匿名的；无名的', 'The article was written by an anonymous author.', '这篇文章出自一位匿名作者之手。', '六级阅读·传媒类', '49', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-050', 'CET6', 'anxiety', '/æŋˈzaɪəti/', 'n.', '焦虑；担忧', 'Too much anxiety before an exam can lower your score.', '考前过度焦虑会降低你的分数。', '四级阅读·心理类', '50', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-051', 'CET6', 'apparent', '/əˈpærənt/', 'adj.', '明显的；表面上的', 'It soon became apparent that the plan would not work.', '很快就明显看出这个计划行不通。', '四级阅读·管理类', '51', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-052', 'CET6', 'appreciate', '/əˈpriːʃieɪt/', 'v.', '欣赏；感激；理解', 'I really appreciate your help with my research project.', '非常感谢你对我研究项目的帮助。', '四级听力·长对话', '52', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-053', 'CET6', 'approach', '/əˈprəʊtʃ/', 'n./v.', '方法；接近；着手处理', 'This approach has proved effective in teaching reading.', '这种方法在阅读教学中证明是有效的。', '四级阅读·教育类', '53', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-054', 'CET6', 'appropriate', '/əˈprəʊpriət/', 'adj.', '恰当的；合适的', 'Jeans are not appropriate for a formal interview.', '牛仔裤不适合正式面试。', '四级听力·职场类', '54', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-055', 'CET6', 'approve', '/əˈpruːv/', 'v.', '批准；赞成', 'The committee approved the new safety regulations yesterday.', '委员会昨天批准了新的安全条例。', '四级阅读·新闻类', '55', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-056', 'CET6', 'aptitude', '/ˈæptɪtjuːd/', 'n.', '天资；才能；悟性（aptitude test 能力倾向测试）', 'She showed a remarkable aptitude for languages.', '她表现出惊人的语言天赋。', '六级阅读·教育类', '56', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-057', 'CET6', 'arbitrary', '/ˈɑːbɪtrəri/', 'adj.', '任意的；武断的；专制的', 'The decision seemed completely arbitrary.', '这个决定看起来完全是武断的。', '六级阅读·管理类', '57', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-058', 'CET6', 'arise', '/əˈraɪz/', 'v.', '出现；产生；起因于', 'New problems may arise when the system is put into use.', '系统投入使用后可能出现新问题。', '四级完形·科技类', '58', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-059', 'CET6', 'articulate', '/ɑːˈtɪkjuleɪt/', 'v./adj.', '清晰表达；口齿清楚的', 'He found it hard to articulate his feelings.', '他发现很难把自己的感受说清楚。', '六级阅读·心理类', '59', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-060', 'CET6', 'assert', '/əˈsɜːt/', 'v.', '断言；主张；维护', 'Scientists assert that climate change is accelerating.', '科学家断言气候变化正在加速。', '六级阅读·科研类', '60', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-061', 'CET6', 'assess', '/əˈses/', 'v.', '评估；估价', 'Teachers assess students’ progress through various tests.', '教师通过各种测试评估学生的进步。', '四级阅读·教育类', '61', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-062', 'CET6', 'assume', '/əˈsjuːm/', 'v.', '假定；承担；呈现', 'Don’t assume that everyone agrees with your opinion.', '不要以为所有人都同意你的看法。', '四级阅读·交际类', '62', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-063', 'CET6', 'attach', '/əˈtætʃ/', 'v.', '附上；系上；重视', 'Please attach a recent photo to your application form.', '请在申请表上贴一张近期照片。', '四级听力·公告类', '63', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-064', 'CET6', 'attitude', '/ˈætɪtjuːd/', 'n.', '态度；看法；姿态', 'A positive attitude helps you deal with difficulties.', '积极的态度有助于你应对困难。', '四级写作·励志类', '64', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-065', 'CET6', 'attribute', '/əˈtrɪbjuːt/', 'v./n.', '把…归因于；属性；特质', 'She attributes her success to hard work and luck.', '她把自己的成功归因于努力和运气。', '六级写作·人物类', '65', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-066', 'CET6', 'augment', '/ɔːɡˈment/', 'v.', '增加；扩大；补充', 'He augmented his income by teaching at night.', '他靠晚上授课增加了收入。', '六级完形·生活类', '66', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-067', 'CET6', 'authentic', '/ɔːˈθentɪk/', 'adj.', '真正的；真迹的；可信的', 'The museum only displays authentic works of art.', '这家博物馆只展出真迹艺术品。', '六级阅读·文化类', '67', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-068', 'CET6', 'autonomy', '/ɔːˈtɒnəmi/', 'n.', '自治；自主权', 'Universities should enjoy greater academic autonomy.', '大学应享有更大的学术自主权。', '六级阅读·教育类', '68', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-069', 'CET6', 'available', '/əˈveɪləbl/', 'adj.', '可获得的；有空的', 'Tickets are available at the box office until 8 p.m.', '售票处下午八点前都有票。', '四级听力·短篇新闻', '69', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-070', 'CET6', 'aware', '/əˈweə(r)/', 'adj.', '意识到的；知道的', 'Few people are aware of how much water they waste daily.', '很少有人意识到自己每天浪费多少水。', '四级阅读·环保类', '70', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-071', 'CET6', 'backward', '/ˈbækwəd/', 'adv./adj.', '向后；倒退的；落后的', 'He took a step backward to get a better view.', '他向后退了一步以便看得更清楚。', '四级听力·短篇新闻', '71', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-072', 'CET6', 'bacteria', '/bækˈtɪəriə/', 'n.', '细菌', 'Washing your hands regularly helps prevent bacteria from spreading.', '勤洗手有助于防止细菌传播。', '四级阅读·健康类', '72', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-073', 'CET6', 'balance', '/ˈbæləns/', 'n./v.', '平衡；余额；使平衡', 'It is hard to keep a balance between work and family.', '在工作与家庭之间保持平衡很难。', '四级写作·生活类', '73', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-074', 'CET6', 'barrier', '/ˈbæriə(r)/', 'n.', '障碍；屏障', 'Language is often the biggest barrier to communication.', '语言常常是沟通的最大障碍。', '四级阅读·社会类', '74', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-075', 'CET6', 'basis', '/ˈbeɪsɪs/', 'n.', '基础；根据；原则', 'The decision was made on the basis of reliable data.', '这个决定是基于可靠数据作出的。', '四级阅读·科研类', '75', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-076', 'CET6', 'behalf', '/bɪˈhɑːf/', 'n.', '代表；利益', 'On behalf of the team, I would like to thank you.', '我代表全队向你表示感谢。', '四级写作·应用文', '76', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-077', 'CET6', 'behave', '/bɪˈheɪv/', 'v.', '表现；举止；运转', 'Parents should teach children how to behave in public.', '父母应教孩子如何在公共场合举止得体。', '四级阅读·教育类', '77', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-078', 'CET6', 'belief', '/bɪˈliːf/', 'n.', '信念；相信；看法', 'There is a growing belief that exercise improves mental health.', '越来越多人相信锻炼能改善心理健康。', '四级阅读·健康类', '78', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-079', 'CET6', 'belong', '/bɪˈlɒŋ/', 'v.', '属于；应归入', 'These books belong to the school library.', '这些书属于学校图书馆。', '四级完形·校园类', '79', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-080', 'CET6', 'beneath', '/bɪˈniːθ/', 'prep./adv.', '在…之下；低于', 'The subway runs beneath the busy commercial street.', '地铁在繁忙的商业街下方穿行。', '四级阅读·城市类', '80', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-081', 'CET6', 'benefit', '/ˈbenɪfɪt/', 'n./v.', '益处；受益', 'Regular exercise benefits both your body and your mind.', '规律锻炼对身心都有好处。', '四级写作·健康类', '81', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-082', 'CET6', 'blame', '/bleɪm/', 'v./n.', '责备；归咎；责任', 'Don’t blame others for your own mistakes.', '不要把自己的错误归咎于别人。', '四级写作·成长类', '82', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-083', 'CET6', 'blend', '/blend/', 'v./n.', '混合；融合', 'The new design blends tradition with modern style.', '新设计把传统与现代风格融合在一起。', '四级阅读·文化类', '83', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-084', 'CET6', 'block', '/blɒk/', 'n./v.', '街区；块；阻挡', 'A fallen tree blocked the road for two hours.', '一棵倒下的树把路堵了两个小时。', '四级听力·短篇新闻', '84', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-085', 'CET6', 'blunder', '/ˈblʌndə(r)/', 'n./v.', '大错；犯大错；跌跌撞撞', 'The company never recovered from that costly blunder.', '公司再也没有从那个代价惨重的错误中恢复过来。', '六级完形·商业类', '85', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-086', 'CET6', 'bond', '/bɒnd/', 'n./v.', '纽带；债券；结合', 'Shared experiences create a strong bond between teammates.', '共同的经历在队友间形成牢固纽带。', '四级阅读·社会类', '86', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-087', 'CET6', 'boost', '/buːst/', 'v./n.', '促进；提高；推动', 'The new policy is expected to boost employment.', '新政策有望促进就业。', '四级阅读·经济类', '87', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-088', 'CET6', 'border', '/ˈbɔːdə(r)/', 'n./v.', '边界；边境；接壤', 'The two countries share a border of over 900 kilometres.', '两国共享九百多公里的边界。', '四级阅读·地理类', '88', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-089', 'CET6', 'bound', '/baʊnd/', 'adj./v.', '必然的；受约束的；跳跃', 'You are bound to make progress if you keep practicing.', '只要坚持练习，你一定会进步。', '四级写作·学习类', '89', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-090', 'CET6', 'brake', '/breɪk/', 'n./v.', '刹车；制动', 'He braked suddenly to avoid hitting the dog.', '他急刹车以免撞到那只狗。', '四级听力·长对话', '90', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet6-091', 'CET6', 'branch', '/brɑːntʃ/', 'n.', '分支；分部；树枝', 'The bank has opened ten new branches this year.', '这家银行今年新开了十家分行。', '四级阅读·经济类', '91', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-092', 'CET6', 'brand', '/brænd/', 'n./v.', '品牌；牌子', 'Many young consumers prefer domestic brands now.', '现在许多年轻消费者更青睐国产品牌。', '四级阅读·消费类', '92', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-093', 'CET6', 'brave', '/breɪv/', 'adj.', '勇敢的；无畏的', 'It was brave of her to speak in front of so many people.', '她敢于在这么多人面前发言，很勇敢。', '四级阅读·人物类', '93', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-094', 'CET6', 'breach', '/briːtʃ/', 'n./v.', '违反；破坏；缺口', 'The firm was fined for a breach of contract.', '该公司因违约被罚款。', '六级阅读·法律类', '94', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-095', 'CET6', 'breed', '/briːd/', 'v./n.', '繁殖；培育；品种', 'Some birds breed twice a year in warm areas.', '一些鸟类在温暖地区一年繁殖两次。', '四级阅读·科普类', '95', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-096', 'CET6', 'brief', '/briːf/', 'adj./v./n.', '简短的；简要介绍；摘要', 'He gave a brief summary of the research findings.', '他简要总结了研究结果。', '四级听力·讲座', '96', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-097', 'CET6', 'brilliant', '/ˈbrɪliənt/', 'adj.', '卓越的；明亮的；才华横溢的', 'She came up with a brilliant solution to the problem.', '她想出了一个极妙的解决办法。', '四级阅读·人物类', '97', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
