  ('cet6-162', 'CET6', 'diminish', '/dɪˈmɪnɪʃ/', 'v.', '减少；缩小；降低', 'The pain gradually diminished after treatment.', '治疗后疼痛逐渐减轻。', '六级阅读·医疗类', '162', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-163', 'CET6', 'discern', '/dɪˈsɜːn/', 'v.', '辨别；看出；察觉', 'It is difficult to discern the truth from his words.', '很难从他的话中辨别出真相。', '六级阅读·语言类', '163', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-164', 'CET6', 'disclose', '/dɪsˈkləʊz/', 'v.', '披露；揭露；公开', 'The company refused to disclose the details.', '公司拒绝披露细节。', '六级阅读·商业类', '164', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-165', 'CET6', 'discrepancy', '/dɪsˈkrepənsi/', 'n.', '差异；不一致；矛盾', 'There is a discrepancy between the two reports.', '两份报告之间存在出入。', '六级阅读·科研类', '165', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-166', 'CET6', 'displace', '/dɪsˈpleɪs/', 'v.', '取代；迫使离开家园', 'Thousands were displaced by the flood.', '成千上万的人因洪灾被迫离开家园。', '六级阅读·新闻类', '166', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-167', 'CET6', 'disrupt', '/dɪsˈrʌpt/', 'v.', '扰乱；中断；打乱', 'The strike disrupted rail services across the country.', '罢工扰乱了全国的铁路运营。', '六级阅读·社会类', '167', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-168', 'CET6', 'dissipate', '/ˈdɪsɪpeɪt/', 'v.', '消散；挥霍；浪费', 'The fog dissipated as the sun rose.', '太阳升起时雾散了。', '六级完形·环境类', '168', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-169', 'CET6', 'distinguish', '/dɪˈstɪŋɡwɪʃ/', 'v.', '区分；辨别', 'Children must learn to distinguish fact from opinion.', '儿童必须学会区分事实与观点。', '四级阅读·教育类', '169', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-170', 'CET6', 'diverse', '/daɪˈvɜːs/', 'adj.', '多样的；不同的', 'The city is home to a diverse population.', '这座城市居住着多元化的人口。', '六级写作·社会类', '170', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-171', 'CET6', 'dominate', '/ˈdɒmɪneɪt/', 'v.', '支配；主导；俯视', 'A few firms dominate the global market.', '少数几家公司在全球市场占主导地位。', '六级阅读·经济类', '171', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-172', 'CET6', 'drastic', '/ˈdræstɪk/', 'adj.', '激烈的；极端的；严厉的', 'Drastic measures are needed to save the industry.', '拯救这个行业需要采取激烈的措施。', '六级阅读·经济类', '172', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-173', 'CET6', 'dubious', '/ˈdjuːbiəs/', 'adj.', '可疑的；靠不住的；犹豫的', 'The benefits of this diet are highly dubious.', '这种饮食的益处非常可疑。', '六级阅读·健康类', '173', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-174', 'CET6', 'duplicate', '/ˈdjuːplɪkeɪt/', 'v./n.', '复制；副本；完全一样的', 'Please keep a duplicate of all your receipts.', '请保留所有收据的副本。', '六级阅读·职场类', '174', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-175', 'CET6', 'eccentric', '/ɪkˈsentrɪk/', 'adj./n.', '古怪的；怪人', 'He is known for his eccentric way of dressing.', '他以古怪的着装方式著称。', '六级完形·人物类', '175', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-176', 'CET6', 'efficient', '/ɪˈfɪʃnt/', 'adj.', '高效的；效率高的', 'Public transport is a more efficient way to travel.', '公共交通是一种更高效的出行方式。', '四级写作·环保类', '176', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-177', 'CET6', 'elicit', '/iˈlɪsɪt/', 'v.', '引出；探出；诱出', 'The question elicited a surprising response.', '这个问题引出了令人意外的回应。', '六级阅读·科研类', '177', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-178', 'CET6', 'eliminate', '/ɪˈlɪmɪneɪt/', 'v.', '消除；排除；淘汰', 'The new process eliminates the need for paper records.', '新流程免除了纸质记录的需要。', '四级阅读·科技类', '178', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-179', 'CET6', 'elite', '/eɪˈliːt/', 'n./adj.', '精英；精英的', 'The university aims to educate the future elite.', '这所大学旨在培养未来的精英。', '六级阅读·教育类', '179', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-180', 'CET6', 'embark', '/ɪmˈbɑːk/', 'v.', '上船；着手；开始', 'She is about to embark on a new career.', '她即将开始一项新的事业。', '六级阅读·职业类', '180', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-181', 'CET6', 'emerge', '/iˈmɜːdʒ/', 'v.', '出现；显露；兴起', 'New technologies emerge almost every month.', '新技术几乎每个月都在涌现。', '四级阅读·科技类', '181', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-182', 'CET6', 'eminent', '/ˈemɪnənt/', 'adj.', '著名的；杰出的', 'He is an eminent scholar in this field.', '他是该领域著名的学者。', '六级阅读·学术类', '182', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-183', 'CET6', 'emphasize', '/ˈemfəsaɪz/', 'v.', '强调；着重', 'The teacher emphasized the importance of taking notes.', '老师强调了记笔记的重要性。', '四级听力·长对话', '183', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-184', 'CET6', 'empirical', '/ɪmˈpɪrɪkl/', 'adj.', '实证的；经验主义的', 'There is little empirical evidence for the claim.', '这一说法几乎没有实证依据。', '六级阅读·科研类', '184', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-185', 'CET6', 'encompass', '/ɪnˈkʌmpəs/', 'v.', '包含；涵盖；包围', 'The term encompasses a wide range of activities.', '这个术语涵盖范围很广的活动。', '六级阅读·学术类', '185', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-186', 'CET6', 'endorse', '/ɪnˈdɔːs/', 'v.', '认可；支持；背书', 'The plan was endorsed by the majority of members.', '该计划得到了多数成员的认可。', '六级阅读·政治类', '186', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-187', 'CET6', 'enhance', '/ɪnˈhɑːns/', 'v.', '提高；增强', 'Reading widely can enhance your vocabulary.', '广泛阅读能扩充你的词汇量。', '四级阅读·语言类', '187', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-188', 'CET6', 'ensure', '/ɪnˈʃʊə(r)/', 'v.', '确保；保证', 'Please ensure that all the windows are closed before you leave.', '离开前请确保所有窗户都关好。', '四级听力·公告类', '188', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-189', 'CET6', 'entail', '/ɪnˈteɪl/', 'v.', '需要；牵涉；使必要', 'The job entails a lot of responsibility.', '这份工作需要承担很多责任。', '六级阅读·职场类', '189', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-190', 'CET6', 'environment', '/ɪnˈvaɪrənmənt/', 'n.', '环境；自然环境', 'We should protect the environment for future generations.', '我们应为子孙后代保护环境。', '四级写作·环保类', '190', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet6-191', 'CET6', 'envision', '/ɪnˈvɪʒn/', 'v.', '设想；展望', 'Few people envisioned such rapid progress.', '很少有人预见到如此迅速的进展。', '六级写作·科技类', '191', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-192', 'CET6', 'epidemic', '/ˌepɪˈdemɪk/', 'n./adj.', '流行病；蔓延的', 'Obesity has become a global epidemic.', '肥胖已成为一种全球性流行病。', '六级阅读·健康类', '192', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-193', 'CET6', 'erode', '/ɪˈrəʊd/', 'v.', '侵蚀；腐蚀；削弱', 'Constant criticism eroded her confidence.', '不断的批评削弱了她的自信。', '六级阅读·心理类', '193', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-194', 'CET6', 'essential', '/ɪˈsenʃl/', 'adj./n.', '必要的；本质的；要素', 'Sleep is essential to both physical and mental health.', '睡眠对身心健康都必不可少。', '四级阅读·健康类', '194', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-195', 'CET6', 'establish', '/ɪˈstæblɪʃ/', 'v.', '建立；创立；确定', 'The school was established more than a century ago.', '这所学校建立于一个多世纪前。', '四级阅读·教育类', '195', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-196', 'CET6', 'estimate', '/ˈestɪmeɪt/', 'v./n.', '估计；估价', 'Experts estimate that the damage will reach ten million dollars.', '专家估计损失将达到一千万美元。', '四级阅读·新闻类', '196', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-197', 'CET6', 'evaluate', '/ɪˈvæljueɪt/', 'v.', '评价；评估', 'Students are asked to evaluate their own progress each month.', '学生被要求每月评估自己的进步。', '四级阅读·教育类', '197', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-198', 'CET6', 'evidence', '/ˈevɪdəns/', 'n.', '证据；迹象', 'There is growing evidence that exercise improves memory.', '越来越多的证据表明锻炼能改善记忆力。', '四级阅读·健康类', '198', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-199', 'CET6', 'exacerbate', '/ɪɡˈzæsəbeɪt/', 'v.', '使恶化；加剧', 'The drought exacerbated the food shortage.', '干旱加剧了粮食短缺。', '六级阅读·环境类', '199', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-200', 'CET6', 'exaggerate', '/ɪɡˈzædʒəreɪt/', 'v.', '夸大；夸张', 'The report exaggerates the risks involved.', '报告夸大了其中的风险。', '六级阅读·传媒类', '200', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-201', 'CET6', 'exclusive', '/ɪkˈskluːsɪv/', 'adj./n.', '独家的；排外的；专访', 'The magazine obtained an exclusive interview.', '该杂志获得了独家专访。', '六级阅读·传媒类', '201', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-202', 'CET6', 'exert', '/ɪɡˈzɜːt/', 'v.', '施加；运用；努力', 'Parents exert a strong influence on children.', '父母对孩子施加强大的影响。', '六级写作·家庭类', '202', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-203', 'CET6', 'exotic', '/ɪɡˈzɒtɪk/', 'adj.', '异国的；外来的；奇异的', 'The market sells a variety of exotic fruits.', '市场出售各种异国水果。', '六级阅读·文化类', '203', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-204', 'CET6', 'expand', '/ɪkˈspænd/', 'v.', '扩大；膨胀；扩展', 'The company plans to expand its business into Asia.', '公司计划把业务扩展到亚洲。', '四级阅读·商业类', '204', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-205', 'CET6', 'expenditure', '/ɪkˈspendɪtʃə(r)/', 'n.', '支出；消耗；经费', 'Public expenditure on education has risen sharply.', '公共教育支出大幅上升。', '六级阅读·经济类', '205', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-206', 'CET6', 'expertise', '/ˌekspɜːˈtiːz/', 'n.', '专业知识；专长', 'We value his expertise in financial management.', '我们看重他在财务管理方面的专长。', '六级阅读·职场类', '206', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-207', 'CET6', 'explicit', '/ɪkˈsplɪsɪt/', 'adj.', '明确的；清楚的；直言的', 'The contract is explicit about payment terms.', '合同对付款条件有明确规定。', '六级阅读·法律类', '207', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-208', 'CET6', 'exploit', '/ɪkˈsplɔɪt/', 'v./n.', '利用；剥削；功绩', 'Companies should not exploit cheap labour.', '公司不应剥削廉价劳动力。', '六级阅读·社会类', '208', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-209', 'CET6', 'extract', '/ɪkˈstrækt/', 'v./n.', '提取；摘录；摘录片段', 'Scientists extracted DNA from the ancient bone.', '科学家从这块古骨中提取了DNA。', '六级阅读·科研类', '209', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-210', 'CET6', 'fabricate', '/ˈfæbrɪkeɪt/', 'v.', '捏造；伪造；制造', 'The evidence was later shown to be fabricated.', '该证据后来被证明是伪造的。', '六级阅读·法律类', '210', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-211', 'CET6', 'facility', '/fəˈsɪləti/', 'n.', '设施；设备；便利', 'The school has excellent sports facilities.', '这所学校有出色的体育设施。', '四级阅读·校园类', '211', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-212', 'CET6', 'factor', '/ˈfæktə(r)/', 'n.', '因素；要素', 'Cost is the key factor in choosing a supplier.', '成本是选择供应商的关键因素。', '四级阅读·经济类', '212', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-213', 'CET6', 'faculty', '/ˈfæklti/', 'n.', '全体教员；院系；能力', 'The faculty members meet every Monday morning.', '全体教员每周一上午开会。', '四级阅读·教育类', '213', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-214', 'CET6', 'failure', '/ˈfeɪljə(r)/', 'n.', '失败；故障；失败者', 'He regarded the setback as a lesson rather than a failure.', '他把这次挫折看作教训而非失败。', '四级写作·成长类', '214', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-215', 'CET6', 'faint', '/feɪnt/', 'adj./v.', '微弱的；模糊的；昏倒', 'There is still a faint hope of finding survivors.', '找到幸存者仍有一线希望。', '四级阅读·新闻类', '215', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-216', 'CET6', 'faith', '/feɪθ/', 'n.', '信任；信念；信心', 'She has great faith in her students’ abilities.', '她对学生的能力充满信心。', '四级阅读·教育类', '216', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-217', 'CET6', 'fallacy', '/ˈfæləsi/', 'n.', '谬误；谬见', 'The belief that success comes overnight is a fallacy.', '认为成功是一夜之间到来的想法是一种谬见。', '六级写作·励志类', '217', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-218', 'CET6', 'familiar', '/fəˈmɪliə(r)/', 'adj.', '熟悉的；常见的', 'His face looks familiar, but I can’t recall his name.', '他看起来面熟，但我想不起名字。', '四级听力·长对话', '218', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-219', 'CET6', 'fancy', '/ˈfænsi/', 'adj./v./n.', '花哨的；喜欢；幻想', 'We don’t need a fancy car, just a reliable one.', '我们不需要花哨的车，可靠的就行。', '四级阅读·消费类', '219', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-220', 'CET6', 'fare', '/feə(r)/', 'n.', '车费；票价；伙食', 'Bus fares will rise by ten percent next month.', '公交票价下月将上涨百分之十。', '四级阅读·民生类', '220', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-221', 'CET6', 'fascinate', '/ˈfæsɪneɪt/', 'v.', '使着迷；吸引', 'The way children learn language fascinates researchers.', '儿童学习语言的方式令研究者着迷。', '六级阅读·语言类', '221', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
