  ('cet6-373', 'CET6', 'illegal', '/ɪˈliːɡl/', 'adj.', '非法的；违法的', 'It is illegal to park here during rush hour.', '高峰时段在此停车是违法的。', '必背核心·高频词', '373', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-374', 'CET6', 'illuminate', '/ɪˈluːmɪneɪt/', 'v.', '照亮；阐明；启发', 'His talk illuminated the causes of the conflict.', '他的讲话阐明了冲突的起因。', '六级阅读·学术类', '374', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-375', 'CET6', 'illusion', '/ɪˈluːʒn/', 'n.', '幻想；错觉；假象', 'Freedom from worry is only an illusion.', '无忧无虑只是一种幻想。', '六级写作·人生类', '375', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-376', 'CET6', 'illustrate', '/ˈɪləstreɪt/', 'v.', '说明；阐明；举例说明', 'Let me illustrate this point with an example.', '让我举个例子说明这一点。', '必背核心·高频词', '376', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-377', 'CET6', 'imitate', '/ˈɪmɪteɪt/', 'v.', '模仿；仿效', 'Young children learn by imitating adults.', '幼儿通过模仿成人来学习。', '必背核心·高频词', '377', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
