  ('cet6-380', 'CET6', 'immune', '/ɪˈmjuːn/', 'adj.', '免疫的；免除的；不受影响的', 'No one is immune to the effects of stress.', '没有人能免受压力的影响。', '六级阅读·健康类', '380', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
