  ('cet6-382', 'CET6', 'imperative', '/ɪmˈperətɪv/', 'adj./n.', '必要的；紧急的；祈使语气', 'Immediate action is imperative.', '立即采取行动是当务之急。', '六级写作·环保类', '382', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
