  ('cet6-384', 'CET6', 'implement', '/ˈɪmplɪment/', 'v./n.', '实施；执行；工具', 'The new rules will be implemented next semester.', '新规定将于下学期实施。', '四级阅读·校园类', '384', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-385', 'CET6', 'implicit', '/ɪmˈplɪsɪt/', 'adj.', '含蓄的；隐含的；绝对的', 'His silence carried an implicit criticism.', '他的沉默含有含蓄的批评。', '六级阅读·语言类', '385', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-386', 'CET6', 'imply', '/ɪmˈplaɪ/', 'v.', '暗示；意味着', 'His silence implied that he disagreed.', '他的沉默暗示他不同意。', '必背核心·高频词', '386', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-387', 'CET6', 'impose', '/ɪmˈpəʊz/', 'v.', '强加；征收；推行', 'The city imposed a tax on plastic bags.', '该市对塑料袋征税。', '必背核心·高频词', '387', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-388', 'CET6', 'impress', '/ɪmˈpres/', 'v.', '使印象深刻；使铭记', 'She impressed the interviewers with her confidence.', '她的自信给面试官留下深刻印象。', '必背核心·高频词', '388', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-389', 'CET6', 'improve', '/ɪmˈpruːv/', 'v.', '改善；提高；改进', 'Regular exercise improves both health and mood.', '规律运动能改善健康和情绪。', '必背核心·高频词', '389', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-390', 'CET6', 'incentive', '/ɪnˈsentɪv/', 'n.', '激励；刺激；动机', 'Tax breaks provide an incentive to invest.', '税收减免提供了投资激励。', '六级阅读·经济类', '390', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
