  ('cet6-595', 'CET6', 'media', '/ˈmiːdiə/', 'n.', '媒体；新闻媒介', 'Social media has changed how we get news.', '社交媒体改变了我们获取新闻的方式。', '必背核心·高频词', '595', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-596', 'CET6', 'mediate', '/ˈmiːdieɪt/', 'v.', '调解；斡旋；居中', 'The UN mediated between the two sides.', '联合国在双方之间进行了调解。', '六级阅读·政治类', '596', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-597', 'CET6', 'medical', '/ˈmedɪkl/', 'adj.', '医学的；医疗的', 'Medical research needs long-term investment.', '医学研究需要长期投入。', '必背核心·高频词', '597', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
