  ('cet6-599', 'CET6', 'mediocre', '/ˌmiːdiˈəʊkə(r)/', 'adj.', '平庸的；普通的', 'The film was pleasant but mediocre.', '这部电影还算好看，但很平庸。', '六级阅读·艺术类', '599', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-600', 'CET6', 'medium', '/ˈmiːdiəm/', 'n./adj.', '媒介；手段；中等的', 'Television remains a powerful advertising medium.', '电视仍是强大的广告媒介。', '必背核心·高频词', '600', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-601', 'CET6', 'memory', '/ˈmeməri/', 'n.', '记忆；回忆；存储器', 'He has a remarkable memory for names.', '他对名字的记忆力惊人。', '必背核心·高频词', '601', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-602', 'CET6', 'mental', '/ˈmentl/', 'adj.', '精神的；心理的；智力的', 'Regular exercise improves both physical and mental health.', '规律锻炼能改善身心健康。', '四级阅读·健康类', '602', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-603', 'CET6', 'mention', '/ˈmenʃn/', 'v./n.', '提到；提及', 'She mentioned the problem at the meeting.', '她在会上提到了这个问题。', '必背核心·高频词', '603', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-604', 'CET6', 'mercy', '/ˈmɜːsi/', 'n.', '仁慈；宽恕；幸运', 'The survivors were at the mercy of the sea.', '幸存者听凭大海摆布。', '必背核心·高频词', '604', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-605', 'CET6', 'mere', '/mɪə(r)/', 'adj.', '仅仅的；只不过的', 'The journey took a mere twenty minutes.', '这趟旅程只花了二十分钟。', '必背核心·高频词', '605', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
