  ('cet6-691', 'CET6', 'nowhere', '/ˈnəʊweə(r)/', 'adv.', '无处；任何地方都不', 'The key was nowhere to be found.', '钥匙到处都找不到。', '必背核心·高频词', '691', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-692', 'CET6', 'nuance', '/ˈnjuːɑːns/', 'n.', '细微差别；微妙之处', 'Good translators capture every nuance of meaning.', '优秀的译者能捕捉意义的每一个细微差别。', '六级翻译·技巧类', '692', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-693', 'CET6', 'nuclear', '/ˈnjuːkliə(r)/', 'adj.', '核的；原子核的', 'The country plans to build two nuclear plants.', '该国计划建造两座核电站。', '必背核心·高频词', '693', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-694', 'CET6', 'numerous', '/ˈnjuːmərəs/', 'adj.', '众多的；许多的', 'She has visited numerous countries in Asia.', '她访问过许多亚洲国家。', '必背核心·高频词', '694', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-695', 'CET6', 'nurse', '/nɜːs/', 'n./v.', '护士；护理；照料', 'The nurse checked his temperature every hour.', '护士每小时给他量一次体温。', '必背核心·高频词', '695', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-696', 'CET6', 'nurture', '/ˈnɜːtʃə(r)/', 'v./n.', '培养；养育；滋养', 'Schools should nurture creativity in children.', '学校应培养儿童的创造力。', '六级写作·教育类', '696', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-697', 'CET6', 'obey', '/əˈbeɪ/', 'v.', '服从；遵守', 'All drivers must obey the traffic rules.', '所有驾驶员都必须遵守交通规则。', '必背核心·高频词', '697', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-698', 'CET6', 'object', '/ˈɒbdʒɪkt/', 'n./v.', '物体；目标；反对', 'He objected to the plan at the meeting.', '他在会上反对这项计划。', '必背核心·高频词', '698', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-699', 'CET6', 'objective', '/əbˈdʒektɪv/', 'n./adj.', '目标；客观的', 'Try to keep an objective view of the problem.', '尽量对问题保持客观的看法。', '必背核心·高频词', '699', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
