  ('cet6-704', 'CET6', 'obsolete', '/ˈɒbsəliːt/', 'adj.', '过时的；废弃的', 'The skill will soon become obsolete.', '这项技能很快就会过时。', '六级阅读·科技类', '704', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
