  ('cet6-708', 'CET6', 'occasion', '/əˈkeɪʒn/', 'n.', '场合；时机；时刻', 'I wear this suit only on special occasions.', '我只在特殊场合穿这套西装。', '必背核心·高频词', '708', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-709', 'CET6', 'occupy', '/ˈɒkjupaɪ/', 'v.', '占据；占用；占领', 'The desk occupies too much space.', '这张桌子占地方太多。', '必背核心·高频词', '709', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-710', 'CET6', 'occur', '/əˈkɜː(r)/', 'v.', '发生；出现；想起', 'The accident occurred at about seven o’clock.', '事故发生在大约七点钟。', '必背核心·高频词', '710', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
