  ('cet6-713', 'CET6', 'offence', '/əˈfens/', 'n.', '犯罪；冒犯；违法行为', 'Parking here is a serious offence.', '在此停车属严重违章。', '必背核心·高频词', '713', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-714', 'CET6', 'offer', '/ˈɒfə(r)/', 'v./n.', '提供；提议；报价', 'The company offered him a higher salary.', '公司给了他更高的薪水。', '必背核心·高频词', '714', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
