  ('cet6-727', 'CET6', 'oppose', '/əˈpəʊz/', 'v.', '反对；反抗', 'Local people strongly oppose the new airport.', '当地居民强烈反对新机场。', '必背核心·高频词', '727', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
