  ('cet6-730', 'CET6', 'option', '/ˈɒpʃn/', 'n.', '选择；选项；选修课', 'Students have several options after graduation.', '学生毕业后有多种选择。', '必背核心·高频词', '730', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-731', 'CET6', 'orange', '/ˈɒrɪndʒ/', 'n./adj.', '橙子；橙色（的）', 'She peeled an orange and shared it.', '她剥了一个橙子分给大家。', '必背核心·高频词', '731', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-732', 'CET6', 'orbit', '/ˈɔːbɪt/', 'n./v.', '轨道；环绕运行', 'The satellite orbits the earth every ninety minutes.', '这颗卫星每九十分钟绕地球一圈。', '必背核心·高频词', '732', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-733', 'CET6', 'orchestra', '/ˈɔːkɪstrə/', 'n.', '管弦乐队', 'The school orchestra performed at the hall.', '学校管弦乐队在礼堂演出。', '必背核心·高频词', '733', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-734', 'CET6', 'order', '/ˈɔːdə(r)/', 'n./v.', '命令；秩序；订购', 'He ordered a cup of coffee and sat down.', '他点了一杯咖啡坐下。', '必背核心·高频词', '734', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
