  ('cet6-741', 'CET6', 'orthodox', '/ˈɔːθədɒks/', 'adj.', '正统的；传统的；因循守旧的', 'His methods were far from orthodox.', '他的方法远非传统。', '六级阅读·学术类', '741', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-742', 'CET6', 'outbreak', '/ˈaʊtbreɪk/', 'n.', '（战争、疾病）爆发', 'The outbreak of the disease alarmed the world.', '该病的爆发令世界警觉。', '六级阅读·新闻类', '742', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
