  ('cet6-791', 'CET6', 'patience', '/ˈpeɪʃns/', 'n.', '耐心；忍耐', 'Teaching young children requires patience.', '教小孩子需要耐心。', '必背核心·高频词', '791', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
