  ('cet6-798', 'CET6', 'peace', '/piːs/', 'n.', '和平；平静；安宁', 'The two sides finally signed a peace deal.', '双方最终签署了和平协议。', '必背核心·高频词', '798', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
