  ('cet6-1091', 'CET6', 'regime', '/reɪˈʒiːm/', 'n.', '政权；体制；养生法', 'The old regime was replaced after the election.', '旧政权在选举后被取代。', '六级阅读·政治类', '1091', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
