  ('cet6-1099', 'CET6', 'relate', '/rɪˈleɪt/', 'v.', '联系；叙述；涉及', 'The report relates poverty to poor education.', '这份报告把贫困与教育落后联系起来。', '必背核心·高频词', '1099', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1100', 'CET6', 'relative', '/ˈrelətɪv/', 'n./adj.', '亲戚；相对的；有关的', 'She invited all her relatives to the wedding.', '她邀请了所有亲戚参加婚礼。', '必背核心·高频词', '1100', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1101', 'CET6', 'relax', '/rɪˈlæks/', 'v.', '放松；使轻松；放宽', 'Music helps me relax after work.', '音乐帮我下班后放松。', '必背核心·高频词', '1101', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1102', 'CET6', 'release', '/rɪˈliːs/', 'v./n.', '释放；发布；放开', 'The film will be released next month.', '这部影片将于下月上映。', '必背核心·高频词', '1102', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
