  ('cet6-1107', 'CET6', 'religion', '/rɪˈlɪdʒən/', 'n.', '宗教；信仰', 'People of many religions live here peacefully.', '多种宗教信仰的人在此和平共处。', '必背核心·高频词', '1107', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1108', 'CET6', 'relinquish', '/rɪˈlɪŋkwɪʃ/', 'v.', '放弃；交出；让予', 'He reluctantly relinquished control of the firm.', '他勉强交出了公司的控制权。', '六级阅读·商业类', '1108', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1109', 'CET6', 'reluctant', '/rɪˈlʌktənt/', 'adj.', '不情愿的；勉强的', 'He was reluctant to admit his own mistake.', '他不愿承认自己的错误。', '四级完形·人物类', '1109', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1110', 'CET6', 'rely', '/rɪˈlaɪ/', 'v.', '依赖；信赖', 'You can rely on her promise.', '你可以相信她的承诺。', '必背核心·高频词', '1110', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
