  ('cet6-1113', 'CET6', 'remedy', '/ˈremədi/', 'n./v.', '疗法；补救办法；纠正', 'There is no easy remedy for this problem.', '这个问题没有简单的解决办法。', '必背核心·高频词', '1113', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1114', 'CET6', 'remind', '/rɪˈmaɪnd/', 'v.', '提醒；使想起', 'Please remind me to hand in the report tomorrow.', '请提醒我明天交报告。', '四级听力·短对话', '1114', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
