  ('cet6-1121', 'CET6', 'repercussion', '/ˌriːpəˈkʌʃn/', 'n.', '后果；反响；影响', 'The decision had serious repercussions.', '这一决定产生了严重后果。', '六级阅读·社会类', '1121', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
