  ('cet6-1123', 'CET6', 'reply', '/rɪˈplaɪ/', 'v./n.', '回答；答复', 'He has not replied to my message yet.', '他还没有回复我的消息。', '必背核心·高频词', '1123', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
