  ('cet6-1125', 'CET6', 'republic', '/rɪˈpʌblɪk/', 'n.', '共和国；共和政体', 'The country became a republic in 1949.', '该国于1949年成为共和国。', '必背核心·高频词', '1125', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1126', 'CET6', 'reputation', '/ˌrepjuˈteɪʃn/', 'n.', '名声；声誉', 'The school has an excellent reputation.', '这所学校声誉极佳。', '必背核心·高频词', '1126', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1127', 'CET6', 'request', '/rɪˈkwest/', 'n./v.', '请求；要求', 'Requests for tickets must be made in writing.', '购票需提交书面申请。', '必背核心·高频词', '1127', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1128', 'CET6', 'require', '/rɪˈkwaɪə(r)/', 'v.', '需要；要求', 'This course requires a great deal of reading.', '这门课需要大量阅读。', '四级阅读·校园类', '1128', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
