  ('cet6-1455', 'CET6', 'wallet', '/ˈwɒlɪt/', 'n.', '钱包；皮夹', 'Someone stole his wallet on the bus.', '有人在公交车上偷了他的钱包。', '必背核心·高频词', '1455', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
