  ('cet6-1458', 'CET6', 'warehouse', '/ˈweəhaʊs/', 'n.', '仓库；货栈', 'The goods are stored in a large warehouse.', '货物存放在一个大仓库里。', '必背核心·高频词', '1458', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
