  ('cet6-1461', 'CET6', 'wary', '/ˈweəri/', 'adj.', '谨慎的；警惕的', 'Be wary of offers that seem too good.', '对好得离谱的报价要保持警惕。', '六级阅读·理财类', '1461', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
