  ('cet6-1472', 'CET6', 'weight', '/weɪt/', 'n./v.', '重量；体重；重压', 'He has lost a lot of weight recently.', '他最近体重减轻了不少。', '必背核心·高频词', '1472', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1473', 'CET6', 'weird', '/wɪəd/', 'adj.', '奇怪的；古怪的', 'It was a weird and wonderful experience.', '那是一次奇特而美妙的经历。', '必背核心·高频词', '1473', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
