  ('cet6-1475', 'CET6', 'welfare', '/ˈwelfeə(r)/', 'n.', '福利；福祉；幸福', 'The welfare of children should come first.', '儿童的福祉应当放在首位。', '四级阅读·社会类', '1475', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
