  ('cet6-1486', 'CET6', 'wind', '/wɪnd/', 'n./v.', '风；缠绕；上发条', 'A cold wind blew from the north.', '寒风从北方吹来。', '必背核心·高频词', '1486', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
