INSERT INTO word (`id`, `level`, `word`, `phonetic`, `pos`, `meaning`, `example_en`, `example_zh`, `source`, `freq_rank`, `create_time`, `update_time`) VALUES
  ('cet6-1491', 'CET6', 'yawn', '/jɔːn/', 'v./n.', '打哈欠；乏味的事', 'He yawned and looked at his watch.', '他打了个哈欠，看了看表。', '必背核心·高频词', '1491', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1492', 'CET6', 'year', '/jɪə(r)/', 'n.', '年；年份；年纪', 'She has worked here for ten years.', '她在这里工作十年了。', '必背核心·高频词', '1492', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1493', 'CET6', 'yearn', '/jɜːn/', 'v.', '渴望；向往；思念', 'Many city dwellers yearn for a quieter life.', '许多城市居民向往更宁静的生活。', '六级写作·社会类', '1493', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1494', 'CET6', 'yell', '/jel/', 'v./n.', '叫喊；大喊', 'Do not yell at the children.', '别对孩子们大喊大叫。', '必背核心·高频词', '1494', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1495', 'CET6', 'yellow', '/ˈjeləʊ/', 'adj./n./v.', '黄色的；黄色；变黄', 'The leaves turned yellow in October.', '树叶在十月变黄。', '必背核心·高频词', '1495', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1496', 'CET6', 'yesterday', '/ˈjestədeɪ/', 'adv./n.', '昨天；往昔', 'I saw him yesterday afternoon.', '我昨天下午见过他。', '必背核心·高频词', '1496', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1497', 'CET6', 'yet', '/jet/', 'adv./conj.', '还；仍然；然而', 'The work is not finished yet.', '这项工作还没有完成。', '必背核心·高频词', '1497', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1498', 'CET6', 'yield', '/jiːld/', 'v./n.', '产生；屈服；产量', 'This method yields much better results than the old one.', '这种方法比旧方法产生好得多的结果。', '四级阅读·科研类', '1498', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1499', 'CET6', 'yoga', '/ˈjəʊɡə/', 'n.', '瑜伽', 'She does yoga for half an hour every morning.', '她每天早上练半小时瑜伽。', '必背核心·高频词', '1499', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1500', 'CET6', 'yolk', '/jəʊk/', 'n.', '蛋黄', 'Separate the yolk from the white.', '把蛋黄和蛋白分开。', '必背核心·高频词', '1500', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1501', 'CET6', 'young', '/jʌŋ/', 'adj./n.', '年轻的；幼小的；年轻人', 'The young need more opportunities.', '年轻人需要更多机会。', '必背核心·高频词', '1501', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1502', 'CET6', 'youth', '/juːθ/', 'n.', '青春；青年时期；年轻人', 'He spent his youth in the countryside.', '他在乡村度过了青年时代。', '必背核心·高频词', '1502', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1503', 'CET6', 'zeal', '/ziːl/', 'n.', '热情；热忱；干劲', 'She worked with remarkable zeal.', '她以非凡的热情投入工作。', '六级阅读·人物类', '1503', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1504', 'CET6', 'zebra', '/ˈzebrə/', 'n.', '斑马', 'We saw zebras at the safari park.', '我们在野生动物园看到了斑马。', '必背核心·高频词', '1504', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1505', 'CET6', 'zenith', '/ˈzenɪθ/', 'n.', '巅峰；最高点；天顶', 'His career reached its zenith in the 1990s.', '他的事业在二十世纪九十年代达到巅峰。', '六级阅读·人物类', '1505', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1506', 'CET6', 'zero', '/ˈzɪərəʊ/', 'n./num.', '零；零点；零度', 'The temperature fell to zero overnight.', '气温一夜之间降到零度。', '必背核心·高频词', '1506', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1507', 'CET6', 'zip', '/zɪp/', 'n./v.', '拉链；拉上拉链；快速移动', 'Your zip is undone.', '你的拉链开了。', '必背核心·高频词', '1507', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1508', 'CET6', 'zone', '/zəʊn/', 'n./v.', '地区；区域；划分', 'This area is a no-parking zone.', '这个区域禁止停车。', '必背核心·高频词', '1508', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1509', 'CET6', 'zoo', '/zuː/', 'n.', '动物园', 'The zoo is closed on Mondays.', '动物园每周一闭园。', '必背核心·高频词', '1509', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('cet6-1510', 'CET6', 'zoom', '/zuːm/', 'v./n.', '快速移动；变焦；嗡嗡声', 'House prices have zoomed up recently.', '最近房价飞涨。', '必背核心·高频词', '1510', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO translation_question (`id`, `level`, `type`, `difficulty`, `source`, `prompt`, `reference`, `tips`, `core_words`, `grammar_points`, `create_time`, `update_time`) VALUES
  ('tr-001', 'CET4', 'sentence', '1', '四级翻译·文化类', '剪纸是中国最受欢迎的传统民间艺术之一。', 'Paper cutting is one of the most popular traditional folk arts in China.', '注意最高级形式 the most popular，且 folk arts 必须用复数。', '[{"en":"paper cutting","zh":"剪纸"},{"en":"folk art","zh":"民间艺术"},{"en":"traditional","zh":"传统的"}]', '["“one of + the + 形容词最高级 + 复数名词”表示“最……之一”，中心名词必须用复数。","表示“在某一范围内”用介词 in：in China。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-002', 'CET4', 'sentence', '1', '四级翻译·社会类', '随着经济的发展，中国人的生活方式发生了巨大的变化。', 'With the development of the economy, great changes have taken place in the Chinese way of life.', '“发生变化”主语用 changes，谓语用 take place，注意主谓一致。', '[{"en":"with the development of","zh":"随着……的发展"},{"en":"take place","zh":"发生（不及物，无被动）"},{"en":"way of life","zh":"生活方式"}]', '["“随着……”用 with + 名词短语，而不是 as + 句子（as 后必须接主谓）。","take place 为不及物动词短语，没有被动语态，不能写成 are taken place。","\\"巨大的变化\\"可用 great / tremendous / dramatic changes。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-003', 'CET4', 'sentence', '1', '四级翻译·科技类', '如今，越来越多的年轻人喜欢在网上购物而不是去实体店。', 'Nowadays, more and more young people prefer shopping online to going to physical stores.', 'prefer 后若接动词一定是动名词（-ing），不要写成 prefer to shop。', '[{"en":"prefer A to B","zh":"比起 B 更喜欢 A"},{"en":"physical store","zh":"实体店"},{"en":"nowadays","zh":"如今，现在"}]', '["prefer doing A to doing B：to 是介词，前后都接名词或动名词，必须对称。","“越来越多的”用比较级叠加：more and more + 名词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-004', 'CET4', 'sentence', '2', '四级翻译·教育类', '许多家长认为，孩子应该从小就学会独立解决问题。', 'Many parents believe that children should learn to solve problems independently from an early age.', '“从小”状语通常放在句末：from an early age / since childhood。', '[{"en":"independently","zh":"独立地"},{"en":"solve problems","zh":"解决问题"},{"en":"from an early age","zh":"从小"}]', '["that 引导宾语从句，从句用陈述语序。","learn to do sth. 表示“学会做某事”，to 后接动词原形。","修饰动词 solve 用副词 independently，而非形容词 independent。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-005', 'CET4', 'sentence', '2', '四级翻译·环境类', '只有大家都行动起来，我们才能有效减少空气污染。', 'Only if everyone takes action can we effectively reduce air pollution.', '倒装只发生在主句，only if 引导的从句本身不倒装。', '[{"en":"take action","zh":"采取行动"},{"en":"only if","zh":"只有当……才"},{"en":"air pollution","zh":"空气污染"}]', '["Only + 状语（从句/介词短语）置于句首时，主句必须部分倒装：can we reduce...","注意区分 only if（只有……才）与 if only（要是……就好了，用于虚拟语气）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-006', 'CET4', 'sentence', '2', '四级翻译·经济类', '据报道，今年上半年该市的出口增长了百分之十五。', 'It is reported that the city’s exports grew by 15 percent in the first half of this year.', '“增长了”用 by，“增长到”用 to，四六级翻译高频考点。', '[{"en":"it is reported that","zh":"据报道"},{"en":"grow by","zh":"增长了（表示幅度）"},{"en":"the first half of","zh":"……的上半年"}]', '["It is + 过去分词 + that 从句：常见报道句型（It is said / believed / estimated that...）。","表示增长幅度用 by：grow by 15%；表示增长到某值用 to：grow to 15%。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-007', 'CET4', 'sentence', '2', '四级翻译·交通类', '中国拥有世界上最长的高速铁路网，总里程超过四万公里。', 'China has the longest high-speed railway network in the world, with a total length of more than 40,000 kilometers.', '“总里程”也可译为 total mileage；数字单位注意 kilometers。', '[{"en":"high-speed railway","zh":"高速铁路"},{"en":"total length","zh":"总里程，总长度"},{"en":"more than","zh":"超过"}]', '["with + 名词 + of + 数值，作补充说明的伴随状语。","最高级 longest 前必须加 the，比较范围为 in the world。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-008', 'CET4', 'sentence', '3', '四级翻译·文化类', '直到亲眼看到长城，我才真正理解了它的雄伟壮观。', 'It was not until I saw the Great Wall with my own eyes that I truly understood its magnificence.', '强调句去掉 It was 与 that 后句子仍成立，可用来自检。', '[{"en":"not until","zh":"直到……才"},{"en":"with one’s own eyes","zh":"亲眼"},{"en":"magnificence","zh":"雄伟，壮观"}]', '["It is/was not until + 时间状语 + that + 主句：not until 的强调句型，that 后不倒装。","若 Not until 直接置于句首，则主句要部分倒装：Not until I saw... did I understand..."]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-009', 'CET4', 'paragraph', '2', '四级翻译·2021年6月真题话题', '铁观音（Tieguanyin）是中国最著名的茶之一，原产于福建省安溪县。铁观音茶汤金黄，香气持久，滋味甘醇。长期饮用有助于提神醒脑、消食去腻。近年来，随着人们对健康的重视，铁观音越来越受到国内外消费者的喜爱。', 'Tieguanyin is one of the most famous teas in China, which originated in Anxi County, Fujian Province. The tea has a golden color, a lasting fragrance and a sweet, mellow taste. Drinking it over a long period of time helps refresh the mind and aid digestion. In recent years, as people have attached greater importance to health, Tieguanyin has become increasingly popular among consumers at home and abroad.', '段落翻译要先定主干再补修饰；地名顺序为“小地点 + 大地点”（Anxi County, Fujian Province）。', '[{"en":"originate in","zh":"起源于"},{"en":"fragrance","zh":"香气"},{"en":"mellow","zh":"醇厚的"},{"en":"aid digestion","zh":"助消化"},{"en":"attach importance to","zh":"重视"},{"en":"at home and abroad","zh":"国内外"}]', '["非限制性定语从句 which originated in... 补充说明主语，从句前加逗号。","“随着……”可用 as 引导时间状语从句（as people have attached...）。","“越来越……”用 increasingly + 形容词，或 more and more + 形容词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-010', 'CET4', 'paragraph', '2', '四级翻译·2022年6月真题话题', '筷子是中国人日常用餐的主要工具，已有三千多年的历史。中国人认为，筷子成双成对，象征着和谐与团圆。使用筷子时有一些禁忌需要注意，例如不能把筷子插在饭碗里，也不能用筷子敲打碗碟。如今，筷子不仅是一种餐具，更成为中华饮食文化的象征。', 'Chopsticks are the main eating utensils for Chinese people in their daily life, with a history of more than 3,000 years. Chinese people believe that chopsticks always come in pairs, which symbolizes harmony and reunion. There are some taboos to keep in mind when using chopsticks; for example, they should not be stuck upright in a bowl of rice, nor used to knock on bowls and plates. Today, chopsticks are not only a kind of tableware, but also a symbol of Chinese food culture.', '注意餐具用词：chopsticks / bowl / plate / tableware，避免混用 dish 与 plate。', '[{"en":"utensil","zh":"器具，用具"},{"en":"come in pairs","zh":"成双成对"},{"en":"symbolize","zh":"象征"},{"en":"taboo","zh":"禁忌"},{"en":"tableware","zh":"餐具"}]', '["“不仅……而且……”用 not only... but also...，连接两个并列成分。","“不能……也不能……”可用 nor 引起的倒装：should not be..., nor used to...","with a history of + 时间段：表示“有……的历史”。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-011', 'CET4', 'paragraph', '3', '四级翻译·2020年9月真题话题', '茅台（Maotai）是中国最著名的白酒之一，产于贵州省茅台镇。茅台酒以当地优质高粱和小麦为原料，采用独特的酿造工艺，历经多年发酵而成。其酒体醇厚，回味悠长。茅台不仅在国内享有盛誉，还远销世界各地，被视为中国白酒的代表。', 'Maotai is one of the most famous liquors in China, produced in Maotai Town, Guizhou Province. Made from high-quality local sorghum and wheat, it is brewed through a unique technique and fermented for many years. The liquor has a mellow body and a long aftertaste. Maotai enjoys a high reputation not only at home but also in many overseas markets, and is regarded as a representative of Chinese liquor.', '“白酒”规范译法为 liquor 或 Baijiu，不要直译成 white wine（白葡萄酒）。', '[{"en":"liquor","zh":"白酒，烈酒"},{"en":"sorghum","zh":"高粱"},{"en":"brew","zh":"酿造"},{"en":"ferment","zh":"发酵"},{"en":"aftertaste","zh":"回味"},{"en":"be regarded as","zh":"被视为"}]', '["过去分词短语作状语：produced in... / made from...，逻辑主语是句子主语 Maotai。","“以……为原料”用 be made from（看不出原材料）或 be made of（看得出原材料）。","“被视为”用 be regarded as / be considered as / be seen as。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-012', 'CET4', 'paragraph', '3', '四级翻译·2023年3月真题话题', '近年来，中国的乡村旅游发展迅速。越来越多的城市居民选择在周末或节假日到乡村去，体验田园生活、品尝农家菜、欣赏自然风光。乡村旅游不仅带动了当地经济的发展，增加了农民收入，也让更多人了解了传统农耕文化。', 'In recent years, rural tourism in China has developed rapidly. A growing number of urban residents choose to visit the countryside at weekends or during holidays to experience rural life, taste home-cooked farm dishes and enjoy natural scenery. Rural tourism has not only boosted the local economy and increased farmers’ income, but also enabled more people to learn about traditional farming culture.', '“农家菜”不要直译成 farmer food，用 home-cooked dishes 或 farmhouse dishes 更地道。', '[{"en":"rural tourism","zh":"乡村旅游"},{"en":"urban residents","zh":"城市居民"},{"en":"home-cooked dishes","zh":"农家菜"},{"en":"boost the economy","zh":"带动经济"},{"en":"enable sb. to do","zh":"使某人能够做"}]', '["not only... but also... 连接两个谓语时，注意时态与形式对称（has boosted... and increased...）。","“越来越多的”可替换为 a growing number of / an increasing number of + 复数名词。","目的状语用不定式：to experience..., taste... and enjoy...（并列不定式后两个 to 可省略）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-013', 'CET6', 'sentence', '1', '六级翻译·历史类', '丝绸之路不仅是古代重要的贸易通道，也是东西方文化交流的桥梁。', 'The Silk Road was not only an important trade route in ancient times, but also a bridge for cultural exchanges between the East and the West.', '“桥梁”比喻义用 a bridge for...，for 后接名词或动名词。', '[{"en":"the Silk Road","zh":"丝绸之路"},{"en":"trade route","zh":"贸易通道"},{"en":"cultural exchange","zh":"文化交流"}]', '["“不仅……而且……”用 not only... but also...，连接表语时结构需对称。","“东西方”固定表达 the East and the West，首字母大写。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-014', 'CET6', 'sentence', '2', '六级翻译·社会类', '鉴于人口老龄化日益严重，政府已采取一系列措施完善养老服务体系。', 'Given the increasingly serious aging of the population, the government has taken a series of measures to improve the elderly care service system.', '“养老”不要译成 old-age support，规范说法是 elderly care / eldercare。', '[{"en":"given (that)","zh":"鉴于，考虑到"},{"en":"aging of the population","zh":"人口老龄化"},{"en":"a series of","zh":"一系列"},{"en":"elderly care","zh":"养老，老年照护"}]', '["given 作介词表示“考虑到”，后接名词短语；作连词时写作 given that + 从句。","“采取措施做某事”用 take measures to do sth.，也可用 adopt measures。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-015', 'CET6', 'sentence', '2', '六级翻译·科技类', '人工智能的广泛应用，使得许多传统行业发生了深刻变革。', 'The wide application of artificial intelligence has brought about profound changes in many traditional industries.', '“深刻的”可用 profound / far-reaching / dramatic，六级写作加分。', '[{"en":"artificial intelligence (AI)","zh":"人工智能"},{"en":"bring about","zh":"引起，带来"},{"en":"profound changes","zh":"深刻的变革"}]', '["“带来变化”用 bring about / lead to / result in changes，注意主语是“应用”这一事实。","现在完成时强调已发生且影响持续：has brought about。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-016', 'CET6', 'sentence', '3', '六级翻译·教育类', '正是由于教育的普及，中国才得以在短短几十年内实现如此巨大的经济腾飞。', 'It is precisely due to the popularization of education that China has managed to achieve such a great economic take-off within just a few decades.', '强调句去掉 It is 与 that 后仍应为完整句子，这是检查要点。', '[{"en":"popularization","zh":"普及"},{"en":"due to","zh":"由于"},{"en":"manage to do","zh":"得以，设法做到"},{"en":"economic take-off","zh":"经济腾飞"}]', '["强调句型 It is/was + 被强调部分 + that + 其余部分；本句强调原因状语。","manage to do 强调“成功做到”，比 can do 更贴切。","such + a/an + 形容词 + 单数名词：such a great economic take-off。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-017', 'CET6', 'paragraph', '2', '六级翻译·2021年12月真题话题', '延安位于陕西省北部，是中国革命的圣地。抗日战争和解放战争时期，延安曾是中共中央所在地。这里至今保留着大量革命旧址，每年吸引数百万游客前来参观。如今，延安在发展红色旅游的同时，也大力推进生态建设，昔日的黄土高坡已披上绿装。', 'Located in the northern part of Shaanxi Province, Yan’an is a sacred place of the Chinese revolution. During the War of Resistance against Japanese Aggression and the Liberation War, Yan’an served as the seat of the Central Committee of the Communist Party of China. A large number of revolutionary sites are still preserved here, attracting millions of visitors every year. Today, while developing red tourism, Yan’an is also vigorously promoting ecological construction, and the once barren loess plateau has been clothed in green.', '“黄土高坡”标准译法为 the Loess Plateau；地名拼写 Shaanxi（陕西）注意与 Shanxi（山西）区分。', '[{"en":"sacred place","zh":"圣地"},{"en":"revolutionary site","zh":"革命旧址"},{"en":"red tourism","zh":"红色旅游"},{"en":"ecological construction","zh":"生态建设"},{"en":"loess plateau","zh":"黄土高坡"}]', '["过去分词作状语：Located in...，逻辑主语是主句主语 Yan’an。","现在分词作结果状语：..., attracting millions of visitors...","while + 现在分词表示“在做某事的同时”：while developing red tourism。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-018', 'CET6', 'paragraph', '2', '六级翻译·2022年9月真题话题', '太极拳（Tai Chi）是中国传统武术的一种，兼具健身与防身功能。它动作柔和缓慢，讲究以柔克刚，强调身心合一。练习太极拳不受场地和器材限制，也不分年龄性别，因此深受人们喜爱。如今，太极拳已传播到世界各地，成为中华文化的一张名片。', 'Tai Chi is a form of traditional Chinese martial art, serving both as physical exercise and as a means of self-defense. Its movements are gentle and slow; it emphasizes overcoming hardness with softness and the unity of body and mind. Practicing Tai Chi requires neither a special venue nor any equipment, and it suits people of all ages and genders, so it is deeply loved by the public. Today, Tai Chi has spread all over the world and has become a calling card of Chinese culture.', '“以柔克刚”是固定文化意象，六级常考，建议整句记忆。', '[{"en":"martial art","zh":"武术"},{"en":"self-defense","zh":"防身"},{"en":"overcome hardness with softness","zh":"以柔克刚"},{"en":"unity of body and mind","zh":"身心合一"},{"en":"calling card","zh":"名片，标志"}]', '["现在分词作伴随/补充说明：serving both as... and as...","neither... nor... 连接两个并列宾语，表示“既不……也不……”。","“深受喜爱”可用 be deeply loved by / enjoy great popularity among。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-019', 'CET6', 'paragraph', '3', '六级翻译·2020年12月真题话题', '北京故宫，旧称紫禁城，是明清两代的皇家宫殿，也是世界上现存规模最大、保存最为完整的木质结构古建筑群。故宫始建于1406年，历时十四年建成，共有宫殿七十多座，房屋九千余间。1987年，故宫被联合国教科文组织列入《世界遗产名录》。', 'The Palace Museum in Beijing, formerly known as the Forbidden City, was the imperial palace of the Ming and Qing dynasties. It is also the largest and best-preserved ancient wooden-structure building complex existing in the world. Its construction began in 1406 and took 14 years to complete. It consists of more than 70 palaces and over 9,000 rooms. In 1987, it was inscribed on the World Heritage List by UNESCO.', '专有名词要准确：the Palace Museum / the Forbidden City / UNESCO。', '[{"en":"the Forbidden City","zh":"紫禁城"},{"en":"imperial palace","zh":"皇家宫殿"},{"en":"wooden-structure complex","zh":"木质结构建筑群"},{"en":"be inscribed on","zh":"被列入（名录）"},{"en":"World Heritage List","zh":"《世界遗产名录》"}]', '["过去分词作定语：formerly known as... / best-preserved...","“现存规模最大的”用最高级 + 现在分词作后置定语：...complex existing in the world。","“历时……建成”用 sth. takes + 时间 + to complete。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-020', 'CET6', 'paragraph', '3', '六级翻译·2023年6月真题话题', '中国的高铁网络在过去十余年间迅速扩张，运营里程已居世界第一。高铁不仅大大缩短了城市之间的时空距离，也深刻改变了人们的出行方式与生活方式。与此同时，中国高铁凭借先进的技术、可靠的品质和合理的价格，已成为一张亮丽的“国家名片”，并加速走向世界。', 'Over the past decade or so, China’s high-speed rail network has expanded rapidly, and its operational mileage now ranks first in the world. High-speed rail has not only greatly shortened the time and space distance between cities, but also profoundly changed the way people travel and live. Meanwhile, thanks to its advanced technology, reliable quality and reasonable prices, China’s high-speed rail has become a bright “national calling card” and is accelerating its expansion into the global market.', '“高铁”正式译法为 high-speed rail（HSR），不要写成 fast train。', '[{"en":"operational mileage","zh":"运营里程"},{"en":"rank first","zh":"居第一位"},{"en":"time and space distance","zh":"时空距离"},{"en":"thanks to","zh":"凭借，由于"},{"en":"national calling card","zh":"国家名片"}]', '["“Over/During the past + 时间段”与现在完成时连用。","“位居第一”用 rank first / top the list / be the largest in the world。","“出行方式”用 the way people travel，way 后接定语从句时省略 that/in which。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-021', 'CET6', 'paragraph', '3', '六级翻译·2022年12月真题话题', '敦煌莫高窟位于甘肃省敦煌市，是世界上现存规模最大、内容最丰富的佛教艺术圣地。莫高窟始建于公元366年，现存洞窟735个，壁画约4.5万平方米，彩塑两千余身。莫高窟不仅是中西文化交流的结晶，也是研究中国古代政治、经济、文化和宗教的珍贵资料。', 'Located in Dunhuang City, Gansu Province, the Mogao Grottoes are the largest and richest Buddhist art site surviving in the world. First constructed in 366 AD, the site now preserves 735 caves, about 45,000 square meters of murals and more than 2,000 painted sculptures. The Mogao Grottoes are not only the fruit of cultural exchanges between China and the West, but also precious material for the study of politics, economy, culture and religion in ancient China.', '数字单位：45,000 square meters of murals；注意“公元366年”写作 366 AD。', '[{"en":"grottoes","zh":"石窟"},{"en":"Buddhist art","zh":"佛教艺术"},{"en":"mural","zh":"壁画"},{"en":"painted sculpture","zh":"彩塑"},{"en":"the fruit of","zh":"……的结晶"}]', '["多个过去分词短语叠加作状语/定语：Located in... / First constructed in...","“最丰富的”用 richest；并列最高级结构 the largest and richest...","“研究……的珍贵资料”用 precious material for the study of..."]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-022', 'CET6', 'paragraph', '3', '六级翻译·2021年6月真题话题', '海南岛是中国第二大岛，地处热带，气候温暖湿润，素有“天然大温室”之称。岛上植被茂盛，物产丰富，盛产椰子、芒果、橡胶等热带作物。近年来，海南大力推进自由贸易港建设，旅游业和现代服务业发展势头强劲，正逐步成为具有国际影响力的开放之地。', 'Hainan Island, China’s second largest island, lies in the tropics and enjoys a warm and humid climate, long known as a “natural greenhouse”. The island is lush with vegetation and rich in produce, abounding in tropical crops such as coconuts, mangoes and rubber. In recent years, Hainan has vigorously promoted the development of a free trade port; its tourism and modern service industries are growing strongly, and the island is gradually becoming an open land with international influence.', '“第二大岛”序数词前加 the：the second largest island，注意最高级前用 largest。', '[{"en":"in the tropics","zh":"地处热带"},{"en":"humid","zh":"湿润的"},{"en":"lush","zh":"茂盛的"},{"en":"abound in","zh":"盛产，富于"},{"en":"free trade port","zh":"自由贸易港"}]', '["同位语作补充说明：China’s second largest island 紧跟在主语之后。","“素有……之称”用 be long known as / be reputed as。","“盛产”用 abound in / be rich in，主语是地点。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-023', 'CET6', 'paragraph', '3', '六级翻译·2023年12月真题话题', '中国传统绘画，简称“国画”，是用毛笔、墨、颜料在宣纸或绢上作画的艺术。与西方绘画注重写实不同，国画更强调“神似”而非“形似”，追求意境的表达。画家常通过留白来营造想象空间，使观者体会到画外之意。经过数千年的发展，国画已成为东方艺术的代表。', 'Traditional Chinese painting, or guohua for short, is the art of painting on xuan paper or silk with a brush, ink and pigments. Unlike Western painting, which attaches great importance to realism, Chinese painting emphasizes “spiritual resemblance” rather than “formal resemblance” and pursues the expression of artistic conception. Painters often leave blank spaces to create room for imagination, allowing viewers to appreciate the meaning beyond the picture. After thousands of years of development, traditional Chinese painting has become a representative of Oriental art.', '“神似 / 形似”六级高频文化词，建议记 spiritual resemblance / formal resemblance。', '[{"en":"xuan paper","zh":"宣纸"},{"en":"pigment","zh":"颜料"},{"en":"realism","zh":"写实主义"},{"en":"artistic conception","zh":"意境"},{"en":"leave blank space","zh":"留白"}]', '["“与……不同”用 Unlike + 名词，或 Different from...","rather than 连接并列成分，表示“而不是”。","现在分词作结果状语：..., allowing viewers to appreciate..."]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-024', 'CET6', 'paragraph', '3', '六级翻译·2020年7月真题话题', '《红楼梦》是中国古典文学的巅峰之作，由曹雪芹创作于18世纪中叶。全书以贾、史、王、薛四大家族的兴衰为背景，以贾宝玉和林黛玉的爱情悲剧为主线，描绘了一幅封建社会的全景图。作品塑造了数百个栩栩如生的人物形象，被誉为中国封建社会的百科全书。', 'Dream of the Red Chamber, a masterpiece of classical Chinese literature, was written by Cao Xueqin in the mid-18th century. Set against the rise and fall of four prominent families — the Jia, the Shi, the Wang and the Xue — and centred on the tragic love between Jia Baoyu and Lin Daiyu, the novel presents a panoramic picture of feudal society. With hundreds of vividly portrayed characters, the work is hailed as an encyclopedia of Chinese feudal society.', '书名《红楼梦》通行译法为 Dream of the Red Chamber（也可用 The Story of the Stone）。', '[{"en":"masterpiece","zh":"杰作，巅峰之作"},{"en":"be set against","zh":"以……为背景"},{"en":"rise and fall","zh":"兴衰"},{"en":"panoramic","zh":"全景的"},{"en":"be hailed as","zh":"被誉为"}]', '["过去分词短语作状语：Set against... and centred on...，逻辑主语为 the novel。","介词 with 引导复合结构作原因/伴随状语：With hundreds of vividly portrayed characters...","“被誉为”用 be hailed as / be praised as / be honored as。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-025', 'CET4', 'paragraph', '2', '四级翻译真题·2019年6月（剪纸）', '剪纸是中国最古老、最流行的民间艺术之一，已有两千多年的历史。剪纸通常用于装饰门窗，表达人们对美好生活的向往。红色的剪纸在中国尤其常见，因为红色在中国文化中象征着吉祥和幸福。每逢春节或婚礼，人们都会贴上精美的剪纸，为节日增添喜庆的气氛。', 'Paper cutting is one of the oldest and most popular folk arts in China, with a history of more than two thousand years. It is usually used to decorate doors and windows and to express people’s longing for a better life. Red paper-cuts are especially common in China, because red symbolizes good luck and happiness in Chinese culture. During the Spring Festival or at weddings, people put up delicate paper-cuts to add a festive atmosphere to the occasion.', '文化类段落常考“象征/代表”，可用 symbolize / represent / stand for 三种表达轮换。', '[{"en":"paper cutting","zh":"剪纸"},{"en":"folk art","zh":"民间艺术"},{"en":"symbolize","zh":"象征"},{"en":"decorate","zh":"装饰"},{"en":"festive atmosphere","zh":"节日气氛"}]', '["“one of + the + 最高级 + 复数名词”结构，中心名词必须用复数：one of the oldest folk arts。","“with a history of + 时间段”作伴随状语，表示“有着……的历史”。","表达“被用来做……”用 be used to do，注意 to 后接动词原形。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-026', 'CET4', 'paragraph', '2', '四级翻译真题·2019年6月（灯笼）', '灯笼起源于两千多年前的西汉时期，最初用于照明。后来，灯笼逐渐成为节日装饰品，尤其在中国春节期间随处可见。传统灯笼多为红色，呈椭圆形，上面常写有“福”字或绘有吉祥图案。如今，灯笼不仅在中国流行，也受到了世界各地人们的喜爱。', 'Lanterns originated in the Western Han Dynasty more than two thousand years ago and were first used for lighting. Later, they gradually became festive decorations and can be seen everywhere during the Spring Festival in particular. Traditional lanterns are mostly red and oval in shape, often inscribed with the character “fu” (blessing) or painted with auspicious patterns. Today, lanterns are popular not only in China but also among people all over the world.', '朝代固定译法：西汉 the Western Han Dynasty；朝代名前加定冠词 the。', '[{"en":"lantern","zh":"灯笼"},{"en":"originate","zh":"起源于"},{"en":"auspicious","zh":"吉祥的"},{"en":"oval","zh":"椭圆形的"},{"en":"decoration","zh":"装饰品"}]', '["“起源于”用 originate in / date back to / date from，三者都不可用被动语态。","“不仅……而且……”用 not only … but also …，连接两个并列成分时结构要对称。","“受到……的喜爱”可用 be popular among / be loved by，注意 among 后接复数人群。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-027', 'CET4', 'paragraph', '3', '四级翻译真题·2019年6月（舞狮）', '舞狮是中国传统的民间表演艺术，通常在春节和其他喜庆场合演出。表演时需要两个人合作，一人舞头，一人舞尾。伴随着锣鼓的节奏，狮子做出各种灵巧的动作，如翻滚、跳跃和登高。人们相信舞狮能够驱邪避灾，为新的一年带来好运和平安。', 'The lion dance is a traditional Chinese folk performing art, usually staged during the Spring Festival and other festive occasions. The performance requires two people working together, one manipulating the head and the other the tail. To the rhythm of gongs and drums, the lion performs a variety of nimble movements, such as rolling, jumping and climbing. People believe that the lion dance can drive away evil spirits and bring good luck and peace for the coming year.', '“驱邪避灾”不要直译成 drive away ghosts，译为 drive away evil spirits 更地道。', '[{"en":"lion dance","zh":"舞狮"},{"en":"performing art","zh":"表演艺术"},{"en":"nimble","zh":"灵巧的"},{"en":"rhythm","zh":"节奏"},{"en":"drive away","zh":"驱赶"}]', '["“伴随着……的节奏”用 to the rhythm of，介词用 to 不用 with。","“such as + 并列动名词”举例，and 连接最后两项时前面用逗号。","“人们相信……”可用 People believe that 或 It is believed that 两种句式。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-028', 'CET4', 'paragraph', '2', '四级翻译真题·2023年3月（筷子）', '筷子是中国人最主要的进食工具，已有三千多年的历史。中国人使用筷子已有数千年，筷子的标准长度约为二十五厘米。使用筷子时，一根固定不动，另一根活动，通过两根的配合夹起食物。如今，筷子不仅是一种餐具，还被视为中国文化的象征，常被作为礼物赠送给外国朋友。', 'Chopsticks are the main eating utensils for the Chinese people, with a history of more than three thousand years. The Chinese have used chopsticks for thousands of years, and the standard length of chopsticks is about twenty-five centimetres. When using chopsticks, one stick remains still while the other moves, and food is picked up through the coordination of the two. Today, chopsticks are not merely tableware but are also regarded as a symbol of Chinese culture, and are often given as gifts to foreign friends.', '“筷子”恒用复数 chopsticks，谓语用 are；说“一双筷子”用 a pair of chopsticks。', '[{"en":"chopsticks","zh":"筷子"},{"en":"utensil","zh":"器具"},{"en":"coordination","zh":"配合"},{"en":"tableware","zh":"餐具"},{"en":"be regarded as","zh":"被视为"}]', '["“通过……的配合”用 through the coordination of，through 强调“经由”。","“不仅……还……”此处连接表语，用 not merely … but also …，比 not only 更书面。","“被视为”用 be regarded as / be seen as / be viewed as，as 后接名词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-029', 'CET4', 'paragraph', '2', '四级翻译真题·2013年12月（中国结）', '中国结是一种古老而独特的手工编织工艺品，出现于唐宋时期，明清时期开始流行。中国结由一根红绳编成，造型对称而优美。不同的造型代表不同的含义，如双钱结象征财富，盘长结象征长寿。如今，中国结常用于装饰居室和汽车，也是赠送亲友的佳品。', 'The Chinese knot is an ancient and distinctive handicraft, which first appeared in the Tang and Song dynasties and became popular in the Ming and Qing dynasties. A Chinese knot is woven from a single red cord, with a symmetrical and elegant shape. Different shapes carry different meanings: for example, the double-coin knot symbolizes wealth, while the pan-chang knot represents longevity. Today, Chinese knots are often used to decorate homes and cars, and also make excellent gifts for relatives and friends.', '朝代连写：唐宋 the Tang and Song dynasties，dynasties 用复数。', '[{"en":"Chinese knot","zh":"中国结"},{"en":"handicraft","zh":"手工艺品"},{"en":"symmetrical","zh":"对称的"},{"en":"longevity","zh":"长寿"},{"en":"weave","zh":"编织"}]', '["非限制性定语从句 which 指代前面整个名词短语，从句前加逗号。","“象征”可用 symbolize / represent / stand for，同一段内应换用避免重复。","“由……编成”用 be woven from（原材料不可见时用 from，可见时用 of）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-030', 'CET4', 'paragraph', '2', '四级翻译真题·2013年12月（中餐）', '中国饮食文化源远流长，中餐以其色、香、味俱全而闻名于世。中国地域辽阔，各地气候和物产差异很大，因而形成了八大菜系。总体而言，南方菜偏清淡、注重原味，北方菜偏咸、分量较大。如今，中餐馆遍布世界各地，深受各国人民的喜爱。', 'Chinese culinary culture has a long history, and Chinese cuisine is famous worldwide for its perfect combination of colour, aroma and taste. China has a vast territory, and its climate and local products vary greatly from region to region, which has given rise to eight major regional cuisines. Generally speaking, southern dishes are light and emphasize the original flavour, while northern dishes tend to be salty and are served in larger portions. Today, Chinese restaurants can be found all over the world and are warmly welcomed by people of all countries.', '“色香味俱全”标准译法：colour, aroma and taste，顺序固定，注意 aroma 拼写。', '[{"en":"cuisine","zh":"菜系；烹饪"},{"en":"aroma","zh":"香气"},{"en":"give rise to","zh":"形成；导致"},{"en":"territory","zh":"领土；地域"},{"en":"portion","zh":"分量；一份"}]', '["“因……而闻名”用 be famous for / be known for，介词用 for 不用 as。","“give rise to”表示“产生、导致”，主语是原因，to 是介词。","“总体而言”用 generally speaking / on the whole，放在句首作评注性状语。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-031', 'CET4', 'paragraph', '3', '四级翻译真题·2021年6月（中国茶）', '中国是茶的故乡，中国人饮茶的历史可以追溯到四千多年前。茶叶分为绿茶、红茶、乌龙茶和白茶等多个种类，其中龙井茶最为著名。喝茶不仅能解渴，还有助于提神醒脑、消除疲劳。在中国，以茶待客是传统礼仪，客人到来时，主人通常会奉上一杯热茶。', 'China is the hometown of tea, and the history of Chinese tea drinking can be traced back to more than four thousand years ago. Tea is divided into several categories, including green tea, black tea, oolong tea and white tea, of which Longjing tea is the most famous. Drinking tea not only quenches thirst but also helps to refresh the mind and relieve fatigue. In China, serving tea to guests is a traditional courtesy; when a guest arrives, the host usually offers a cup of hot tea.', '“红茶”英文是 black tea（不是 red tea）；“绿茶”green tea，这是常考的文化差异点。', '[{"en":"trace back to","zh":"追溯到"},{"en":"category","zh":"种类"},{"en":"quench","zh":"解（渴）"},{"en":"fatigue","zh":"疲劳"},{"en":"courtesy","zh":"礼节"}]', '["“追溯到”用 date back to / trace back to，两者都无被动，常用一般现在时。","“of which”引导非限制性定语从句，表示“其中……”，用于整体与部分关系。","“不仅……而且……”连接谓语动词时，not only 后接助动词或动词，结构须平行。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-032', 'CET4', 'paragraph', '3', '四级翻译真题·2022年6月（苏州园林）', '苏州园林是中国古典园林的代表，以其精致的布局和典雅的景致闻名。园林虽小，却巧妙地运用了山、水、花木和建筑，营造出“人在画中游”的意境。苏州园林多建于明清时期，最初是文人墨客的私家住宅。1997年，苏州的几座古典园林被联合国教科文组织列入世界遗产名录。', 'Suzhou gardens are representatives of classical Chinese gardens, known for their exquisite layout and elegant scenery. Though small in size, these gardens make ingenious use of rocks, water, plants and architecture to create the artistic conception of “strolling in a painting”. Most of the Suzhou gardens were built during the Ming and Qing dynasties and originally served as private residences for men of letters. In 1997, several classical gardens in Suzhou were inscribed on the World Heritage List by UNESCO.', '“联合国教科文组织”固定缩写 UNESCO，前面不加冠词，读作 U-N-E-S-C-O。', '[{"en":"exquisite","zh":"精致的"},{"en":"layout","zh":"布局"},{"en":"artistic conception","zh":"意境"},{"en":"residence","zh":"住宅"},{"en":"inscribe","zh":"列入（名录）"}]', '["“以……闻名”用 be known for，后接原因；若接身份则用 be known as。","“though + 形容词”可构成省略让步状语：Though small in size, …","“被列入……名录”用被动 be inscribed on / be included in the … list。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-033', 'CET4', 'paragraph', '2', '四级翻译真题·2022年12月（中国高铁）', '中国拥有世界上最大的高速铁路网络，总里程超过四万公里。高铁不仅速度快，而且安全舒适、准点率高，已经成为许多人出行的首选。乘坐高铁，人们可以在几个小时内穿梭于城市之间，极大地节省了旅行时间。高铁的快速发展不仅改变了人们的出行方式，也促进了沿线城市的经济发展。', 'China has the largest high-speed railway network in the world, with a total length of more than forty thousand kilometres. High-speed trains are not only fast but also safe, comfortable and highly punctual, and have become the first choice for many travellers. By taking high-speed trains, people can travel between cities within a few hours, which greatly saves travelling time. The rapid development of high-speed railways has not only changed the way people travel, but also promoted the economic growth of cities along the lines.', '“高铁”标准译法 high-speed railway（英式）或 high-speed rail；列车可用 high-speed train。', '[{"en":"high-speed railway","zh":"高速铁路"},{"en":"network","zh":"网络"},{"en":"punctual","zh":"准时的"},{"en":"promote","zh":"促进"},{"en":"save","zh":"节省"}]', '["“方式/方法”后接定语从句可用 the way (that) people travel，that 可省略。","“不仅……而且……”在此连接两个谓语，注意时态一致（都用现在完成时）。","“沿线”用 along the lines / along the route，along 表示沿着。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-034', 'CET4', 'paragraph', '2', '四级翻译真题·2023年6月（共享单车）', '共享单车近年来在中国城市迅速普及，为解决“最后一公里”的出行问题提供了便利。用户只需用手机扫描车上的二维码，就可以随时取车和还车。共享单车价格低廉，还能减少交通拥堵和尾气排放。然而，乱停乱放和车辆损坏等问题也随之出现，需要政府和企业共同解决。', 'Bike-sharing has spread rapidly in Chinese cities in recent years, offering a convenient solution to the “last kilometre” of a journey. Users only need to scan the QR code on the bike with a smartphone, and they can pick up and return it at any time. Bike-sharing is inexpensive and also helps to reduce traffic congestion and exhaust emissions. However, problems such as random parking and damaged bikes have emerged, which require joint efforts from both the government and enterprises.', '“二维码”译 QR code（Q-R 大写）；“最后一公里”用引号保留 the “last kilometre”。', '[{"en":"bike-sharing","zh":"共享单车"},{"en":"scan","zh":"扫描"},{"en":"congestion","zh":"拥堵"},{"en":"emission","zh":"排放"},{"en":"random","zh":"随意的"}]', '["“近年来……迅速普及”用现在完成时 has spread rapidly in recent years。","“……等问题”用 problems such as …，such as 后接名词或动名词。","“需要……共同解决”用 require joint efforts from，from 后接各方。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-035', 'CET4', 'paragraph', '2', '四级翻译真题·2018年12月（移动支付）', '移动支付在中国已经十分普及，人们出门几乎不用带现金。无论是在超市购物、在餐厅用餐，还是乘坐公共交通，只需用手机扫一扫就能完成付款。移动支付不仅方便快捷，还降低了现金丢失和被盗的风险。与此同时，也有人担心个人信息的安全问题。', 'Mobile payment has become very common in China, and people hardly need to carry cash when going out. Whether shopping in a supermarket, dining in a restaurant, or taking public transport, people can finish paying simply by scanning with a mobile phone. Mobile payment is not only fast and convenient, but also reduces the risk of cash being lost or stolen. Meanwhile, some people are also worried about the security of their personal information.', '“公共交通”public transport（英式）/ public transportation（美式），不可加 s。', '[{"en":"mobile payment","zh":"移动支付"},{"en":"cash","zh":"现金"},{"en":"convenient","zh":"方便的"},{"en":"risk","zh":"风险"},{"en":"security","zh":"安全"}]', '["“无论……还是……”用 whether … or …，可后接并列动名词或并列从句。","“只需……”用 simply by + 动名词，by 表示方法手段。","“担心”用 be worried about / be concerned about，about 是介词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-036', 'CET4', 'paragraph', '3', '四级翻译真题·2015年6月（快递业）', '近年来，中国快递业发展迅猛，年业务量已位居世界第一。电子商务的兴起是快递业快速增长的主要原因，越来越多的消费者选择在网上购物。为了提升效率，快递公司不断增加人力和车辆投入，并开始使用无人机和智能快递柜。快递业的发展不仅创造了大量就业机会，也给人们的日常生活带来了极大便利。', 'In recent years, China’s express delivery industry has developed rapidly, and its annual business volume now ranks first in the world. The rise of e-commerce is the main reason for the fast growth of the express industry, as more and more consumers choose to shop online. To improve efficiency, delivery companies have been increasing their investment in manpower and vehicles, and have begun to use drones and smart parcel lockers. The development of the express industry has not only created a large number of jobs, but also brought great convenience to people’s daily lives.', '“快递”常用 express delivery / courier service；“快递员”courier 或 delivery man。', '[{"en":"express delivery","zh":"快递"},{"en":"volume","zh":"量；业务量"},{"en":"e-commerce","zh":"电子商务"},{"en":"efficiency","zh":"效率"},{"en":"drone","zh":"无人机"}]', '["“位居第一”用 rank first / rank number one，rank 后直接接序数词。","原因状语可用 as 引导从句，也可换用 because of + 名词短语。","“越来越多……”用 more and more + 名词，或 an increasing number of + 复数名词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-037', 'CET4', 'paragraph', '3', '四级翻译真题·2023年6月（新能源汽车）', '为应对气候变化和减少空气污染，中国政府大力推广新能源汽车。过去几年，新能源汽车的产销量持续增长，充电设施也日益完善。与传统汽车相比，新能源汽车不仅能降低油耗，还能减少温室气体排放。专家预测，未来新能源汽车将逐步取代传统燃油汽车，成为市场的主流。', 'In response to climate change and in order to reduce air pollution, the Chinese government has been vigorously promoting new energy vehicles. Over the past few years, the production and sales of new energy vehicles have kept growing, and charging facilities have also been steadily improved. Compared with conventional cars, new energy vehicles can not only cut fuel consumption but also reduce greenhouse gas emissions. Experts predict that new energy vehicles will gradually replace traditional fuel-powered cars and become the mainstream of the market in the future.', '“温室气体”greenhouse gas；“燃油汽车”fuel-powered car / petrol car，注意 powered 的拼写。', '[{"en":"new energy vehicle","zh":"新能源汽车"},{"en":"in response to","zh":"应对；响应"},{"en":"emission","zh":"排放"},{"en":"fuel consumption","zh":"油耗"},{"en":"replace","zh":"取代"}]', '["“为应对……”用 In response to + 名词，或 To cope with + 名词，两者都作目的状语。","“与……相比”用 Compared with + 名词，compare 必须用过去分词表被动。","“逐步取代”用 gradually replace，副词位置在动词前。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-038', 'CET4', 'paragraph', '2', '四级翻译真题·2016年6月（深圳）', '深圳位于中国南部，原本是一个小渔村。1980年，深圳成为中国首批经济特区之一。此后，深圳以惊人的速度发展，短短几十年间就崛起为一座现代化大都市。如今，深圳被誉为中国的“硅谷”，聚集了大量高科技企业和创新人才，是中国最具活力的城市之一。', 'Located in southern China, Shenzhen was originally a small fishing village. In 1980, it became one of China’s first special economic zones. Since then, Shenzhen has developed at an astonishing speed and has risen to become a modern metropolis within just a few decades. Today, Shenzhen is honoured as China’s “Silicon Valley”, home to a large number of high-tech companies and innovative talents, and is one of the most dynamic cities in China.', '“硅谷”固定译 Silicon Valley，两个词首字母都大写；加引号表示特殊称谓。', '[{"en":"special economic zone","zh":"经济特区"},{"en":"astonishing","zh":"惊人的"},{"en":"metropolis","zh":"大都市"},{"en":"innovative","zh":"创新的"},{"en":"dynamic","zh":"有活力的"}]', '["“位于……”用 Located in + 地点，过去分词短语作状语，与主语构成被动关系。","“以……的速度”用 at a(n) … speed，介词用 at。","“被誉为”用 be honoured as / be known as，as 后接称号。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-039', 'CET4', 'sentence', '1', '四级翻译·基础句型（被动语态）', '这座桥是三年前建成的，现在每天有上万辆汽车通过。', 'The bridge was built three years ago, and now tens of thousands of cars pass over it every day.', '“成千上万”thousands of；“数以百万计”millions of，概数都要加 s + of。', '[{"en":"bridge","zh":"桥"},{"en":"tens of thousands of","zh":"上万；数以万计"},{"en":"pass over","zh":"经过"}]', '["汉语无主语句常译为英语被动语态：桥是建成的 → was built。","“三年前”用 three years ago，谓语动词用一般过去时。","“上万辆”用 tens of thousands of，注意 thousand 加 s 并接 of。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-040', 'CET4', 'sentence', '1', '四级翻译·基础句型（定语从句）', '昨天来参观的那位教授，就是写这本书的人。', 'The professor who came to visit yesterday is the very person who wrote this book.', '定语从句关系词选择：先行词是人用 who/whom，是物用 which/that。', '[{"en":"professor","zh":"教授"},{"en":"the very","zh":"正是；恰恰是"},{"en":"write","zh":"写"}]', '["两个定语从句分别修饰 professor 和 person，先行词是人，关系词用 who。","“就是……的人”用 the very person，very 在此表示强调“正是”。","“昨天来参观”用一般过去时 came to visit，作定语修饰 professor。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-041', 'CET4', 'sentence', '2', '四级翻译·基础句型（比较级）', '这座城市的公共交通比十年前便利得多，但房价也高了不少。', 'Public transport in this city is much more convenient than it was ten years ago, but housing prices are also considerably higher.', '比较级常用修饰语：much, far, even, still, a lot, a great deal；不可用 very 修饰比较级。', '[{"en":"public transport","zh":"公共交通"},{"en":"convenient","zh":"便利的"},{"en":"housing prices","zh":"房价"},{"en":"considerably","zh":"相当地；大大地"}]', '["比较级前可用 much / far / considerably / a lot 修饰，表示程度“……得多”。","比较对象要对称：than it was ten years ago 中 it 指代 public transport。","“高了不少”也用 much higher，避免重复使用 a lot。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-042', 'CET4', 'sentence', '2', '四级翻译·基础句型（非谓语动词）', '为了提高学生的口语能力，学校决定每周开设一次英语角。', 'To improve students’ speaking ability, the school has decided to set up an English corner once a week.', '常见只接不定式作宾语的动词：decide, hope, plan, refuse, promise, agree, offer。', '[{"en":"improve","zh":"提高"},{"en":"speaking ability","zh":"口语能力"},{"en":"set up","zh":"开设；建立"},{"en":"English corner","zh":"英语角"}]', '["目的状语可用不定式 To improve 放句首，逻辑主语须与主句主语一致。","“决定做某事”用 decide to do，不可说 decide doing。","“每周一次”用 once a week，表示频率。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-043', 'CET4', 'paragraph', '2', '四级翻译真题·2020年12月（春节团圆饭）', '春节是中国最重要的传统节日，团圆饭则是春节期间最重要的活动。除夕之夜，全家人无论身在何处，都会尽力赶回家中，围坐在一起吃一顿丰盛的年夜饭。餐桌上通常有鱼，因为“鱼”与“余”谐音，寓意年年有余。饭后，长辈会给晚辈发红包，祝福他们在新的一年健康平安。', 'The Spring Festival is the most important traditional festival in China, and the family reunion dinner is the most important event during the festival. On New Year’s Eve, all family members, no matter where they are, try their best to hurry home and sit together for a sumptuous reunion dinner. Fish is usually served at the table, because the Chinese character for “fish” sounds the same as the character for “surplus”, symbolizing abundance year after year. After the meal, elders give red envelopes to younger generations to wish them health and safety in the coming year.', '“年夜饭”与“团圆饭”都可译 family reunion dinner / New Year’s Eve dinner；红包也可说 red packet。', '[{"en":"reunion dinner","zh":"团圆饭"},{"en":"New Year’s Eve","zh":"除夕"},{"en":"sumptuous","zh":"丰盛的"},{"en":"surplus","zh":"剩余；余"},{"en":"red envelope","zh":"红包"}]', '["“无论在哪里”用 no matter where，引导让步状语从句，也可换用 wherever。","“因为……谐音”用 because … sounds the same as …，注意主从句时态一致。","“寓意/象征”可用 symbolizing（现在分词作结果状语）或 which symbolizes。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-044', 'CET4', 'paragraph', '2', '四级翻译真题·长城', '长城是中国古代最伟大的防御工程，始建于两千多年前的春秋战国时期。秦始皇统一中国后，将各段城墙连接起来，形成了万里长城。长城全长约两万一千公里，横跨中国北方的山川和沙漠。1987年，长城被列入世界文化遗产名录，每年吸引着数以千万计的中外游客。', 'The Great Wall is the greatest defensive project in ancient China, first built more than two thousand years ago during the Spring and Autumn and Warring States periods. After Emperor Qin Shi Huang unified China, he had the separate sections of wall joined together, forming the Great Wall of ten thousand li. The Great Wall stretches about twenty-one thousand kilometres across the mountains and deserts of northern China. In 1987, it was inscribed on the World Cultural Heritage List, and it attracts tens of millions of visitors from home and abroad every year.', '“春秋战国”the Spring and Autumn and Warring States periods；“秦始皇”Emperor Qin Shi Huang。', '[{"en":"defensive project","zh":"防御工程"},{"en":"unify","zh":"统一"},{"en":"stretch","zh":"延伸"},{"en":"heritage","zh":"遗产"},{"en":"tens of millions of","zh":"数以千万计"}]', '["“始建于……”用 first built + 时间，过去分词作后置定语。","“让人把……连接”用 have sth. done 结构：had the sections joined。","“横跨”用 stretch across / run across，主语是长城，用一般现在时。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-045', 'CET4', 'paragraph', '3', '四级翻译真题·故宫', '故宫位于北京市中心，是明清两代的皇宫，已有六百多年的历史。故宫占地约七十二万平方米，有大小宫殿七十多座、房屋九千余间，是世界上现存规模最大、保存最完整的木质结构古建筑群。1925年，故宫被改为博物院，向公众开放。今天，故宫博物院收藏着一百八十多万件珍贵文物。', 'Located in the centre of Beijing, the Forbidden City was the imperial palace of the Ming and Qing dynasties and has a history of more than six hundred years. Covering an area of about 720,000 square metres, it comprises more than seventy palaces of various sizes and over nine thousand rooms, making it the largest and best-preserved ancient wooden structure complex in the world. In 1925, the Forbidden City was converted into a museum and opened to the public. Today, the Palace Museum houses a collection of more than 1.8 million precious cultural relics.', '“故宫”两种译法：the Forbidden City（宫殿建筑）/ the Palace Museum（博物院），注意区分。', '[{"en":"imperial palace","zh":"皇宫"},{"en":"cover an area of","zh":"占地面积"},{"en":"best-preserved","zh":"保存最完好的"},{"en":"complex","zh":"建筑群"},{"en":"cultural relic","zh":"文物"}]', '["“位于……”用 Located in，过去分词短语作地点状语。","“使……成为”用 making it the largest …，现在分词作结果状语。","“被改为”用 be converted into / be turned into，into 表示转变的结果。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-046', 'CET4', 'paragraph', '2', '四级翻译真题·2019年12月（中国姓氏）', '中国人的姓氏历史悠久，最早可以追溯到母系氏族社会。中国人的姓氏有一万多个，其中最常用的只有一百多个，“张”“王”“李”“赵”是最常见的几个姓氏。在中国，子女通常随父姓，子女的名字往往寄托着父母的期望。了解一个人的姓氏，有助于了解其家族的历史和文化。', 'Chinese surnames have a long history and can be traced back to matriarchal clan society. There are more than ten thousand Chinese surnames, of which only a little over one hundred are in common use, and Zhang, Wang, Li and Zhao are among the most common. In China, children usually take their father’s surname, and their given names often embody their parents’ expectations. Knowing a person’s surname helps to shed light on the history and culture of his or her family.', '“姓氏”surname / family name；“名”given name / first name，两者要分清。', '[{"en":"surname","zh":"姓氏"},{"en":"matriarchal","zh":"母系的"},{"en":"in common use","zh":"常用的"},{"en":"embody","zh":"体现；寄托"},{"en":"shed light on","zh":"使……更易理解"}]', '["“其中……”用 of which 引导非限制性定语从句，也可用 among which。","“最常见的几个”用 among the most common，among 表示“在……之中”。","动名词短语 Knowing a person’s surname 作主语，谓语用单数 helps。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-047', 'CET4', 'paragraph', '3', '四级翻译真题·2019年12月（中国家庭观念）', '家庭在中国人的生活中占据着极其重要的地位。传统上，几代人同住一个屋檐下是司空见惯的，祖父母帮忙照看孙辈，子女则负责赡养老人。随着城市化的推进和生活节奏的加快，越来越多的年轻人选择与父母分开居住。尽管如此，尊老爱幼仍然是中华民族的传统美德，家庭成员之间的联系依然十分紧密。', 'Family occupies an extremely important position in the lives of the Chinese people. Traditionally, it was common for several generations to live under the same roof: grandparents helped look after their grandchildren, while their children took responsibility for supporting the elderly. With the advance of urbanization and the quickening pace of life, a growing number of young people choose to live apart from their parents. Even so, respecting the old and caring for the young remains a traditional virtue of the Chinese nation, and the bonds between family members remain very close.', '“尊老爱幼”固定译 respect the old and care for the young，the + 形容词表一类人。', '[{"en":"generation","zh":"代；一代人"},{"en":"urbanization","zh":"城市化"},{"en":"support the elderly","zh":"赡养老人"},{"en":"virtue","zh":"美德"},{"en":"bond","zh":"纽带；联系"}]', '["“随着……的推进”用 With the advance of，with 复合结构作伴随状语。","“越来越多的”用 a growing number of 或 an increasing number of，后接复数名词。","“尽管如此”用 Even so / Nevertheless，作连接性状语，注意句首大写。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-048', 'CET4', 'paragraph', '3', '四级翻译真题·2017年6月（长江）', '长江是亚洲最长的河流，全长约六千三百公里，在中国被称为“母亲河”。长江发源于青藏高原，流经十一个省、自治区和直辖市，最后注入东海。长江流域是中国重要的农业区和工业基地，养育了沿岸数以亿计的人口。近年来，中国政府加大了对长江生态环境的保护力度。', 'The Yangtze River is the longest river in Asia, with a total length of about 6,300 kilometres, and is known as the “mother river” of China. It originates on the Qinghai-Tibet Plateau, flows through eleven provinces, autonomous regions and municipalities, and finally empties into the East China Sea. The Yangtze River basin is an important agricultural region and industrial base in China, sustaining hundreds of millions of people along its banks. In recent years, the Chinese government has stepped up its efforts to protect the ecological environment of the Yangtze River.', '“青藏高原”the Qinghai-Tibet Plateau；“东海”the East China Sea，专有名词前加 the。', '[{"en":"originate","zh":"发源"},{"en":"plateau","zh":"高原"},{"en":"empty into","zh":"注入"},{"en":"basin","zh":"流域"},{"en":"step up","zh":"加大；加强"}]', '["“发源于”用 originate on/in，无被动语态，常用于一般现在时。","“注入”可用 empty into / flow into，主语是河流，into 后接海洋或湖泊。","“加大……力度”用 step up efforts to do，也可用 intensify / strengthen。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-049', 'CET4', 'sentence', '3', '四级翻译·难点句型（强调句）', '正是因为多年来坚持不懈的努力，他才取得了今天的成就。', 'It is precisely because of his persistent efforts over the years that he has achieved what he has today.', '强调句去掉 It is 与 that 后句子仍完整，这是判断强调句的依据。', '[{"en":"precisely","zh":"恰恰；正是"},{"en":"persistent","zh":"坚持不懈的"},{"en":"because of","zh":"因为"},{"en":"achieve","zh":"取得"}]', '["强调句型 It is/was + 被强调部分 + that + 其余部分，此处强调原因状语。","because of 后接名词短语 efforts，若接句子则用 because。","“取得了今天的成就”用 has achieved what he has today，what 引导宾语从句。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-050', 'CET4', 'sentence', '3', '四级翻译·难点句型（倒装）', '他不仅精通英语，而且对法国文学也有很深的了解。', 'Not only does he have a good command of English, but he also has a deep understanding of French literature.', '常见引起部分倒装的词：not only, never, seldom, hardly, no sooner, under no circumstances。', '[{"en":"have a good command of","zh":"精通"},{"en":"literature","zh":"文学"},{"en":"understanding","zh":"了解"}]', '["Not only 置于句首时，其所在分句须部分倒装：Not only does he have …","but also 后的分句不倒装，also 可省略或移至句末。","“精通”用 have a good command of / be proficient in，of/in 为介词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-051', 'CET4', 'sentence', '3', '四级翻译·难点句型（虚拟语气）', '如果当时听了老师的建议，他就不会犯这么严重的错误了。', 'If he had followed his teacher’s advice at that time, he would not have made such a serious mistake.', '虚拟语气三种时态：现在 did/would do；过去 had done/would have done；将来 did/would do。', '[{"en":"follow one’s advice","zh":"听从某人的建议"},{"en":"at that time","zh":"当时"},{"en":"serious","zh":"严重的"}]', '["与过去事实相反的虚拟条件句：从句 had done，主句 would have done。","“听从建议”用 follow/take one’s advice，advice 是不可数名词，不加 s。","“犯错误”用 make a mistake，不与 do 搭配。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-052', 'CET4', 'sentence', '2', '四级翻译·难点句型（形式主语）', '年轻人掌握一门外语是很有必要的，因为这不仅有助于就业，还能开阔视野。', 'It is very necessary for young people to master a foreign language, because this not only helps them find jobs but also broadens their horizons.', 'It is + adj. + for sb. 强调事情性质；It is + adj. + of sb. 强调人的品质（如 kind, wise）。', '[{"en":"necessary","zh":"必要的"},{"en":"master","zh":"掌握"},{"en":"broaden one’s horizons","zh":"开阔视野"}]', '["形式主语结构 It is + adj. + for sb. to do sth.，真正主语是不定式。","“有助于”用 help (to) do，help 后的 to 可省略。","“开阔视野”用 broaden/expand one’s horizons，horizons 常用复数。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-053', 'CET6', 'paragraph', '3', '六级翻译真题·丝绸之路', '丝绸之路是古代连接中国与西方的重要贸易通道，开通于两千多年前的汉代。这条路东起长安，西至地中海沿岸，全长七千多公里。通过丝绸之路，中国的丝绸、瓷器和造纸术传入西方，而葡萄、核桃等作物以及佛教文化也传入中国。丝绸之路不仅是商贸之路，更是东西方文化交流的桥梁。2014年，丝绸之路被列入世界遗产名录。', 'The Silk Road was an important trade route linking China with the West in ancient times, opened up more than two thousand years ago during the Han Dynasty. It stretched over seven thousand kilometres, starting from Chang’an in the east and reaching the Mediterranean coast in the west. Along the Silk Road, Chinese silk, porcelain and papermaking technology were introduced to the West, while crops such as grapes and walnuts, as well as Buddhist culture, were brought into China. The Silk Road was not merely a trade route but, more importantly, a bridge for cultural exchange between East and West. In 2014, it was inscribed on the World Heritage List.', '“一带一路”标准译法 the Belt and Road Initiative（缩写 BRI），首字母大写。', '[{"en":"the Silk Road","zh":"丝绸之路"},{"en":"trade route","zh":"贸易通道"},{"en":"porcelain","zh":"瓷器"},{"en":"papermaking","zh":"造纸术"},{"en":"cultural exchange","zh":"文化交流"}]', '["“东起……西至……”用 starting from … and reaching …，现在分词作伴随状语。","“传入”用 be introduced to / be brought into，注意被动语态与介词搭配。","“不仅是……更是……”用 not merely … but more importantly …，表递进。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-054', 'CET6', 'paragraph', '3', '六级翻译真题·一带一路', '2013年，中国提出了共建“一带一路”的倡议，旨在促进沿线国家的基础设施建设与经贸合作。该倡议继承了古代丝绸之路的精神，强调互利共赢、共同发展。十多年来，已有150多个国家与中国签署了合作文件，一批铁路、港口和工业园区相继建成。“一带一路”为参与国创造了大量就业机会，也推动了全球经济的增长。', 'In 2013, China proposed the Belt and Road Initiative, which aims to promote infrastructure development and economic and trade cooperation among countries along the routes. Inheriting the spirit of the ancient Silk Road, the initiative emphasizes mutual benefit and common development. Over the past decade and more, more than 150 countries have signed cooperation documents with China, and a number of railways, ports and industrial parks have been built one after another. The Belt and Road has created a large number of jobs for participating countries and has also driven global economic growth.', '“互利共赢”mutual benefit and win-win outcomes；也可用 win-win cooperation。', '[{"en":"the Belt and Road Initiative","zh":"一带一路倡议"},{"en":"infrastructure","zh":"基础设施"},{"en":"mutual benefit","zh":"互利"},{"en":"cooperation document","zh":"合作文件"},{"en":"one after another","zh":"相继"}]', '["“旨在……”用 which aims to do，非限制性定语从句补充说明。","“继承了……”用 Inheriting …，现在分词作原因状语，逻辑主语是 the initiative。","“十多年来”用 Over the past decade and more，句子常用现在完成时。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-055', 'CET6', 'paragraph', '3', '六级翻译真题·中国城市化', '改革开放以来，中国经历了世界上规模最大、速度最快的城市化进程。城市人口比例已从1978年的不足18%上升到今天的66%以上。城市化推动了经济增长，提高了居民收入，也带动了教育、医疗等公共服务的发展。与此同时，交通拥堵、住房紧张和环境污染等“城市病”也日益突出。如何在发展与宜居之间取得平衡，是中国城市面临的重要课题。', 'Since the launch of reform and opening up, China has undergone the largest and fastest urbanization process in the world. The proportion of the urban population has risen from less than 18 per cent in 1978 to over 66 per cent today. Urbanization has driven economic growth, raised residents’ incomes, and spurred the development of public services such as education and health care. At the same time, “urban diseases” such as traffic congestion, housing shortages and environmental pollution have become increasingly prominent. How to strike a balance between development and livability is an important issue facing Chinese cities.', '“改革开放”固定译 reform and opening up；“取得平衡”strike a balance between A and B。', '[{"en":"urbanization","zh":"城市化"},{"en":"proportion","zh":"比例"},{"en":"spur","zh":"带动；促进"},{"en":"prominent","zh":"突出的"},{"en":"livability","zh":"宜居性"}]', '["“从……上升到……”用 rise from A to B，from 与 to 后成分须对称。","“与此同时”用 At the same time / Meanwhile，作连接性状语。","“如何取得平衡”用 How to strike a balance，疑问词 + 不定式作主语。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-056', 'CET6', 'paragraph', '3', '六级翻译真题·中国航天', '中国航天事业起步于1956年，经过几代人的不懈努力，已取得举世瞩目的成就。2003年，中国成为世界上第三个独立将人送入太空的国家。近年来，中国先后完成了月球采样返回、空间站建设和火星探测等重大任务。2020年，北斗三号全球卫星导航系统正式开通，为全球用户提供高精度定位服务。中国始终坚持和平利用太空的原则。', 'China’s space programme started in 1956 and, thanks to the unremitting efforts of several generations, has achieved remarkable accomplishments that have attracted worldwide attention. In 2003, China became the third country in the world to send humans into space independently. In recent years, China has successively accomplished major missions such as lunar sample return, the construction of a space station and Mars exploration. In 2020, the BeiDou-3 global satellite navigation system was officially commissioned, providing high-precision positioning services for users worldwide. China has always adhered to the principle of the peaceful use of space.', '“北斗”官方译 BeiDou（不是 Big Dipper）；“空间站”space station。', '[{"en":"space programme","zh":"航天事业"},{"en":"unremitting","zh":"不懈的"},{"en":"sample return","zh":"采样返回"},{"en":"navigation system","zh":"导航系统"},{"en":"adhere to","zh":"坚持"}]', '["“第几个做……的国家”用 the + 序数词 + country to do，不定式作后置定语。","“先后完成”用 has successively accomplished，现在完成时强调成果积累。","“坚持……原则”用 adhere to / stick to the principle of，to 是介词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-057', 'CET6', 'paragraph', '3', '六级翻译真题·数字经济', '近年来，中国数字经济规模持续扩大，已成为推动经济增长的重要引擎。大数据、云计算、人工智能等新一代信息技术被广泛应用于制造、医疗、金融和物流等领域。数字经济不仅催生了电子商务、在线教育等新业态，还大幅提升了传统产业的生产效率。专家指出，随着5G网络的普及，数字经济将在未来发挥更加重要的作用。', 'In recent years, China’s digital economy has continued to expand in scale and has become an important engine driving economic growth. New-generation information technologies such as big data, cloud computing and artificial intelligence are widely applied in fields including manufacturing, health care, finance and logistics. The digital economy has not only given birth to new business forms such as e-commerce and online education, but also greatly improved the productivity of traditional industries. Experts point out that with the widespread adoption of 5G networks, the digital economy will play an even more important role in the future.', '“人工智能”artificial intelligence（缩写 AI）；“大数据”big data，都不用复数。', '[{"en":"digital economy","zh":"数字经济"},{"en":"cloud computing","zh":"云计算"},{"en":"logistics","zh":"物流"},{"en":"give birth to","zh":"催生"},{"en":"productivity","zh":"生产效率"}]', '["“已成为……引擎”用 has become an engine driving growth，现在分词作后置定语。","“被广泛应用于”用 be widely applied in，in 后接领域。","“随着……的普及”用 with the widespread adoption/use of，with 表伴随。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-058', 'CET6', 'paragraph', '3', '六级翻译真题·汉字', '汉字是世界上最古老的文字之一，也是唯一沿用至今的表意文字。传说汉字由仓颉所创，现存最早的成熟汉字是三千多年前的甲骨文。汉字不仅是记录汉语的书写符号，也是中华文明的重要载体。汉字书法更是一门独特的艺术，被誉为“无言的诗、无行的舞”。如今，随着中国国际影响力的提升，全球学习汉字的人数不断增加。', 'Chinese characters are among the oldest writing systems in the world and the only ideographic script still in use today. Legend has it that Chinese characters were created by Cangjie, and the earliest mature Chinese characters extant are the oracle bone inscriptions from more than three thousand years ago. Chinese characters are not only the written symbols used to record the Chinese language, but also an important carrier of Chinese civilization. Calligraphy, in particular, is a unique art, honoured as “silent poetry and motionless dance”. Today, as China’s international influence grows, the number of people learning Chinese characters around the world keeps increasing.', '“甲骨文”oracle bone inscriptions；“表意文字”ideographic script，注意拼写。', '[{"en":"Chinese character","zh":"汉字"},{"en":"ideographic","zh":"表意的"},{"en":"oracle bone inscription","zh":"甲骨文"},{"en":"carrier","zh":"载体"},{"en":"calligraphy","zh":"书法"}]', '["“唯一沿用至今的”用 the only … still in use，in use 为固定短语。","“传说……”用 Legend has it that …，that 引导同位语从句。","“随着……的提升”用 as + 从句（as China’s influence grows）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-059', 'CET6', 'paragraph', '3', '六级翻译真题·四大发明', '造纸术、印刷术、火药和指南针是中国古代的四大发明，对世界文明的发展产生了深远影响。造纸术和印刷术大大降低了书籍的成本，使知识得以广泛传播；火药改变了战争的方式；指南针则为远洋航行提供了可能。英国哲学家培根曾指出，这三项发明改变了整个世界的面貌。四大发明是中华民族对世界文明作出的卓越贡献。', 'Papermaking, printing, gunpowder and the compass are the Four Great Inventions of ancient China, which have exerted a profound influence on the development of world civilization. Papermaking and printing greatly reduced the cost of books, enabling knowledge to be spread far and wide; gunpowder changed the way wars were fought; and the compass made ocean-going navigation possible. The British philosopher Bacon once noted that these inventions had changed the face of the whole world. The Four Great Inventions are an outstanding contribution made by the Chinese nation to world civilization.', '“四大发明”固定译 the Four Great Inventions，首字母大写；指南针前加 the。', '[{"en":"gunpowder","zh":"火药"},{"en":"compass","zh":"指南针"},{"en":"exert an influence on","zh":"对……产生影响"},{"en":"navigation","zh":"航行"},{"en":"outstanding","zh":"卓越的"}]', '["“对……产生影响”用 exert/have an influence on，on 是介词。","“使……得以……”用 enabling knowledge to be spread，现在分词作结果状语。","“为……提供可能”用 make sth. possible / provide the possibility for sth.。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-060', 'CET6', 'paragraph', '3', '六级翻译真题·唐诗', '唐诗是中国文学史上最辉煌的篇章之一，代表了中国古代诗歌的最高成就。唐代三百年间，涌现出李白、杜甫、白居易等一大批杰出诗人，流传至今的诗作近五万首。唐诗题材广泛，风格各异：李白的诗想象奇特、气势磅礴，杜甫的诗沉郁顿挫、忧国忧民。唐诗不仅在中国家喻户晓，也深刻影响了日本、韩国等周边国家的文学。', 'Tang poetry is one of the most brilliant chapters in the history of Chinese literature and represents the highest achievement of ancient Chinese poetry. During the three hundred years of the Tang Dynasty, a large number of outstanding poets emerged, including Li Bai, Du Fu and Bai Juyi, and nearly fifty thousand poems have been handed down to the present day. Tang poetry covers a wide range of themes and varies greatly in style: Li Bai’s poems are marked by extraordinary imagination and majestic vigour, while Du Fu’s are characterised by a sombre, restrained tone and deep concern for the country and its people. Tang poetry is not only widely known in China, but has also profoundly influenced the literature of neighbouring countries such as Japan and Korea.', '“唐诗”Tang poetry；“家喻户晓”widely known / known to every household。', '[{"en":"emerge","zh":"涌现"},{"en":"hand down","zh":"流传"},{"en":"majestic","zh":"气势磅礴的"},{"en":"sombre","zh":"沉郁的"},{"en":"profoundly","zh":"深刻地"}]', '["“涌现出”用 emerge（不及物）或 there emerged …，不用被动。","“流传至今”用 be handed down to the present day，常用现在完成时。","对比两事物时可用 while 连接并列分句，表示“而”。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-061', 'CET6', 'paragraph', '3', '六级翻译真题·2019年12月（高等教育）', '过去几十年，中国高等教育实现了从精英教育到大众化的历史性跨越。高校数量和在校生规模持续增长，高等教育毛入学率已超过60%。与此同时，国家加大了对中西部地区高校的扶持力度，努力缩小区域间的教育差距。越来越多的中国高校进入世界一流大学行列，科研水平和国际影响力显著提升。', 'Over the past few decades, China’s higher education has accomplished a historic leap from elite education to mass education. The number of universities and the scale of enrolment have kept expanding, and the gross enrolment ratio of higher education has exceeded 60 per cent. Meanwhile, the state has increased its support for universities in the central and western regions, striving to narrow the educational gap between regions. A growing number of Chinese universities have entered the ranks of world-class institutions, with their research capability and international influence significantly enhanced.', '“毛入学率”gross enrolment ratio；“双一流”可译 Double First-Class（世界一流大学和一流学科）。', '[{"en":"higher education","zh":"高等教育"},{"en":"enrolment","zh":"招生；入学"},{"en":"exceed","zh":"超过"},{"en":"narrow the gap","zh":"缩小差距"},{"en":"world-class","zh":"世界一流的"}]', '["“从……到……的跨越”用 a leap from A to B，from 与 to 须对称。","“努力缩小差距”用 striving to narrow the gap，现在分词作目的状语。","“随着……提升”用 with + 名词 + 过去分词（with … enhanced），即 with 复合结构。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-062', 'CET6', 'paragraph', '3', '六级翻译真题·人口老龄化', '中国正快速步入老龄化社会，60岁及以上人口已超过2.9亿。老龄化一方面得益于医疗条件改善和人均寿命延长，另一方面也与长期较低的生育率有关。为应对这一挑战，政府正在完善养老保险和医疗服务体系，并鼓励发展社区养老和居家养老。如何让老年人安享晚年，已成为全社会共同关注的话题。', 'China is rapidly becoming an ageing society, with the population aged 60 and above exceeding 290 million. Ageing is attributable, on the one hand, to improved medical conditions and longer life expectancy, and, on the other hand, to the persistently low birth rate. To meet this challenge, the government is improving the pension insurance and medical service systems, and encouraging the development of community-based and home-based elderly care. How to enable the elderly to enjoy their later years in comfort has become a topic of common concern to the whole society.', '“60岁及以上”the population aged 60 and above；“居家养老”home-based elderly care。', '[{"en":"ageing society","zh":"老龄化社会"},{"en":"life expectancy","zh":"预期寿命"},{"en":"birth rate","zh":"生育率"},{"en":"pension insurance","zh":"养老保险"},{"en":"elderly care","zh":"养老"}]', '["“一方面……另一方面……”用 on the one hand … on the other hand …，后者中的 on the 可保留。","“得益于/归因于”用 be attributable to，to 是介词，后接名词或动名词。","“让某人做某事”用 enable sb. to do，不可用 let sb. do 的正式度替代。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-063', 'CET6', 'paragraph', '3', '六级翻译真题·生态文明建设', '生态文明建设是关系中华民族永续发展的根本大计。过去十年，中国以前所未有的力度推进环境保护，空气质量显著改善，可再生能源装机容量稳居世界第一。中国已明确提出力争2030年前实现碳达峰、2060年前实现碳中和的目标。这不仅体现了中国应对气候变化的决心，也为全球生态治理贡献了中国方案。', 'The development of an ecological civilization is fundamental to the sustainable development of the Chinese nation. Over the past decade, China has promoted environmental protection with unprecedented intensity: air quality has improved markedly, and its installed capacity of renewable energy ranks first in the world. China has clearly set the goal of striving to peak carbon dioxide emissions before 2030 and achieve carbon neutrality before 2060. This not only demonstrates China’s determination to tackle climate change, but also contributes a Chinese solution to global ecological governance.', '“碳达峰”peak carbon dioxide emissions；“碳中和”carbon neutrality，均为官方译法。', '[{"en":"ecological civilization","zh":"生态文明"},{"en":"sustainable","zh":"可持续的"},{"en":"unprecedented","zh":"前所未有的"},{"en":"carbon neutrality","zh":"碳中和"},{"en":"governance","zh":"治理"}]', '["“关系……的根本大计”用 be fundamental to，to 是介词。","“明确提出……目标”用 set the goal of doing，of 后接动名词。","“不仅……也……”连接两个谓语，注意时态与人称一致。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-064', 'CET6', 'paragraph', '3', '六级翻译真题·深海探测', '中国深海探测技术近年来取得重大突破。2012年，“蛟龙号”载人潜水器下潜至7062米，创造了同类作业型潜水器的世界纪录。2020年，“奋斗者号”成功坐底马里亚纳海沟，深度超过一万米，标志着中国具备了进入世界海洋最深处的能力。深海探测不仅有助于人类认识海洋、开发资源，也为研究地球演化和生命起源提供了宝贵样本。', 'China has made major breakthroughs in deep-sea exploration technology in recent years. In 2012, the manned submersible Jiaolong descended to a depth of 7,062 metres, setting a world record for operational submersibles of its kind. In 2020, the Fendouzhe successfully reached the bottom of the Mariana Trench at a depth of over ten thousand metres, marking China’s capability to access the deepest point of the world’s oceans. Deep-sea exploration not only helps humanity understand the oceans and exploit their resources, but also provides valuable samples for research into the evolution of the earth and the origin of life.', '“蛟龙号”Jiaolong；“奋斗者号”Fendouzhe；“马里亚纳海沟”the Mariana Trench，加 the。', '[{"en":"breakthrough","zh":"突破"},{"en":"submersible","zh":"潜水器"},{"en":"trench","zh":"海沟"},{"en":"exploit","zh":"开发"},{"en":"origin of life","zh":"生命起源"}]', '["“取得重大突破”用 make major breakthroughs in，in 后接领域。","“创造了……纪录”用 setting a world record for，现在分词作结果状语。","“标志着……”用 marking …，现在分词补充说明主句结果。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-065', 'CET6', 'paragraph', '3', '六级翻译真题·电商与乡村振兴', '电子商务的普及为乡村发展注入了新的活力。在许多偏远地区，农民通过直播带货把特色农产品直接卖给全国消费者，收入大幅提高。与此同时，物流网络的延伸和移动支付的普及，使农村电商得以快速发展。电商不仅拓宽了农产品销路，还吸引了一批年轻人返乡创业，为乡村振兴提供了人才支撑。', 'The spread of e-commerce has injected new vitality into rural development. In many remote areas, farmers sell their speciality agricultural products directly to consumers across the country through livestreaming, substantially increasing their incomes. At the same time, the extension of logistics networks and the widespread use of mobile payment have enabled rural e-commerce to grow rapidly. E-commerce has not only broadened the market for agricultural products, but also attracted a number of young people to return to their hometowns to start businesses, providing talent support for rural revitalization.', '“直播带货”livestream marketing / selling through livestreaming；“乡村振兴”rural revitalization。', '[{"en":"inject vitality into","zh":"为……注入活力"},{"en":"livestreaming","zh":"直播带货"},{"en":"substantially","zh":"大幅度地"},{"en":"extension","zh":"延伸"},{"en":"rural revitalization","zh":"乡村振兴"}]', '["“使……得以发展”用 enable … to grow，enable 后接复合宾语。","“不仅……还……”连接两个谓语，用现在完成时保持时态一致。","“为……提供支撑”用 providing support for，现在分词作伴随状语。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-066', 'CET6', 'paragraph', '3', '六级翻译真题·中国山水画', '中国山水画是传统绘画中最具代表性的门类，讲究“以形写神，形神兼备”。与西方风景画注重写实不同，中国山水画更强调画家主观情感的抒发和意境的营造。画家常以留白表现云雾与流水，以简练的笔墨勾勒山川轮廓。欣赏中国山水画，不只是观赏景色，更是体会画家的人生境界与哲学思考。', 'Chinese landscape painting is the most representative genre of traditional Chinese painting, which pursues “depicting the spirit through form, with both form and spirit fully conveyed”. Unlike Western landscape painting, which emphasizes realism, Chinese landscape painting lays greater stress on the expression of the painter’s subjective feelings and the creation of an artistic conception. Painters often use blank space to suggest clouds, mist and flowing water, and outline mountains and rivers with economical brushwork. Appreciating Chinese landscape painting is not merely viewing scenery, but rather experiencing the painter’s vision of life and philosophical reflection.', '“形神兼备”常译 unity of form and spirit；“留白”也可用 leaving blank / void。', '[{"en":"landscape painting","zh":"山水画"},{"en":"genre","zh":"门类；体裁"},{"en":"artistic conception","zh":"意境"},{"en":"blank space","zh":"留白"},{"en":"brushwork","zh":"笔墨；笔法"}]', '["“与……不同”用 Unlike + 名词（短语），后接主句，不用连接词。","“注重/强调”用 lay stress on / emphasize，on 是介词。","“不只是……更是……”用 not merely … but rather …，表对照而非递进。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-067', 'CET6', 'sentence', '2', '六级翻译·高级句型（分词作状语）', '考虑到天气状况，组织者决定将比赛推迟到下周末举行。', 'Considering the weather conditions, the organizers decided to postpone the match until next weekend.', '分词作状语时，若逻辑主语与主句不一致即为垂悬分词，是常见错误。', '[{"en":"considering","zh":"考虑到"},{"en":"postpone","zh":"推迟"},{"en":"until","zh":"直到"}]', '["现在分词短语 Considering … 作原因状语，其逻辑主语须与主句主语一致。","“推迟到……”用 postpone … until/to，until 后接时间点。","“决定做某事”用 decide to do，不用 decide doing。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-068', 'CET6', 'sentence', '3', '六级翻译·高级句型（同位语从句）', '毫无疑问，教育公平是社会稳定的重要基础。', 'There is no doubt that educational equity is an important foundation of social stability.', '同位语从句 that 不作成分且不能省；定语从句 that 作成分、作宾语时可省。', '[{"en":"no doubt","zh":"毫无疑问"},{"en":"educational equity","zh":"教育公平"},{"en":"foundation","zh":"基础"},{"en":"stability","zh":"稳定"}]', '["“毫无疑问”用 There is no doubt that …，that 引导同位语从句，不可省略。","“……的基础”用 the foundation of，of 表所属关系。","抽象名词后常用 that 引导同位语从句：fact, doubt, evidence, belief, idea。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-069', 'CET6', 'sentence', '3', '六级翻译·高级句型（with 复合结构）', '随着越来越多的年轻人涌向城市，许多乡村学校不得不关闭。', 'With more and more young people flooding into cities, many rural schools have been forced to close.', 'with 复合结构的三种形式：with + n. + doing / done / 介词短语。', '[{"en":"flood into","zh":"涌入"},{"en":"rural","zh":"乡村的"},{"en":"be forced to","zh":"不得不；被迫"}]', '["with 复合结构：With + 宾语 + 现在分词，表示伴随原因。","“被迫做某事”用 be forced to do，force 用被动语态。","“越来越多”用 more and more 或 an increasing number of。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-070', 'CET6', 'sentence', '3', '六级翻译·高级句型（让步与转折）', '尽管面临资金不足和技术难题，研究团队仍然按时完成了任务。', 'Despite the lack of funding and the technical difficulties, the research team still completed the task on schedule.', 'despite = in spite of（介词短语）；although/though 是从属连词，后接从句。', '[{"en":"despite","zh":"尽管"},{"en":"lack of","zh":"缺乏"},{"en":"funding","zh":"资金"},{"en":"on schedule","zh":"按时"}]', '["Despite 是介词，后接名词短语；后面若接句子须用 Although/Though。","“缺乏……”用 the lack of，lack 作名词时前加 the，后接 of。","“按时”用 on schedule / on time，介词用 on。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-071', 'CET6', 'sentence', '2', '六级翻译·高级句型（主语从句）', '他能否按时完成任务，将直接影响整个项目的进度。', 'Whether he can complete the task on time will directly affect the progress of the whole project.', 'if 引导的主语从句不能置于句首，只能用 whether；宾语从句中两者皆可。', '[{"en":"whether","zh":"是否"},{"en":"on time","zh":"按时"},{"en":"affect","zh":"影响"},{"en":"progress","zh":"进度"}]', '["Whether 引导主语从句，置于句首时不可用 if 替换。","主语从句作主语时，谓语动词通常用单数。","“影响”用 affect（动词）或 have an effect on（短语），注意区分 effect（名词）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-072', 'CET6', 'sentence', '2', '六级翻译·高级句型（条件从句）', '除非我们立即采取行动，否则情况只会变得更糟。', 'Unless we take immediate action, the situation will only get worse.', 'unless 从句中不能再用 and；也不可说 unless … not，属双重否定错误。', '[{"en":"unless","zh":"除非"},{"en":"take action","zh":"采取行动"},{"en":"situation","zh":"情况"}]', '["Unless = if … not，本身已含否定意义，句中不可再加 not。","条件状语从句用一般现在时表将来，主句用一般将来时。","“变得更糟”用 get worse / become worse，worse 是 badly/ill 的比较级。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-073', 'CET6', 'sentence', '3', '六级翻译·高级句型（倍数表达）', '这座新建的体育馆的面积是原来那座的三倍。', 'The newly built stadium is three times as large as the original one.', '常见倍数句型：twice as much as / three times the size of / four times larger than。', '[{"en":"stadium","zh":"体育馆"},{"en":"three times","zh":"三倍"},{"en":"as large as","zh":"和……一样大"},{"en":"original","zh":"原来的"}]', '["倍数表达法一：A + be + 倍数 + as + 形容词原级 + as + B。","倍数表达法二：A + be + 倍数 + 比较级 + than + B（three times larger than）。","“三倍”用 three times，不可用 three times of。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-074', 'CET6', 'sentence', '3', '六级翻译·高级句型（部分否定）', '并非所有学生都赞成这个方案，有些人担心它会占用太多时间。', 'Not all students are in favour of this plan; some are worried that it will take up too much time.', '部分否定 vs 全部否定：Not all（部分）≠ None（全部）；Not both ≠ Neither。', '[{"en":"not all","zh":"并非所有"},{"en":"in favour of","zh":"赞成"},{"en":"take up","zh":"占用"}]', '["Not all … 表示部分否定，意为“并非全部……”，不等于全部否定。","全部否定须用 None of … / No …，如 None of the students agreed。","“担心”后接 that 从句，也可说 be worried about + 名词。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-075', 'CET6', 'sentence', '3', '六级翻译·高级句型（形式宾语）', '互联网的普及使我们更容易获取最新的信息。', 'The widespread use of the Internet has made it easier for us to obtain the latest information.', '常见形式宾语动词：make, find, think, consider, feel + it + 宾补 + to do/that 从句。', '[{"en":"widespread","zh":"广泛的"},{"en":"obtain","zh":"获取"},{"en":"the latest","zh":"最新的"}]', '["形式宾语结构：make it + 宾补 + to do，it 代替后面的真正宾语不定式。","“使我们更容易”用 make it easier for us，介词 for 引出不定式的逻辑主语。","“最新的”用 the latest，不可用 the newest（newest 指新旧，latest 指时间最近）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-076', 'CET6', 'sentence', '3', '六级翻译·高级句型（独立主格）', '会议结束后，代表们陆续离开了会场。', 'The meeting being over, the delegates left the conference hall one after another.', '独立主格常见形式：n. + doing / done / adj. / 介词短语，如 Weather permitting, …', '[{"en":"delegate","zh":"代表"},{"en":"one after another","zh":"陆续；一个接一个"},{"en":"conference hall","zh":"会场"}]', '["独立主格结构：名词 + 现在分词（The meeting being over），其逻辑主语独立于主句。","独立主格前不加连词，常用逗号与主句隔开。","“陆续”用 one after another / one by one，注意 another 与 by 的搭配。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-077', 'CET4', 'sentence', '1', '四级翻译·基础句型（there be）', '过去这个村庄里只有一所小学，现在已经有好几所了。', 'There used to be only one primary school in this village, but now there are several.', 'there used to be 与 there was 的区别：前者强调“曾经有过（现在没了）”。', '[{"en":"there used to be","zh":"过去曾经有"},{"en":"primary school","zh":"小学"},{"en":"several","zh":"几个"}]', '["“过去曾经有”用 there used to be，used to 后接动词原形。","there be 句型中 be 的数由后面的名词决定：one school 用 was/单数。","表示转折用 but 连接两个并列分句。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-078', 'CET4', 'sentence', '2', '四级翻译·基础句型（因果关系）', '由于准备充分，他在面试中表现得非常自信。', 'Thanks to his thorough preparation, he performed with great confidence in the interview.', '表原因的介词短语：because of, due to, owing to, thanks to（多含褒义）。', '[{"en":"thanks to","zh":"由于；多亏"},{"en":"thorough","zh":"充分的；彻底的"},{"en":"confidence","zh":"自信"},{"en":"interview","zh":"面试"}]', '["Thanks to 表示正面原因，多译为“多亏”；表负面原因用 because of / due to。","“表现得自信”用 perform with confidence，with 引出伴随状态。","“在面试中”用 in the interview，介词用 in。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-079', 'CET4', 'sentence', '1', '四级翻译·写作衔接专项（段落层次连接词 first/second/third）', '请按 first … second … third 的顺序组织，翻译：首先，健康是最重要的；其次，没有健康我们无法工作；第三，我们应该每天锻炼。', 'First, health is the most important thing. Second, without health we cannot work. Third, we should exercise every day.', '讲义原话：「以上结构序数词不要混用，保持结构对应和工整」。', '[{"en":"first","zh":"首先"},{"en":"second","zh":"其次"},{"en":"third","zh":"第三"},{"en":"health","zh":"健康"},{"en":"exercise","zh":"锻炼"}]', '["同一组序数连接词必须结构对应、不能混用：first/second/third 是一组，firstly/secondly/thirdly 是另一组。","连接词置于句首时后面通常加逗号，再接完整句子。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-080', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（段落层次连接词 firstly/secondly/thirdly/finally）', '请用 firstly … secondly … thirdly … finally 的递进结构，翻译：首先，阅读能增长知识；其次，它能提高写作能力；第三，它有助于培养耐心；最后，它会让生活更充实。', 'Firstly, reading can increase our knowledge. Secondly, it can improve our writing ability. Thirdly, it helps develop patience. Finally, it makes life more fulfilling.', '递进结构写作文时最稳：条目数固定、词形统一，阅卷人一眼能看出逻辑层次。', '[{"en":"firstly","zh":"首先"},{"en":"secondly","zh":"其次"},{"en":"thirdly","zh":"第三"},{"en":"finally","zh":"最后"},{"en":"patience","zh":"耐心"}]', '["-ly 序数系列与 first/second 系列不可混用，四个连接词须按序排列以体现递进。","help 后接动词原形或动名词均可：helps develop / helps to develop / helps developing。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-081', 'CET4', 'paragraph', '2', '四级翻译·写作衔接专项（段落层次连接词 to begin with/then/furthermore/finally）', '请用 to begin with … then … furthermore … finally 组织段落，翻译：要提高英语水平，首先要坚持每天背单词；然后要多听多说；此外还应大量阅读英文材料；最后，最好能找机会与英语母语者交流。', 'To begin with, you should keep memorizing words every day if you want to improve your English. Then, you need to listen and speak more. Furthermore, you should read a large amount of English materials. Finally, it is better to find chances to communicate with native speakers.', 'then 与 furthermore 属于不同强度的递进，then 表顺承、furthermore 表追加，顺序不要颠倒。', '[{"en":"to begin with","zh":"首先"},{"en":"furthermore","zh":"此外"},{"en":"finally","zh":"最后"},{"en":"native speakers","zh":"母语者"}]', '["to begin with 是固定短语，不可写成 to begin，也不可改成 to beginning with。","a large amount of 修饰不可数名词（materials 此处作不可数），a large number of 才接可数名词复数。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-082', 'CET4', 'paragraph', '2', '四级翻译·写作衔接专项（段落层次连接词 to start with/next/in addition/finally）', '请用 to start with … next … in addition … finally 翻译：首先，政府应加大教育投入；接下来，学校要改进课程设置；此外，家长也应参与其中；最后，学生自己必须付出努力。', 'To start with, the government should increase investment in education. Next, schools should improve their courses. In addition, parents should also get involved. Finally, students themselves must make efforts.', '讲义把 to start with / next / in addition / finally 归为一组，与 to begin with / then / furthermore 那组属同义替换。', '[{"en":"to start with","zh":"首先"},{"en":"in addition","zh":"此外"},{"en":"finally","zh":"最后"},{"en":"investment","zh":"投入、投资"},{"en":"get involved","zh":"参与其中"}]', '["in addition 是副词性连接词，后面直接加逗号接句子；in addition to 才是介词短语，须接名词。","themselves 是反身代词，用于强调「学生自己」，不可省略。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-083', 'CET6', 'paragraph', '3', '六级翻译·写作衔接专项（段落层次连接词 first and foremost/besides/last but not least）', '请用 first and foremost … besides … last but not least 翻译：最重要的是，我们必须保护环境；此外，节约能源同样重要；最后但同样重要的是，每个人都应从自己做起。', 'First and foremost, we must protect the environment. Besides, saving energy is equally important. Last but not least, everyone should start with himself.', 'first and foremost 比 first 语气更重，适合放在首段第一句定调。', '[{"en":"first and foremost","zh":"最重要的是"},{"en":"besides","zh":"此外"},{"en":"last but not least","zh":"最后但同样重要的是"},{"en":"environment","zh":"环境"}]', '["last but not least 是固定搭配，不能写成 last but not the least。","besides 表「另外还有」（递进），beside 意为「在……旁边」，拼写相近但词义完全不同。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-084', 'CET6', 'paragraph', '3', '六级翻译·写作衔接专项（段落层次连接词 most important of all/moreover/finally）', '请用 most important of all … moreover … finally 翻译：最重要的是，教育决定一个国家的未来；此外，它还能促进经济发展；最后，教育有助于减少贫困。', 'Most important of all, education determines the future of a country. Moreover, it can promote economic development. Finally, education helps reduce poverty.', 'moreover 比 besides 更书面，议论文里用来追加同向论据。', '[{"en":"most important of all","zh":"最重要的是"},{"en":"moreover","zh":"此外"},{"en":"finally","zh":"最后"},{"en":"poverty","zh":"贫困"}]', '["most important of all 是插入性的独立成分，不加 that，其后用逗号与主句隔开。","determine 意为「决定」，与 decide（决定做某事）用法不同。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-085', 'CET4', 'paragraph', '2', '四级翻译·写作衔接专项（段落层次连接词 on the one hand/on the other hand）', '请用 on the one hand … on the other hand 翻译：一方面，手机让沟通变得更加方便；另一方面，过度使用手机会影响健康。', 'On the one hand, mobile phones make communication more convenient. On the other hand, using them too much may affect our health.', '这组用于「同一事物的两个侧面」，若前后是相反事实，应改用 in contrast 或 on the contrary。', '[{"en":"on the one hand","zh":"一方面"},{"en":"on the other hand","zh":"另一方面"},{"en":"convenient","zh":"方便的"},{"en":"health","zh":"健康"}]', '["on the one hand 与 on the other hand 必须成对出现，分属两句或两个分句。","on the other hand 不能缩写成 on other hand；also 可加可不加（on the other hand, also…）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-086', 'CET4', 'paragraph', '2', '四级翻译·写作衔接专项（段落层次连接词 for one thing/for another thing）', '请用 for one thing … for another thing 翻译：一方面，这项政策能创造就业机会；另一方面，它能提高人们的生活水平。', 'For one thing, this policy can create jobs. For another thing, it can raise people''s living standards.', '议论文中这两组衔接可互换，但同一次写作里只选一组，避免混用。', '[{"en":"for one thing","zh":"一方面"},{"en":"for another thing","zh":"另一方面"},{"en":"policy","zh":"政策"},{"en":"living standards","zh":"生活水平"}]', '["for one thing 与 for another thing 成对使用，语气比 on the one hand 更口语、更口语化。","people''s 是所有格，缺撇号或撇号位置错误均属拼写错误。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-087', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（总括过渡词 as far as I am concerned）', '请用 as far as I am concerned 翻译：就我而言，大学生应该多参加社会实践活动。', 'As far as I am concerned, college students should take part in more social practice activities.', '这组属于「总括过渡词」，用来自然引出个人观点，比 I think 更书面。', '[{"en":"as far as I am concerned","zh":"就我而言"},{"en":"take part in","zh":"参加"},{"en":"social practice","zh":"社会实践"}]', '["as far as I am concerned 是固定表达，be 动词用 am（主语 I），不能写成 is。","take part in 强调参加活动并起作用，attend 强调出席，join 强调加入组织。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-088', 'CET4', 'sentence', '1', '四级翻译·写作衔接专项（总括过渡词 generally speaking）', '请用 generally speaking 翻译：一般来说，早起的人工作效率更高。', 'Generally speaking, people who get up early are more efficient at work.', '同类总括过渡词还有 practically speaking、strictly speaking，可作同义替换。', '[{"en":"generally speaking","zh":"一般来说"},{"en":"efficient","zh":"高效的"}]', '["generally speaking 是分词短语作独立成分，逻辑主语与主句一致时使用；若不一致须改为从句。","who get up early 是定语从句修饰 people，谓语用 are 与先行词 people 保持一致。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-089', 'CET6', 'sentence', '2', '六级翻译·写作衔接专项（同类过渡词 similarly）', '请用 similarly 翻译：这座城市的公共交通十分便利；同样，它的自行车道系统也相当完善。', 'The public transport in this city is very convenient. Similarly, its bike lane system is quite well developed.', '讲义「同类过渡词」还有 equally important、namely、that is，用于解释或并列同类信息。', '[{"en":"similarly","zh":"同样地"},{"en":"public transport","zh":"公共交通"},{"en":"convenient","zh":"便利的"}]', '["similarly 表「同理、同样」，用于引入与上文同类的情况；likewise 与之同义。","public transport 是英式说法，美式为 public transportation，两者均可。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-090', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（对比过渡词 in contrast）', '请用 in contrast 翻译：城市里的生活节奏很快；相比之下，乡村生活要悠闲得多。', 'The pace of life in cities is very fast. In contrast, life in the countryside is much more relaxed.', 'in contrast 后若要接比较对象，用 in contrast to / with。', '[{"en":"in contrast","zh":"相比之下"},{"en":"pace of life","zh":"生活节奏"},{"en":"countryside","zh":"乡村"},{"en":"relaxed","zh":"悠闲的"}]', '["in contrast 用于客观对比两者的差异，前后是两个相对立的事实；on the contrary 则用于否定前句并给出相反情况。","much more relaxed 中 much 修饰比较级，不能用 very 修饰比较级。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-091', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（对比过渡词 on the contrary）', '请用 on the contrary 翻译：这项措施并不会增加成本；恰恰相反，它能节省大量资金。', 'This measure will not increase the cost. On the contrary, it can save a large amount of money.', '这是四六级写作最常被误用的一组衔接，判断标准：前句是不是被「否定」了。', '[{"en":"on the contrary","zh":"恰恰相反"},{"en":"measure","zh":"措施"},{"en":"cost","zh":"成本"}]', '["on the contrary 用于否定前述说法并给出相反事实；in contrast 用于并列对比差异，二者不可互换。","a large amount of 接不可数名词（money），a large number of 接可数名词复数。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-092', 'CET6', 'sentence', '2', '六级翻译·写作衔接专项（转折过渡词 nevertheless）', '请用 nevertheless 翻译：这个项目面临许多风险；然而，我们不应放弃努力。', 'This project faces many risks. Nevertheless, we should not give up our efforts.', 'nevertheless 比 however 更正式，在六级作文中用来表现「让步后的转折」。', '[{"en":"nevertheless","zh":"然而"},{"en":"risks","zh":"风险"},{"en":"give up","zh":"放弃"}]', '["nevertheless 是副词，前后用句号或分号连接两个句子；不可像 but 那样直接连接两个分句。","give up 后接动名词或名词：give up trying / give up our efforts。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-093', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（转折过渡词 however）', '请用 however 翻译：这项技术已经相当成熟；然而，它的成本仍然很高。', 'This technology is already quite mature. However, its cost is still very high.', '转折类过渡词还有 yet、whereas、otherwise、despite，注意 whereas 是连词、despite 是介词。', '[{"en":"however","zh":"然而"},{"en":"mature","zh":"成熟的"},{"en":"cost","zh":"成本"}]', '["however 作副词表转折时前后用标点隔开；作连词时 however + 形容词/副词 = no matter how，如 however hard he tried。","quite 修饰形容词表示「相当」，与 very 程度相当但语气略弱。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-094', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（举例过渡词 for example）', '请用 for example 翻译：许多传统手艺正面临失传的风险；例如，会制作油纸伞的手艺人已经越来越少。', 'Many traditional crafts are facing the risk of dying out. For example, there are fewer and fewer craftsmen who can make oil-paper umbrellas.', '讲义把「举例过渡词」还列为 a case in point is that、as an illustration，后者更书面。', '[{"en":"for example","zh":"例如"},{"en":"traditional crafts","zh":"传统手艺"},{"en":"risk","zh":"风险"}]', '["for example 后接句子，for instance 与之同义；such as 后接名词或名词短语，不能接完整句子。","there are fewer and fewer 是「越来越少」的地道表达，注意比较级叠加结构。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-095', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（举例过渡词 a case in point is that）', '请用 a case in point is that 翻译：发展新能源能有效减少污染；一个典型的例子就是电动汽车的迅速普及。', 'Developing new energy can effectively reduce pollution. A case in point is that electric cars are becoming increasingly popular.', '配套表达：as an illustration, …；to illustrate, …。', '[{"en":"a case in point is that","zh":"一个典型的例子是"},{"en":"reduce pollution","zh":"减少污染"},{"en":"electric cars","zh":"电动汽车"}]', '["a case in point 意为「恰如其分的例子」，后接 is that 引导表语从句，写作中比 for example 更高级。","动名词短语 Developing new energy 作主语时，谓语动词用单数 can。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-096', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（原因过渡词 owing to）', '请用 owing to 翻译：由于天气恶劣，昨天的所有航班都被取消了。', 'Owing to the bad weather, all the flights yesterday were cancelled.', '讲义「原因过渡词」共 10 个：due to、considering、as a result of、given、in that、in the view of、on account of、on the grounds of、owing to、seeing that。', '[{"en":"owing to","zh":"由于"},{"en":"bad weather","zh":"恶劣的天气"},{"en":"cancelled","zh":"取消"}]', '["owing to、due to、because of 都是介词短语，后接名词或名词短语，不能接完整句子。","flights 是被取消的，故用被动语态 were cancelled。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-097', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（原因过渡词 due to）', '请用 due to 翻译：由于技术进步，这些设备的价格大幅下降了。', 'Due to technological progress, the prices of these devices have dropped sharply.', 'due to 与 owing to 可互换；但 due to 更常用于书面，owing to 更中性。', '[{"en":"due to","zh":"由于"},{"en":"technological progress","zh":"技术进步"},{"en":"devices","zh":"设备"}]', '["due to 在传统语法中作表语（The delay was due to…），现代英语中作状语也已广泛接受。","have dropped 用现在完成时，强调「已经发生的下降对现在的影响」。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-098', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（原因过渡词 on the grounds of）', '请用 on the grounds of 翻译：由于安全原因，这条道路暂时封闭。', 'On the grounds of safety, this road is temporarily closed.', 'grounds 恒用复数，on the ground of 也可接受，但 on the grounds that + 从句更常见。', '[{"en":"on the grounds of","zh":"由于、基于……理由"},{"en":"safety","zh":"安全"},{"en":"temporarily","zh":"暂时地"}]', '["on the grounds of 表示「以……为理由」，比 because of 更正式，多用于法律、公告等文体。","temporarily 是副词修饰 closed，注意拼写：temporarily（不是 temporally）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-099', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（原因过渡词 seeing that）', '请用 seeing that 翻译：考虑到他已经尽了最大努力，我们不应再指责他。', 'Seeing that he has already tried his best, we should not blame him any more.', '这一组是六级写作提分点：用连词引导从句比用介词短语接名词更能显示句式能力。', '[{"en":"seeing that","zh":"考虑到"},{"en":"blame","zh":"指责"}]', '["seeing that 引导原因状语从句，与 considering that、given that 同义，都属连词。","not … any more 表「不再」，与之对应的 not … any longer 强调时间上的不再延续。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-100', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（让步过渡词 admittedly）', '请用 admittedly 翻译：诚然，互联网给我们的生活带来了便利，但它也带来了一些问题。', 'Admittedly, the Internet has brought convenience to our lives, but it has also brought some problems.', '让步过渡词还有 although、in spite of、even though、certainly、indeed，其中 in spite of 是介词短语。', '[{"en":"admittedly","zh":"诚然、无可否认"},{"en":"convenience","zh":"便利"},{"en":"problems","zh":"问题"}]', '["admittedly 是「先承认、再转折」的让步副词，常与 but 或 nevertheless 呼应。","bring sth to sb 表「给某人带来某物」，此处用 bring convenience to our lives。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
INSERT INTO translation_question (`id`, `level`, `type`, `difficulty`, `source`, `prompt`, `reference`, `tips`, `core_words`, `grammar_points`, `create_time`, `update_time`) VALUES
  ('tr-101', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（让步过渡词 even though）', '请用 even though 翻译：尽管他遇到了很多困难，他仍然坚持完成了这项研究。', 'Even though he met many difficulties, he still insisted on finishing the research.', '让步从句中不能再用 but：Even though he met many difficulties, he still… 是正确写法。', '[{"en":"even though","zh":"尽管"},{"en":"difficulties","zh":"困难"},{"en":"insisted on","zh":"坚持"}]', '["even though 引导让步状语从句，语气比 although 更强；though 可与 even 分开用（Even he though…不成立，注意语序）。","insist on 中 on 是介词，后接动名词 finishing，不能接动词原形。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-102', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（强调过渡词 needless to say）', '请用 needless to say 翻译：不言而喻，良好的教育对一个人的未来至关重要。', 'Needless to say, a good education is of great importance to a person''s future.', '强调过渡词还有 chiefly、even worse、most important of all、no doubt、particularly。', '[{"en":"needless to say","zh":"不言而喻"},{"en":"education","zh":"教育"},{"en":"great importance","zh":"至关重要"}]', '["be of great importance = be very important，of + 抽象名词 = 形容词，是六级高频书面表达。","a person''s future 中所有格撇号位置在 s 之前（单数名词）。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-103', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（强调过渡词 even worse）', '请用 even worse 翻译：这次事故发生得很突然；更糟糕的是，当时正下着大雨。', 'The accident happened very suddenly. Even worse, it was raining heavily at that time.', '写作中可用 What is worse 替换 even worse，句式更灵活。', '[{"en":"even worse","zh":"更糟糕的是"},{"en":"accident","zh":"事故"},{"en":"suddenly","zh":"突然地"}]', '["even worse 是「递进式强调」，用于在前述不利情况上再加一层。","was raining 用过去进行时，表示事故发生时正在持续的天气状态。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-104', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（目的过渡词 for the sake of）', '请用 for the sake of 翻译：为了下一代的健康，我们必须保护环境。', 'For the sake of the health of the next generation, we must protect the environment.', '目的过渡词还有 with the aim of、with the view to、for the purpose of，后接动名词。', '[{"en":"for the sake of","zh":"为了"},{"en":"next generation","zh":"下一代"},{"en":"protect the environment","zh":"保护环境"}]', '["for the sake of 后接名词或名词短语（for the sake of health），不能直接接句子。","the health of the next generation 是「of 所有格」，比 the next generation’s health 更正式。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-105', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（目的过渡词 with a view to）', '请用 with a view to 翻译：为了提高教学质量，学校引进了一批新设备。', 'With a view to improving the quality of teaching, the school has introduced a batch of new equipment.', '区分 with a view to doing（为了）与 in view of（鉴于），后者表原因。', '[{"en":"with a view to","zh":"为了"},{"en":"quality of teaching","zh":"教学质量"},{"en":"equipment","zh":"设备"}]', '["with a view to 中的 to 是介词，后接动名词 improving，不能接动词原形。","equipment 是不可数名词，没有复数形式 equipments，计量用 a piece of equipment。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-106', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（条件过渡词 as long as）', '请用 as long as 翻译：只要坚持练习，每个人的英语水平都能得到提高。', 'As long as you keep practising, everyone can improve their English.', '条件过渡词还有 given、provided that，其中 provided that 更书面。', '[{"en":"as long as","zh":"只要"},{"en":"keep practising","zh":"坚持练习"},{"en":"improve","zh":"提高"}]', '["as long as 引导条件状语从句，条件从句用一般现在时表将来，主句用情态动词或将来时。","keep doing 表「持续做某事」，keep on doing 语气更强。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-107', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（条件过渡词 provided that）', '请用 provided that 翻译：只要条件允许，我们就会继续推进这个计划。', 'Provided that conditions permit, we will continue to carry out this plan.', 'if 与 provided that 的差别：后者强调「以……为前提条件」，语气更正式。', '[{"en":"provided that","zh":"只要"},{"en":"conditions","zh":"条件"},{"en":"carry out","zh":"推进、执行"}]', '["provided that 等于 providing that，是正式的条件连词，多用于合同、公文与议论文。","carry out 表「执行、实施」，宾语是计划、政策、实验等。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-108', 'CET4', 'sentence', '2', '四级翻译·写作衔接专项（结论过渡词 in short）', '请用 in short 翻译：总之，只有通过不断努力，我们才能实现自己的目标。', 'In short, only through constant efforts can we achieve our goals.', '结论过渡词还有 in brief、in a word、to sum up、in summary，写作结尾可择优使用。', '[{"en":"in short","zh":"总之"},{"en":"constant efforts","zh":"不断努力"},{"en":"achieve","zh":"实现"}]', '["only 置于句首修饰状语时，主句须部分倒装：only through … can we achieve…。","constant 意为「持续不断的」，continuous 强调「不间断的」，二者语境有别。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-109', 'CET6', 'sentence', '2', '六级翻译·写作衔接专项（结论过渡词 as a result）', '请用 as a result 翻译：这家工厂长期排放污水；结果，附近的河流被严重污染了。', 'This factory had been discharging waste water for a long time. As a result, the nearby river was seriously polluted.', '结论过渡词 accordingly、consequently、hence、therefore 与 as a result 同类，写作中避免重复使用同一个。', '[{"en":"as a result","zh":"结果"},{"en":"waste water","zh":"污水"},{"en":"polluted","zh":"污染"}]', '["as a result 是副词性短语，后接结果；as a result of 才是介词短语，后接原因。","had been discharging 是过去完成进行时，强调在结果出现前该行为一直持续。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('tr-110', 'CET6', 'sentence', '3', '六级翻译·写作衔接专项（结论过渡词 on the whole）', '请用 on the whole 翻译：总的来说，这次活动取得了圆满成功。', 'On the whole, this activity was a complete success.', '讲义「结论过渡词」共 14 个，其中最常用的是 in conclusion、to sum up、on the whole、in brief。', '[{"en":"on the whole","zh":"总的来说"},{"en":"activity","zh":"活动"},{"en":"complete success","zh":"圆满成功"}]', '["on the whole 意为「总体上」（= in general），on the other hand 才是「另一方面」，形近但意义完全不同。","success 在此作可数名词，表示「一件成功的事」，故加 a。"]', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
