INSERT INTO paper_question (`id`, `paper_id`, `section_id`, `order_no`, `stem`, `options`, `answer`, `analysis`, `user_answer`, `done`, `favorite`, `create_time`, `update_time`) VALUES
  ('1', '1', '1', '1', 'Directions: For this part, you are allowed 30 minutes to write an essay on the use of short videos. You should write at least 120 words but no more than 180 words.', '[]', '参考范文：Nowadays short videos have become part of our daily life. Whenever we take a bus or wait in a queue, we can see people watching short videos on their phones. Some people welcome this trend, while others worry about its negative effects.
